(window.GIM_TS=window.GIM_TS||{})["Eruvin.3"]={"from":72,"a":[["\u0003אי אתה מודה\u0004 לפחות שיש לחשוש \u0003שמא יבקע הנוד, ונמצא שותה טבלים למפרע? אמר להן: לכשיבקע,\u0004 אני איני חושש לאפשרות זו.","\u0003ר' אליעזר אומר: יום טוב הסמוך לשבת, בין מלפניה\u0004 — ביום ששי, \u0003ובין לאחריה\u0004 — ביום ראשון: \u0003מערב אדם שני עירובין, ואומר: עירובי ב\u0004יום ה\u0003ראשון\u0004 לצד \u0003מזרח, וב\u0004יום ה\u0003שני למערב.\u0004 או \u0003בראשון למערב ובשני למזרח,\u0004 או שאומר: \u0003עירובי בראשון, ובשני\u0004 אהיה \u0003כבני עירי.\u0004 או שאומר: \u0003עירובי בשני, וב\u0004יום ה\u0003ראשון\u0004 אהיה \u0003כבני עירי.\u0004","\u0003וחכמים אומרים:\u0004 אי אפשר לחלק כך, אלא \u0003או מערב לרוח אחת, או אינו מערב כל עיקר. או מערב לשני ימים, או אינו מערב כל עיקר.\u0004","\u0003כיצד יעשה? מוליכו\u0004 לעירוב בעצמו או על ידי שליח \u0003ב\u0004יום ה\u0003ראשון ומחשיך עליו, ונוטלו\u0004 אם אין בידו אחר, \u0003ובא לו\u0004 וחוזר לביתו. \u0003בשני מחשיך עליו ואוכלו ובא לו, ונמצא משתכר,\u0004 כלומר זוכה בקביעת תחום על ידי עירוב \u0003בהליכתו\u0004 ביום הראשון, \u0003ומשתכר ב\u0004יום השני על ידי \u0003עירובו\u0004 שהניח.","ואם מצא ש\u0003נאכל\u0004 עירובו \u0003ב\u0004יום ה\u0003ראשון\u0004 — הרי \u0003עירובו\u0004 מועיל \u0003ל\u0004יום ה\u0003ראשון, ואין עירובו\u0004 מועיל \u0003לשני.\u0004","\u0003אמר להן ר' אליעזר:\u0004 אם כן נמצא ש\u0003מודים אתם לי ש\u0004שבת ויום טוב \u0003הן שתי קדושות,\u0004 שהרי אין עירוב אחד מועיל לשני הימים כאחד, ואם כן אף אתם תודו לי שיכול אדם לערב לכתחילה לשני הימים ולשני כיוונים שונים.","על לשון חכמים במשנתנו מקשים: \u0003\"לרוח אחת\" מאי ניהו\u0004 \u0005[מה הוא,\u0006 מה משמעו\u0005]\u0006 — ש\u0003לשני ימים\u0004 צריך לערב לאותו כיוון. \u0003\"לשני ימים\" מאי ניהו\u0004 \u0005[מה הוא,\u0006 מה משמעו\u0005]\u0006 — שיכול לערב רק ב\u0003רוח אחת,\u0004 אם כן \u0003היינו קמייתא\u0004 \u0005[הרי זו\u0006 ממש \u0005הראשונה]\u0006 ומה ההבדל בין הדברים?","ומבארים: \u0003הכי קאמרי ליה רבנן\u0004 \u0005[כך אמרו לו חכמים]\u0006 \u0003לר' אליעזר: אי\u0004 \u0005[אין]\u0006 \u0003אתה מודה שאין מערבין ליום אחד חציו לצפון וחציו לדרום? אמר להן: אבל\u0004 כלומר, אכן, כן הוא. אמרו לו: \u0003כשם שאין מערבין ליום אחד חציו לדרום וחציו לצפון — כך אין מערבין לשני ימים\u0004 שהם קדושות סמוכות \u0003יום אחד למזרח ויום אחד למערב.\u0004","\u0003ור' אליעזר\u0004 מה הוא אומר? אומר הוא: \u0003התם\u0004 \u0005[שם]\u0006 ביום אחד — \u0003קדושה אחת\u0004 היא, ואי אפשר לחלק חציו של יום לצד זה וחציו לצד אחר. \u0003הכא\u0004 \u0005[כאן]\u0006 יום טוב ושבת הסמוכים זה לזה — \u0003שתי קדושות\u0004 הן, ואפשר לחלק ביניהם אף לענין עירוב.","\u0003אמר להן ר' אליעזר: אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים\u0004 לי \u0003שאם\u0004 לא היה לו פת כדי לקנות בה שביתה ולכן הלך הוא בעצמו ו\u0003עירב ברגליו ביום ראשון\u0004 שקנה שביתה באותו מקום מכוח שהותו בו בין השמשות, ובכל זאת צריך להיות \u0003מערב ברגליו ביום שני\u0004, ואין די בעירוב אחד, וכן אם \u0003נאכל עירובו ביום ראשון — אין יוצא עליו ביום שני.\u0004","\u0003אמרו לו: אבל\u0004, נכון הוא. אמר להם: \u0003הא לאיי\u0004 \u0005[הרי אם כן]\u0006 \u0003שתי קדושות הן,\u0004 ואם כן אף לכתחילה נוכל לחלק ביניהם. \u0003ורבנן ספוקי מספקא להו, והכא לחומרא והכא לחומרא\u0004 \u0005[וחכמים ספק מסתפקים הם\u0006 בדבר\u0005, וכאן\u0006 הולכים הם \u0005להחמיר וכאן להחמיר],\u0006","\u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר: אי אתה מודה שאין מערבים בתחילה מיום טוב לשבת?\u0004 שאם היה יום טוב בערב שבת ושכח לערב בערב יום טוב אינו יכול לערב בתוך החג עירוב תחומים, \u0003אמר להן: אבל,\u0004 כן הוא. אמרו לו: \u0003הא לאיי\u0004 \u0005[הרי אם כן]\u0006 \u0003קדושה אחת היא!\u0004","ודוחים כי \u0003ר' אליעזר\u0004 סבור כי \u0003התם\u0004 \u0005[שם]\u0006 שאין מערבים מיום טוב עבור השבת לא משום שהיא קדושה אחת, אלא מטעם אחר, \u0003משום הכנה,\u0004 שאסור להכין דברים מיום טוב לשבת, ואפילו עירוב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עירב ברגליו ביום ראשון\u0004 שבא לאותו מקום בבין השמשות וקבע שביתתו בו — \u0003מערב ברגליו ביום שני.\u0004 ואם עירב מלכתחילה במאכל ו\u0003נאכל עירובו ביום ראשון — אין יוצא עליו\u0004 ממקומו למקום עירובו \u0003ביום\u0004 ה\u0003שני\u0004, אלה \u0003דברי רבי.\u0004","\u0003ר' יהודה אומר\u0004:"],["\u0003הרי זה חמר גמל,\u0004 כלומר, נמשך לשני צדדים מנוגדים ואין בידו מאומה, כי אין בידינו הלכה קבועה אם קדושה אחת היא ואם שתיים, ומספק מחמירים אנו עליו גם כאילו קנה עירובו, וגם כאילו לא קנה עירוב כלל.","\u0003רבן שמעון בן גמליאל ור' ישמעאל בנו של ר' יוחנן בן ברוקה אומרים: עירב ברגליו בראשון — אין מערב ברגליו בשני\u0004 אלא חל העירוב גם לצורך יום המחרת, וכן אם \u0003נאכל עירובו ביום\u0004 ה\u0003ראשון — יוצא עליו בשני,\u0004 ששני הימים קדושה אחת הם, ומלכתחילה נקנה לשני הימים.","\u0003אמר רב: הלכה כארבעה זקנים הללו, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' אליעזר\u0004 ש\u0003אמר:\u0004 שבת ויום טוב הסמוכים זה לזה \u0003שתי קדושות הן. ואלו הן ארבעה זקנים\u0004 אלה: \u0003רבן שמעון בן גמליאל, ור' ישמעאל בן ר' יוחנן בן ברוקה, ור' אלעזר בן ר' שמעון, ור' יוסי בר יהודה סתימתאה\u0004 (שדבריו מופיעים הרבה לא בשמו אלא כסתם משנה). \u0003ואיכא דאמרי: חד מינייהו\u0004 \u0005[ויש שאומרים: אחד מהם\u0006 מארבעה זקנים\u0005]\u0006 הוא \u0003ר' אלעזר, ומפיק\u0004 \u0005[ומוציא]\u0006 מן הרשימה את \u0003ר' יוסי בר יהודה סתימתאה\u0004 \u0005[שסתמו\u0006 דבריו\u0005]\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבן שמעון בן גמליאל ור' ישמעאל בר\u0004 \u0005[בן]\u0006 \u0003ר' יוחנן בן ברוקה איפכא\u0004 \u0005[ההיפך]\u0006 \u0003שמעינן להו\u0004 \u0005[שמענו אותם\u0006 אומרים\u0005]\u0006 בברייתא, ולדעתם קדושה אחת היא! ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות.","ומקשים: \u0003אי הכי, היינו\u0004 \u0005[אם כך,\u0006 דבריהם \u0005הרי זה\u0006 כדברי\u0005]\u0006 \u0003רבי\u0004 ובמה נחלקו? ומתרצים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שלא הובאו הדברים כדרך מחלוקת אלא יש לגרוס: \u0003וכן אמר רבן שמעון בן גמליאל וכו'\u0004 שאף הוא סבור כן.","ושואלים: \u0003וליחשוב נמי\u0004 \u0005[ושיחשיב\u0006 בין הזקנים הללו \u0005גם\u0006 את\u0005]\u0006 \u0003רבי\u0004 שאף לדעתו שתי קדושות הן! ומשיבים: \u0003רבי תני לה\u0004 \u0005[שנה\u0006 הלכה \u0005זו]\u0006 \u0003ו\u0004הוא עצמו \u0003לא סבר לה\u0004 \u0005[כמותה]\u0006 שמסר דברי הלכה שקיבל מרבותיו ולא דעת עצמו.","ומקשים: אם כן אפשר לומר \u0003רבנן נמי תנו לה ולא סברי לה\u0004 \u0005[חכמים\u0006 רבן שמעון בן גמליאל ור' ישמעאל \u0005גם כן שנו אותה ולא סברו אותה]\u0006 ומה מוכיח לנו שזו שיטת עצמם? ומשיבים: \u0003רב גמרא גמיר לה\u0004 \u0005[במסורת למד אותה]\u0006 שארבעה זקנים אלה החזיקו בשיטה זו, ולא על לשון המשניות נסמך.","מסופר \u0003כי נח נפשיה\u0004 \u0005[כאשר נפטר]\u0006 \u0003רב הונא,\u0004 תלמידו המובהק של רב, \u0003עייל\u0004 \u0005[נכנס]\u0006 \u0003רב חסדא\u0004 לבית המדרש \u0003למירמא\u0004 \u0005[להקשות]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב: מי\u0004 \u0005[האם]\u0006 \u0003אמר רב: הלכה כארבעה זקנים, ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003ר' אליעזר\u0004 ש\u0003אמר שתי קדושות הן?\u0004","\u0003והא איתמר\u0004 \u0005[והרי נאמר]:\u0006 שנחלקו האמוראים בדין \u0003שבת ויום טוב\u0004 הסמוכים זה לזה, \u0003רב אמר:\u0004 ביצה ש\u0003נולדה בזה — אסורה בזה\u0004 כשם שביצה שנולדה ביום טוב אסורה בו ביום, ומשמע שסבור הוא שקדושה אחת הן. ומצד שני אומר הוא שהלכה כשיטה האומרת ששתי קדושות הן!","\u0003אמר רבה:\u0004 שיש לחלק בין הדינים: \u0003התם\u0004 \u0005[שם]\u0006 בענין ביצה — אין האיסור משום שקדושה אחת היא אלא \u0003משום\u0004 איסור \u0003הכנה\u0004 מיום טוב לשבת.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הפסוק: \u0003\"והיה ביום הששי והכינו\u0004 את אשר יביאו\" (שמות טז, ה) שמשמעו: יום \u0003חול מכין ל\u0004צרכי \u0003שבת, ו\u0004כן \u0003חול מכין ליום טוב,\u0004 ויש לדייק מלשון הכתוב כי רק ביום הששי, שהוא יום חול — עושים כן. \u0003ו\u0004אולם \u0003אין יום טוב מכין לשבת ואין שבת מכינה ליום טוב.\u0004 ולכן ביצה שנולדה ביום טוב אסורה בשבת משום הכנה מקדושה אחת לקדושה שניה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כיצד הוא עושה\u0004 בעירוב של שני ימים — \u0003מוליכו בראשון, ומחשיך עליו, ונוטלו ובא לו\u0004 וחוזר למקומו. \u0003בשני מחשיך עליו, ואוכלו ובא לו\u0004. ואולם \u0003הא קא\u0004 \u0005[הריהו]\u0006 \u0003מכין מיום טוב לשבת,\u0004 והרי לדברי רבה אסור הדבר משום הכנה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003סוף היום קונה עירוב?\u0004 לא, העירוב שהניח בין השמשות אינו נקנה (נקבע חוקית) ברגע האחרון של היום בערב השבת שיהא בכך משום הכנה \u0003אלא תחילת היום,\u0004 בכניסת השבת, \u0003קונה עירוב,\u0004 שלא עשה דבר ביום טוב \u0003ושבת מכינה לעצמה.\u0004","והקשה אביי: \u0003אלא מעתה\u0004 שכך אתה אומר — \u0003יערבו בלגין\u0004 שמילאהו אדם מתוך חבית של טבל ואמר עליו שיחשב לתרומת מעשר רק משחשיכה, ואם תאמר שתחילת היום קונה עירוב, אם כן מדוע נקבעה הלכה שאין לערב בלגין כעין זה?","ודוחים: שם, בלגין אין העירוב נקנה מפני טעם אחר, כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003סעודה הראויה מבעוד יום, וליכא\u0004 \u0005[ואין],\u0006 שהרי לפני חשיכה אין תוכנו של הלגין ראוי לשתיה, לפי שעדיין הוא טבל.","ועוד הקשה: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: יום טוב הסמוך לשבת, בין מלפניה בין מלאחריה — מערב אדם שני עירובין. הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 \u0003סעודה הראויה מבעוד יום, וליכא\u0004 \u0005[ואין],\u0006 שהרי כיון שעירב במקום אחד הרי קנה שביתה באותו מקום ואין לו אלא אלפיים אמה משם, ואינו יכול לגשת ולאכול את העירוב המצוי אלפיים אמה מן הקצה האחר של העיר.","ודוחים: \u0003מי סברת דמנח ליה\u0004 \u0005[האם סבור אתה שיהא מניח אותו,\u0006 את העירוב \u0003]\u0004 במקום הרחוק ביותר שיכול להניחו \u0003בסוף אלפים אמה לכאן, ובסוף אלפים אמה לכאן?\u0004 ואז אינו יכול להגיע מקצה זה לקצה זה? \u0003לא,\u0004 אלא \u0003דמנח ליה\u0004 \u0005[שמניח אותו]\u0006 \u0003בסוף אלף אמה לכאן, ובסוף אלף אמה לכאן,\u0004 שגם כאשר קונה שביתתו בצד אחד על ידי עירוב עדיין מותר לו ללכת למקום שהניח בו את העירוב האחר של יום המחרת.","ועוד הקשה אביי: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה: עירב ברגליו ביום ראשון — מערב ברגליו יום שני, עירב בפת ביום ראשון — מערב בפת ביום שני, הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003מכין מיום טוב לשבת!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת דאזיל ואמר מידי\u0004 \u0005[האם סבור אתה ש\u0006הוא \u0005הולך ואומר דבר]\u0006 ועושה על ידי כך פעולה כלשהי של הכנה? לא כך — \u0003דאזיל ושתיק, ויתיב\u0004 \u0005[שהוא הולך ושותק, ויושב]\u0006 וממילא נקנה לו מקום שביתה מבלי לומר או לעשות דבר.","והקשה לו: אם כן \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 הלכה זו? לגבי קניית מקום, \u0003כ\u0004שיטת \u0003ר' יוחנן בן נורי\u0004 ש\u0003אמר:\u0004 אדם ישן קונה שביתה במקומו. ואף על פי שאינו אלא כחפצי הפקר מכל מקום \u0003חפצי הפקר קונין שביתה\u0004 בעצמם ויש להם תחום לעצמם, ואין צורך שיקנה להם אדם שביתה במקום ידוע.","ענה לו: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שדברי כשיטת \u0005חכמים]\u0006 \u0003עד כאן לא\u0004 שמענו \u0003פליגי רבנן עליה\u0004 \u0005[שנחלקו חכמים עליו]\u0006 על \u0003ר' יוחנן בן נורי אלא בישן, דלא מצי אמר\u0004 \u0005[שאינו יכול לומר]\u0006 דבר, שהרי ישן הוא. ומשום כך אינו יכול לקנות שביתה באופן אחר. \u0003אבל בניעור, דאי בעי למימר מצי אמר\u0004 \u0005[שאם היה רוצה לומר היה יכול לומר]\u0006 לכן \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר\u0004 שהוא קונה שביתה, \u0003כמאן דאמר דמי\u0004 \u0005[כמי שאומר נחשב].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר רב חנין לאביי: אי הוה שמיע ליה למר הא דתניא\u0004 \u0005[אם היה נודע לו לרבינו\u0006 רבה\u0005, זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יהלך אדם לסוף שדהו לידע מה היא צריכה\u0004 לעיבוד ולתיקון לאחר השבת, וכן \u0003כיוצא בו:\u0004"],["\u0003לא יטייל אדם\u0004 סמוך לצאת החג או השבת \u0003על פתח מדינה\u0004 (העיר) \u0003כדי שיכנס למרחץ מיד. ולפי דבריך האם הדר ביה\u0004 \u0005[היה חוזר בו]\u0006 ממה שאמר לענין עירוב? שהרי נראה מכאן שאף הליכה בשבת לצורך מוצאי שבת היא כהכנה אסורה!","ודוחים \u0003ולא היא,\u0004 ואין הדבר כן, אלא \u0003שמע ליה ולא הדר ביה\u0004 \u0005[שמע\u0006 את הברייתא \u0005הזאת ולא חזר בו]\u0006 כי יש להבדיל בין המקרים. \u0003התם\u0004 \u0005[שם]\u0006 במהלך בסוף שדהו וכן בעומד סמוך לפתח המדינה \u0005—\u0006 \u0003מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 לכל מי שרואה שמעשיו לצורך בדיקת צרכי שדהו או לשם כניסה מיידית לבית המרחץ, \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי העירוב — \u0003לאו מוכחא מילתא\u0004 \u0005[אין הדבר מוכח]\u0006 שעשה מה שעשה לצורך העירוב.","שכן \u0003אי צורבא מרבנן הוא, אמרינן: שמעתא משכתיה\u0004 \u0005[אם תלמיד חכם הוא, אומרים אנו\u0006 הרואים: שמא \u0005ההלכה משכה אותו],\u0006 שמתוך טרדתו בעיון בהלכה טייל ולא שם לב לאן הוא הולך. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003עם הארץ הוא, אמרינן: חמרא אירכס ליה\u0004 \u0005[אומרים אנו:\u0006 שמא \u0005חמור אבד לו],\u0006 והריהו טורח לחפש אחריו ואין כל הוכחה במעשיו שכוונתו לקנות עירוב, שהרי אינו עושה כל מעשה הנראה לעין.","\u0003גופא\u0004 \u0005[לגופם של דברים שהזכרנו\u0006\u0005]\u0006 \u0003אמר רב יהודה: עירב ברגליו ביום ראשון — מערב ברגליו\u0004 אף \u0003ב\u0004יום ה\u0003שני.\u0004 ואם \u0003עירב בפת ביום ראשון — מערב בפת\u0004 אף \u0003ביום\u0004 ה\u0003שני.\u0004","ואם \u0003עירב בפת בראשון\u0004 ונאכל עירובו, יכול לשנות ולהיות \u0003מערב ברגליו בשני.\u0004 אולם אם \u0003עירב ברגליו בראשון — אין מערב בפת בשני,\u0004 כי מעיקרו של דבר \u0003שאין מערבין בתחלה\u0004 ביום טוב לצורך השבת שלאחריו \u0003בפת\u0004 שכן אסורה הכנה מיום טוב לשבת.","על מה שאמרו: \u0003עירב בפת ביום ראשון — מערב בפת ביום שני, אמר שמואל: ובאותה הפת\u0004 דוקא, \u0003אמר רב אשי: דיקא נמי מתניתין\u0004 \u0005[מדוייקת גם כן משנתנו]\u0006 כשיטת הסבר זו, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003כיצד הוא עושה? מוליכו בראשון, ומחשיך עליו ונוטלו ובא לו. בשני, מחשיך עליו ואוכלו ובא לו,\u0004 משמע שנוטל אותה פת עצמה.","ואומרים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שאינם מקבלים דברי שמואל אומרים שאין זו הוכחה, כי \u0003דילמא התם\u0004 \u0005[שמא שם]\u0006 במשנה \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא יוכרח להכין עירוב נוסף אלא יוכל להסתפק בעירוב אחד.","\u0003ר' יהודה אומר: ראש השנה, שהיה ירא\u0004 אדם הגר בגולה \u0003שמא תתעבר\u0004 ויהא ראש השנה שני ימים. שבזמן שבית המקדש היה קיים עשו את ראש השנה לפעמים יום אחד בלבד ולפעמים עיברו בית דין את החודש ונהגו שני ימים. ואם אדם אינו יודע כיצד יהא ראש שנה זו, ובשני הימים העשויים להיקבע כראש השנה הוא צריך ללכת בכל יום לצד אחר, אמר ר' יהודה שבמקרה זה \u0003מערב אדם שני עירובין, ואומר: עירובי\u0004 יהא \u0003ב\u0004יום ה\u0003ראשון למזרח, ובשני למערב. בראשון למערב ובשני למזרח.\u0004 או \u0003עירובי\u0004 יחול \u0003ב\u0004יום ה\u0003ראשון, ובשני\u0004 אהיה \u0003כבני עירי\u0004 או \u0003עירובי\u0004 יחול \u0003ב\u0004יום ה\u0003שני, ובראשון\u0004 אהיה \u0003כבני עירי. ולא הודו לו חכמים\u0004 שאפשר לחלק כך בין שני ימי ראש השנה.","\u0003ועוד אמר ר' יהודה\u0004 כיוצא בזה לענין שני ימי ראש השנה כשנסתפק שמא נתעבר החודש ויום זה עדיין יום החג: \u0003מתנה אדם על הכלכלה,\u0004 על סל פירות של טבל שהיה לו, \u0003ביום טוב ראשון\u0004 ואומר: אם היום קודש ומחר חול — הרי אני מפריש את המעשר רק מחר, ולא עשיתי היום מאומה. אם היום חול — הריני מפריש עכשיו את המעשרות הראויים. \u0003ואוכלה בשני,\u0004 שהרי בכל אופן, אחד משני העישורים היה ביום חול.","\u0003וכן ביצה שנולדה ב\u0004יום טוב \u0003ראשון תאכל בשני,\u0004 מפני שוודאי אחד מן הימים חול הוא. \u0003ולא הודו לו חכמים\u0004 אף בשני ימים טובים אלה.","\u0003ר' דוסא בן הרכינס אומר: העובר לפני התיבה ביום טוב של ראש השנה, אומר: \"החליצנו ה' אלהינו את יום ראש החדש הזה אם היום\u0004 הוא \u0003אם למחר\"\u0004 שהרי אין הדבר נודע אלא לאחר חקירת בית דין. \u0003ו\u0004כן \u0003למחר הוא אומר: \"אם היום אם אמש\u0004 היה ראש השנה \u0003\"\u0004. \u0003ולא הודו לו חכמים\u0004 שיזכיר בתפילתו לשון זו של תנאי.","\u0003מאן\u0004 \u0005[מי הם]\u0006 אותם חכמים ש\u0003\"לא הודו לו\"? אמר רב\u0004: המחזיקים בשיטת \u0003ר' יוסי היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003מודים חכמים לר' אליעזר ב\u0004שאלת \u0003ראש השנה\u0004 ולענין שני עירובין, \u0003שהיה ירא שמא תתעבר,\u0004 הרי \u0003מערב\u0004 אדם \u0003שני עירובין, ואומר: עירובי בראשון למזרח ובשני למערב, בראשון למערב ובשני למזרח. עירובי בראשון ובשני כבני עירי, עירובי בשני ובראשון כבני עירי.\u0004 ו\u0003ר' יוסי אוסר.\u0004","\u0003אמר להן ר' יוסי\u0004 לחכמים: \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים שאם באו עדים\u0004 שהעידו שראו את מולד הלבנה קודם לכן \u0003מן המנחה ולמעלה,\u0004 לאחריה, ביום הראשון של ראש השנה, שאין אנו סומכים על עדותם לקדש היום בקדושת ראש השנה אלא אומרים שכיון שלא נתקבלה העדות בזמנה אין זו מקדשת את היום שעבר, ו\u0003נוהגין אותו היום\u0004 של ראש השנה \u0003קדש\u0004 כביום חג ממש \u0003ו\u0004אף \u0003למחר קדש,\u0004 ואין זה מחמת הספק שאיננו יודעים באיזה יום קדש החג נוהגים שני ימים, אלא בשאיחרו העדים נוהגים מלכתחילה בשני הימים וכאילו היו יום אחד ארוך בלבד, משמע שקדושת ראש השנה בשני הימים קדושה אחת היא, ואין לחלק בה."],["\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים כי \u0003התם\u0004 \u0005[שם]\u0006 בראש השנה לא נעשה אותו יום קודש מדין תורה אלא תקנת חכמים היא \u0003כי היכי דלא לזלזולי ביה\u0004 \u0005[כדי שלא יזלזלו בו]\u0006 ביום טוב הראשון בשנה אחרת. אבל מעיקר הדין יום חול הוא.","במשנה הובא שבנוסף לעירוב לצורך שני ימי ראש השנה \u0003עוד אמר ר' יהודה\u0004 לגבי ביצה וכלכלה ביום טוב של גלויות, ומעירים:","\u0003וצריכא\u0004 \u0005[וצריך]\u0006 היה לומר לנו שלוש הלכות אלו ואין ללמוד אחת מחברתה. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 את ההלכה רק ב\u0003ראש השנה,\u0004 היינו אומרים \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' יהודה, משום דלא קעביד מידי\u0004 \u0005[שאינו עושה דבר]\u0006 בתוך היום עצמו, \u0003אבל כלכלה, דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כמתקן טיבלא\u0004 \u0005[טבל]\u0006 ועושה מעשה של תיקון — \u0003אימא מודה להו לרבנן\u0004 \u0005[אמור מודה\u0006 הוא \u0005להם לחכמים]\u0006 שגוזרים אנו לאסור.","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו באלו השתים],\u0006 היינו אומרים שהתיר ר' יהודה \u0003משום דליכא למיגזר עלייהו\u0004 \u0005[שאין מקום לגזור עליהם],\u0006 שכן אין איסורם מעיקרו חמור כל כך, \u0003אבל ביצה\u0004 שנולדה \u0003דאיכא למיגזר\u0004 \u0005[שיש\u0006 מקום \u0005לגזור]\u0006 \u0003בה,\u0004 כמבואר במסכת ביצה, \u0003משום פירות הנושרין ו\u0004כן \u0003משום משקין שזבו\u0004 מן הפירות ביום טוב, שגזרו חכמים שאסור להשתמש בהם, \u0003אימא\u0004 \u0005[אמור]\u0006 שמא \u0003מודה להו לרבנן [להם לחכמים]\u0004 שאסורה ביצה זו לאכילה אפילו ביום השני, לכן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להשמיענו בכל המקרים.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003כיצד אמר ר' יהודה מתנה אדם על הכלכלה ביום טוב ראשון ואוכלה בשני? היו לפניו שתי כלכלות\u0004 \u0005(סלים)\u0006 \u0003של\u0004 פירות \u0003טבל, אומר: אם היום חול ולמחר קדש — תהא זו תרומה על זו, ואם היום קדש ולמחר חול — אין בדברי כלום. וקורא עליה שם\u0004 תרומה, \u0003ומניחה.\u0004","\u0003ולמחר הוא אומר: אם היום חול — תהא זו תרומה על זו, ואם היום קדש — אין בדברי כלום, וקורא עליה שם\u0004 תרומה \u0003ואוכלה\u0004 את הכלכלה האחרת, שכן בכל אופן הופרשה התרומה ביום חול. \u0003ר' יוסי אוסר. וכן היה ר' יוסי אוסר בשני ימים טובים של גליות,\u0004 שאף על פי שהיום השני נקבע משום הספק בלבד, יש להחמיר בכך.","מסופר: \u0003ההוא בר טביא דאתא לבי ריש גלותא דאתציד\u0004 \u0005[צבי צעיר אחד שהובא לבית ראש הגולה, שניצוד\u0006 על ידי גוי\u0005]\u0006 \u0003ביום טוב ראשון של גליות, ואשתחיט\u0004 \u0005[ונשחט]\u0006 \u0003ביום טוב שני,\u0004 ונתעוררה השאלה אם מותר לאכלו על סמך שיום אחד משני הימים האלה ודאי יום חול הוא.","\u0003רב נחמן ורב חסדא אכלו\u0004 מבשרו, ו\u0003רב ששת לא אכל. אמר רב נחמן\u0004 בלשון מבודחת: \u0003מאי אעביד ליה\u0004 \u0005[מה אעשה לו]\u0006 \u0003לרב ששת דלא אכיל בישרא דטביא\u0004 \u0005[שאינו אוכל בשר צבי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת: והיכי איכול\u0004 \u0005[ואיך אוכל]\u0006 שהרי \u0003תני\u0004 \u0005[שנה]\u0006 \u0003איסי\u0004, \u0003ואמרי לה\u0004 ויש אומרים בשינוי (ובלשון שאלה) \u0003איסי תני\u0004 \u0005[שנה]:\u0006 \u0003וכן היה ר' יוסי אוסר בשני ימים טובים של גליות!\u0004","\u0003אמר רבא: ומאי קושיא\u0004 \u0005[ומה הקושיה]?\u0006 \u0003דילמא הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 \u0003וכן היה ר' יוסי אוסר בשני ימים טובים של ראש השנה בגולה\u0004 אבל בשני ימי יום טוב של גלויות מודה הוא לר' יהודה המתיר! אמרו לו: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"של גליות\"\u0004 אינה ראויה, אלא \u0003\"בגולה\" מיבעי ליה\u0004 \u0005[צריך היה\u0006 לו לומר\u0005]!\u0006","\u0003אמר ר' אסי: ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 בזה\u0005]?\u0006 \u0003דילמא הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 \u0003וכן היה ר' יוסי עושה איסור שני ימים טובים של גליות, כשני ימים טובים של ראש השנה לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003דשרו\u0004 \u0005[שהתירו].\u0006 על כל פנים הראו כי ההוכחה מברייתא זו אינה מושלמת.","מסופר כי אחר כך \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003רב ששת לרבה בר שמואל, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תני מר מידי\u0004 \u0005[וכי שנה אדוני דבר]\u0006 \u0003ב\u0004שתי \u0003קדושות\u0004 יום טוב וכיוצא בהן? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003מודה ר' יוסי בשני ימים טובים של גליות. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי משכחת להו, לא תימא להו ולא מידי\u0004 \u0005[אם תמצא אותם\u0006 את ר' נחמן ור' חסדא שחלקו עלי\u0005, אל תאמר להם דבר]\u0006 ממה שאמרת, שלא יביישוני ממקור זה שמדברי התנאים על שלא אכלתי.","\u0003אמר רב אשי: לדידי\u0004 \u0005[לי עצמי]\u0006 \u0003אמר לי אמימר: ההוא בר טביא לאו איתצודי איתציד\u0004 \u0005[אותו צבי לא ניצוד]\u0006 ביום טוב,"],["\u0003אלא מחוץ לתחום אתא\u0004 \u0005[בא].\u0006 אף על פי שניצוד עוד קודם לכן, ובו ביום נשחט. \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אכל סבר:\u0004 דבר \u0003הבא\u0004 מחוץ לתחום \u0003בשביל ישראל זה — מותר לישראל אחר.\u0004 וכיון שהובא הצבי בשביל ראש הגולה — מותר לחכמים לאוכלו, ואין אוסרים להם ליהנות ממה שעשה גוי בשביל ישראל אחר.","\u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003לא אכל סבר: כל\u0004 דבר \u0003דאתי לבי ריש גלותא\u0004 \u0005[שבא לבית ראש גולה] —\u0006 \u0003אדעתא דכולהו רבנן אתי\u0004 \u0005[על דעת כל החכמים בא],\u0006 שידוע שראש הגולה מזמנם לסעוד אצלו ביום טוב. וכשם שאסור לראש הגולה עצמו כיון שהובא מחוץ לתחום, כך אסור גם לכל בני ביתו שהם החכמים.","ושואלים: \u0003והא אשכחיה\u0004 \u0005[והרי מצאו]\u0006 \u0003רב ששת לרבה בר שמואל ואמר ליה\u0004 \u0005[לו]\u0006 מה שאמר?! ועונים שלפי הגירסה ששמע רב אשי \u0003לא היו דברים מעולם,\u0004 וכל אותו מעשה לא כך היה.","מסופר \u0003ההוא ליפתא דאתי\u0004 \u0005[לפת אחת שהובאה]\u0006 \u0003ל\u0004עיר \u0003מחוזא\u0004 על ידי גויים ביום טוב של גלויות, \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רבא\u0004 לשוק, \u0003חזיא דכמישא, שרא\u0004 \u0005[ראה\u0006 שלפת זו \u0005כמושה, והתיר]\u0006 \u0003רבא למיזבן מיניה\u0004 \u0005[לקנות ממנה]\u0006 מיד, ולא צווה להמתין בכדי שתובא כמותה מחוץ לתחום. \u0003אמר: הא\u0004 \u0005[\u0006לפת \u0005זו]\u0006 \u0003ודאי\u0004 מאתמול \u0003נעקרה\u0004 ולא נעשתה בה מלאכה היום","אלא \u0003מאי אמרת\u0004 \u0005[מה אומר אתה]\u0006 \u0003מחוץ לתחום אתיא\u0004 \u0005[באה],\u0006 ומשום כך תיאסר. ואולם, כלל הוא זה: \u0003הבא בשביל ישראל זה, מותר לאכול לישראל אחר, וכל שכן האי דאדעתא דגוים אתא\u0004 \u0005[\u0006לפת \u0005זו שעל דעת הגוים הובאה]\u0006 כלומר: בשבילם ולא בשביל ישראל, ואם קונים ישראל ממנה — אין איסור בדבר.","\u0003כיון דחזא דקא מפשי ומייתי להו\u0004 \u0005[שראה שמרבים ומביאים להם]\u0006 שהיו הגוים מרבים להביא לפת עבור הקונים היהודים — \u0003אסר להו\u0004 \u0005[להם]\u0006 לבני מחוזא לקנותה מהם, שהרי ברור שהביאו מלכתחילה בשביל ישראל.","וכן מסופר: \u0003הנהו בני גננא דגזו להו אסא\u0004 \u0005[אותם בני החופות\u0006 שקולעים בהן הדסים \u0005שחתכו להם הדס]\u0006 \u0003ביום טוב שני, לאורתא שרא להו\u0004 \u0005[לערב התיר להם]\u0006 \u0003רבינא לאורוחי ביה לאלתר\u0004 \u0005[להריח בו מיד],\u0006 ולא הצריכם להמתין עד מוצאי החג. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר תחליפא לרבינא: ליסר להו מר\u0004 \u0005[שיאסור להם אדוני]\u0006 \u0003מפני שאינן בני תורה,\u0004 ויש להחמיר עליהם שלא יבואו לזלזל בקדושת יום טוב שני.","\u0003מתקיף\u0004 \u0005[מקשה]\u0006 על כך \u0003רב שמעיה: טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 משום ש\u0003אינן בני תורה, הא\u0004 \u0005[הרי]\u0006 אם היו \u0003בני תורה שרי\u0004 \u0005[מותר היה]?!\u0006 \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 בכלל להמתין \u0003בכדי שיעשו! אזלו שיילוה\u0004 \u0005[הלכו ושאלוה\u0006 לשאלה זו\u0005]\u0006 \u0003לרבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 להמתין \u0003בכדי שיעשו.\u0004","במשנה הובאה גירסתו של ר' דוסא על נוסח התפילה המיוחד של ראש השנה. \u0003ר' דוסא אומר: העובר לפני התיבה\u0004 ביום טוב הראשון של ראש השנה אומר: \"החליצנו ה' אלהינו את יום ראש החדש הזה אם היום אם למחר\".","\u0003אמר רבה: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו של\u0005]\u0006 \u0003רב הונא, איבעיא לן\u0004 \u0005[נשאלה לנו\u0006 שאלה זו\u0005]\u0006 \u0003מהו להזכיר\u0004 גם את \u0003של ראש חדש\u0004 בתפילת \u0003ראש השנה?\u0004 וצדדי השאלה: האם \u0003כיון\u0004 ש\u0003חלוקין במוספין,\u0004 שמביאים קרבן מוסף מיוחד לשם ראש חודש וקרבן מוסף מיוחד לשם ראש השנה, \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ומזכירים את ראש חודש בראש השנה? \u0003או דילמא\u0004 \u0005[שמא]\u0006 — \u0003זכרון אחד עולה לכאן ולכאן,\u0004 שלשון \"זכרון\" נאמרה בתורה גם בראש השנה וגם בראש חודש, ולכן די במה שאומרים \"יום הזכרון\" בלבד?","\u0003אמר לן\u0004 \u0005[לנו]\u0006 רב הונא: \u0003תניתוה\u0004 \u0005[שניתם אותה\u0006 במשנה\u0005]\u0006 את הפתרון לשאלה זו, שכן \u0003ר' דוסא אומר: העובר לפני התיבה אומר ומתנה אף על ראש חודש בו ביום. נאמר במשנה שלא הודו לו חכמים ושואלים: על מה לא הודו לו, מאי לאו\u0004 \u0005[האם לא]\u0006 שנתכוון לדייק מדבריו שיש \u0003להזכיר\u0004 את ראש החודש?","את הראיה הזו דוחים: \u0003לאו\u0004 \u0005[לא],\u0006 \u0003להתנות.\u0004 שחידושו של ר' דוסא לא היה בעצם הזכרת ראש החודש, אלא שיש להתנות בתוך התפילה שמא יום זה אין קדושתו ודאית.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שעיקר המחלוקת לענין התנאי ולא לענין הזכרת ראש חודש. \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 כעין זה \u0003בברייתא: וכן היה ר' דוסא עושה בראשי חדשים של כל השנה כולה\u0004 שעושים אותם שני ימים מספק, \u0003ולא הודו לו\u0004 חכמים.","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 מעיקרו של הדבר משום \u0003להתנות\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא הודו לו,\u0004 משום שבעיקרו של דבר לא הסכימו שיש להתנות כן בתפילה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שעיקר הדבר הוא \u0003להזכיר\u0004 ראש חודש — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא הודו לו,\u0004 ומדוע לא יזכירו ראש חודש בתפילה?","ומקשים: ו\u0003אלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 — שהמחלוקת היא \u0003להתנות? למה לי לאיפלוגי בתרתי\u0004 \u0005[לחלוק פעמיים]?\u0006 הלא הבעיה אחת היא, הן לגבי ראש חודש והן לגבי ראש השנה! ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה]\u0006 מחלוקת כפולה זו \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 ב\u0003ראש השנה\u0004 בלבד \u0005—\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003בהא קאמרי רבנן דלא\u0004 \u0005[בזה אמרו חכמים שלא]\u0006 יזכיר תנאי — \u0003משום דאתי לזלזולי ביה\u0004 \u0005[שיבואו לזלזל\u0006 ולעשות \u0005בו\u0006 מלאכה\u0005],\u0006 \u0003אבל בראשי חדשים של כל השנה כולה — אימא מודו ליה\u0004 \u0005[אמור\u0006 שמא \u0005מודים לו]\u0006 \u0003לר' דוסא,\u0004 שהרי אין איסור מלאכה בראש חודש, ואין חשש זלזול בו.","ולהיפך: \u0003ואי אתמר בהא\u0004 \u0005[ואם היה נאמר בזה,\u0006 בראש חודש\u0005]\u0006 הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזה\u0006 דוקא \u0005אמר]\u0006 \u0003ר' דוסא\u0004 שמתנים, \u0003אבל בהך\u0004 \u0005[בההיא,\u0006 בראש השנה\u0005] —\u0006 \u0003אימא\u0004 \u0005[נאמר]\u0006 ש\u0003מודה להו לרבנן\u0004 \u0005[להם לחכמים]\u0006 מחשש זלזול בחג. על כן, \u0003צריכא\u0004 \u0005[נצרכה]\u0006 המחלוקת להיאמר בשני המקרים.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003ראש השנה שחל להיות בשבת, בית שמאי אומרים: מתפלל עשר\u0004 ברכות, שמוסיף עוד ברכה אחת להזכרת השבת, \u0003ובית הלל אומרים: מתפלל תשע,\u0004 ומזכיר את השבת והחג בברכה אחת. \u0003ואם איתא\u0004 \u0005[יש]\u0006 שיטה הסבורה שיש להזכיר את ראש החדש, אם כן לדעת \u0003בית שמאי אחת עשרה\u0004 ברכות \u0003מבעי ליה\u0004 \u0005[צריך לו]\u0006 לומר, שהן: תשע לראש השנה, אחת לשבת, ואחת להזכרת ראש חודש."],["\u0003אמר ר' זירא: שאני\u0004 \u0005[שונה]\u0006 \u0003ראש חודש\u0004 שצריך אכן להזכירו לבית שמאי ובכל זאת לא קבעוהו כברכה בפני עצמה, \u0003מתוך שכולל ל\u0004הזכרת ראש חודש בין בתפילת \u0003שחרית ו\u0004בין בתפילת \u0003ערבית,\u0004 ולא אומרו כברכה בפני עצמה, \u0003כולל נמי\u0004 \u0005[גם כן]\u0006 \u0003במוספין.\u0004","ומקשים: \u0003ומי אית להו\u0004 \u0005[והאם יש להם,\u0006 היו מקבלים\u0005]\u0006 \u0003בית שמאי\u0004 הלכה זו ש\u0003כולל\u0004 ברכת ראש חודש בברכה אחרת? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ראש חדש שחל להיות בשבת, בית שמאי אומרים: מתפלל שמנה,\u0004 שמוסיף ברכה מיוחדת לראש החודש. \u0003ובית הלל אומרים: מתפלל שבע\u0004 ברכות, וכולל ראש החודש בשל שבת. ואם כן לדעת בית שמאי אין כוללים ברכה בברכה. ומה שלא הצריכו בראש השנה ברכה בפני עצמה הוא מכיון שזכרון עולה לכאן ולכאן. ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר לשיטתו\u0005]\u0006","ומעירים: \u0003ו\u0004ענין זה אם \u0003כולל\u0004 ברכה בברכה הוא \u0003עצמו תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שבת שחל להיות בראש חודש או בחולו של מועד, ערבית שחרית ומנחה מתפלל כדרכו שבע\u0004 ברכות, \u0003ואומר מעין המאורע\u0004 שמזכיר את ראש חודש או חול המועד \u0003ב\u0004ברכת ה\u0003עבודה\u0004 (\"רצה\") באמירת \"יעלה ויבוא\". \u0003ר' אליעזר אומר:\u0004 מוסיף דברים אלה \u0003ב\u0004ברכת \u0003הודאה\u0004 (\"מודים\"), \u0003ואם לא אמר — מחזירין אותו.\u0004 הרי שאינו כולל את המאורע בתוך הברכות עצמן בתפילה.","\u0003וב\u0004תפילת ה\u0003מוספין מתחיל\u0004 את הברכה הרביעית, היא הברכה המיוחדת למוסף — \u0003בשל שבת, ומסיים בשל שבת, ואומר קדושת היום\u0004 ראש חודש או המועד \u0003באמצע.\u0004","ואילו \u0003רבן שמעון בן גמליאל ור' ישמעאל בנו של ר' יוחנן בן ברוקה אומרים: כל מקום שזקוק לשבע\u0004 ברכות ואפילו בשחרית או ערבית — \u0003מתחיל בשל שבת ומסיים בשל שבת, ואומר קדושת היום\u0004 של יום טוב או ראש חודש \u0003באמצע.\u0004 שלדעתם יש לכלול דברי ברכה מיוחדים בתוך עצם התפילה.","לעיקרה של השאלה — אם מזכירים ראש חודש בראש השנה שואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 למעשה? מה פסקו בה חכמים: \u0003אמר רב חסדא: זכרון אחד עולה לו לכאן ולכאן. וכן אמר רבה: זכרון אחד עולה לו לכאן ולכאן.\u0004","אגב הדיון בתפילות ראש השנה מביאים עוד בעיות הקשורות בכך. \u0003ואמר רבה: כי הוינא בי\u0004 \u0005[כאשר הייתי בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב הונא, איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו: \u0003מהו לומר זמן\u0004 (ברכת \"שהחיינו\"), \u0003בראש השנה וביום הכפורים?\u0004 וצדדי השאלה: \u0003כיון\u0004 ש\u0003מזמן לזמן אתי\u0004 \u0005[בא\u0006 החג\u0005] —\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \"שהחיינו\", כעל כל דבר שמחה הבא מזמן לזמן, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא איקרו\u0004 \u0005[נקראו]\u0006 חגים אלה \u0003רגלים — לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \"שהחיינו\", שאין השמחה בהם חשובה דיה. \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה.","\u0003כי אתאי בי\u0004 [כאשר באתי לבית מדרשו\u0005]\u0006 של \u0003רב יהודה אמר: אנא אקרא חדתא נמי אמינא\u0004 \u0005[אני על דלעת חדשה גם כן אומר]\u0006 \u0003זמן,\u0004 ברכת \"שהחיינו\", ובודאי מברך אני \"שהחיינו\" גם על ראש השנה ויום הכיפורים. \u0003אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 לענין \u0003רשות\u0004 לומר \"שהחיינו\" \u0003לא קא מבעיא לי\u0004 \u0005[אינו מסופק בעיני],\u0006 \u0003כי קא מיבעיא לי\u0004 \u0005[כאשר נסתפק לי]\u0006 האם לגבי \u0003חובה מאי\u0004 \u0005[מהו]?\u0006 האם חובה היא לומר \"שהחיינו\" או לא? \u0003אמר לי: רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין אומר זמן אלא בשלש רגלים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא במדרש הכתוב \u0003\"תן חלק לשבעה וגם לשמונה\"\u0004 (קהלת יא, ב) \u0003ר' אליעזר אומר: \"שבעה\" — אלו שבעה ימי בראשית, \"שמונה\" — אלו שמונה ימי מילה.\u0004 ו\u0003ר' יהושע אומר: \"שבעה\" — אלו שבעה ימי פסח, \"שמונה\" — אלו שמונה ימי החג. וכשהוא אומר \"וגם\"\u0004 הרי זה בא (כשאר לשון 'גם' במקרא) \u0003לרבות\u0004, ומה הוא מרבה — \u0003עצרת\u0004 (חג השבועות) \u0003וראש השנה ויום הכפורים.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נתכוון בדרשה זו ללמד שגם ימים אלה חייבים \u0003ל\u0004ברך בהם ברכת \u0003זמן?\u0004 ודוחים \u0003לא.\u0004 הכוונה היתה \u0003לברכה\u0004 שיש לומר ברכה מיוחדת בימי חג אלה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 \u0003לזמן\u0004 (לענין ברכת \"שהחיינו\") — וכי ברכת \u0003זמן כל שבעה\u0004 ימי חג הפסח \u0003מי איכא\u0004 \u0005[האם ישנם]?\u0006 שהרי אין מברכים \"שהחיינו\" אלא ביום הראשון של החג בלבד! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קושיה]\u0006 שהכוונה היא \u0003דאי לא מברך האידנא\u0004 \u0005[שאם לא מברך עכשיו]\u0006 ביום הראשון של החג \u0005—\u0006 \u0003מברך למחר וליום אוחרא\u0004 \u0005[אחר\u0006 בתוך החג\u0005]\u0006 שכל ימי החג דינם כרגלים, ויכול לברך בכל אחד מהם ברכת \"שהחיינו\" על הרגל.","ושואלים: והלא \u0003מכל מקום\u0004 אפילו לשיטה שחובה היא לברך — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003כוס,\u0004 לברך \"שהחיינו\" על כוס יין והיכן ימצא כל אדם כוס בימי חול המועד? ואם כן, \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שדבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן\u0004 ש\u0003אמר רב נחמן\u0004 כרגיל \u0003זמן אומרו אפילו בשוק\u0004 בלא כוס. ומעירים: \u0003הא לא קשיא, דאיקלע ליה\u0004 \u0005[זו אינה קושיה,\u0006 שכן כאן מדובר \u0005שנזדמנה לו]\u0006 \u0003כוס,\u0004 ואכן אין לברך \"שהחיינו\" בלא כוס.","ומקשים: \u0003התינח\u0004 \u0005[זה נוח]\u0006 לגבי \u0003עצרת וראש השנה,\u0004 שיכול לברך \"שהחיינו\" על הכוס, ואולם \u0003יום הכפורים היכי עביד\u0004 \u0005[כיצד עושה]?\u0006 \u0003אי מברך עליה ושתי ליה\u0004 \u0005[אם מברך\u0006 על הכוס \u0005ושותה אותה]\u0006 \u0003ואולם כיון\u0004 ש\u0003אמר\u0004 הוא כבר \u0003זמן,\u0004 ברכת \"שהחיינו\", \u0003קבליה עליה\u0004 \u0005[קיבל עליו]\u0006 קדושת היום\u0003, ואסר ליה\u0004 \u0005[לו]\u0006 לשתות, כדין יום הכיפורים,","שהרי \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ירמיה בר אבא לרב\u0004 כאשר ראהו שהוא מקדש לפני כניסת השבת: \u0003מי בדלת\u0004 \u0005[האם\u0006 גם \u0005בדלת]\u0006 מעשיית מלאכה להימנע מלעשות מלאכה משעה זו? \u0003ואמר ליה: אין, בדילנא\u0004 \u0005[ואמר לו: כן, בדלתי\u0006 מעשיית מלאכה\u0005]\u0006 משמע שמשעת הקידוש, שבו הוא מקבל עליו את קדושת היום, חלים עליו כל דיני היום, וכיון שבירך על יום הכיפורים שוב אסור לו לאכול בו.","ואם תאמר: \u0003לברוך עליה ולנחיה\u0004 \u0005[שיברך על\u0006 הכוס \u0005ויניחנה]\u0006 וישתה אותה למוצאי החג, הלא כלל הוא ש\u0003המברך צריך שיטעום!\u0004 ואם נאמר \u0003ליתביה לינוקא\u0004 \u0005[שיתן אותו לתינוק]\u0006 שאינו מחוייב בצום, אולם בענין זה \u0003לית הלכתא\u0004 \u0005[אין הלכה]\u0006 \u0003כרב אחא\u0004 שהציע הצעה כעין זו לענין אחר, וטעמו של דבר: \u0003דילמא אתי למסרך\u0004 \u0005[שמא יבוא להימשך]\u0006 שישתה התינוק יין בכל יום הכיפורים אפילו לאחר שיגדיל, שאין קובעים תקנה העלולה להביא למכשול.","אם כן, בסופו של דבר, \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה\u0006 על הלכה זו למעשה\u0005]?\u0006 האם צריך לומר ברכת \"שהחיינו\" בראש השנה ויום הכיפורים? \u0003שדרוה רבנן\u0004 \u0005[שלחו חכמים]\u0006 את \u0003רב יימר סבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא במעלי יומא דריש שתא\u0004 \u0005[ערב יום ראש השנה]\u0006 \u0003אמרו ליה: זיל חזי היכי עביד עובדא, תא אימא לן\u0004 \u0005[אמרו לו: לך ראה איך עושה הוא מעשה\u0006 לענין ברכת \"שהחיינו\", ואחר \u0005בוא אמור לנו].\u0006 \u0003כי חזייה\u0004 \u0005[כאשר ראהו]\u0006 רב חסדא \u0003אמר ליה\u0004 \u0005[לו]\u0006 כפתגם העם: \u0003דלויה לרטיבא רפסא ליה בדוכתיה\u0004 \u0005[כשהרימו את\u0006 הקורה \u0005הרטובה,\u0006 עושים זאת משום שרוצים לעשות \u0005משהו במקומה]\u0006 כלומר, בוודאי באת אלי לצורך מסויים ולא לביקור. ולמעשה, \u0003אייתו ליה כסא דחמרא, קדיש\u0004 \u0005[הביאו לו כוס יין, קידש]\u0006 \u0003ואמר זמן.\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 למעשה\u0005]:\u0006 \u0003אומר זמן בראש השנה וביום הכפורים, והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 ש\u0003זמן אומרו אפילו בשוק\u0004 ואינו זקוק לכוס.","ועוד בענין שאלות אלו, כיון שהוזכרה שאלה שהועלתה בימי לימודו של רבה. הביאו עוד מה ש\u0003אמר רבה: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב הונא איבעיא לן\u0004 \u0005[נשאלה לנו\u0006 שאלה זו\u0005]:\u0006 \u0003בר בי רב דיתיב בתעניתא במעלי שבתא\u0004 \u0005[תלמיד בבית הרב היושב בתענית בערב שבת],\u0006 \u0003מהו לאשלומי\u0004 \u0005[שישלים]\u0006 תעניתו עד סופה בערב שבת. ושמא נאמר שצריך להפסיק לפני השבת, כדי שלא יכנס לשבת כשהוא עייף מתעניתו. \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003אתאי לקמיה\u0004 \u0005[באתי לפני]\u0006 \u0003רב יהודה\u0004 אחר כך \u0003ולא הוה בידיה\u0004 \u0005[היתה\u0006 אף \u0005בידו]\u0006 תשובה,","\u0003אמר רבא: נחזייה אנן\u0004 \u0005[נראה אנו\u0006 בעצמנו\u0005]\u0006 פתרון מתוך המקורות, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תשעה באב שחל להיות בשבת\u0004"],["\u0003וכן ערב תשעה באב שחל להיות בשבת\u0004 אינו מצמצם אכילתו כפי שהיה צריך לנהוג אילו היה חל ביום חול, אלא \u0003אוכל ושותה כל צרכו, ומעלה על שולחנו אפילו כסעודת שלמה בשעתו. חל להיות תשעה באב בערב שבת — מביאין לו כביצה\u0004 בסוף היום \u0003ואוכל. כדי שלא יכנס לשבת כשהוא מעונה.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: פעם אחת היינו יושבין לפני ר' עקיבא, ותשעה באב שחל להיות בערב שבת היה. והביאו לו ביצה מגולגלת\u0004 (מבושלת מעט) \u0003וגמעה בלא מלח. ולא שהיה תאב לה\u0004 עד כדי כך, \u0003אלא להראות לתלמידים הלכה,\u0004 שאין צריך להשלים את תעניתו בתשעה באב שחל בערב שבת, כדי לא להיכנס לשבת כשהוא מעונה.","\u0003ור' יוסי אומר: מתענה ומשלים. אמר להן ר' יוסי: אי אתם מודים לי בתשעה באב שחל להיות באחד בשבת, שמפסיק מבעוד יום\u0004 השבת שלפניו? משמע, שמוסיף משעות השבת על הצום, וכן נעשה אף בערב שבת. \u0003אמרו לו: אבל\u0004 (אכן, כן הוא). \u0003אמר להם: מה לי ליכנס בה\u0004 בשבת, \u0003כשהוא מעונה. מה לי לצאת ממנה כשהוא מעונה,\u0004 שהרי אם הוא מתחיל לצום מבעוד יום, הרי הוא צם זמן מה ביום השבת.","\u0003אמרו לו:\u0004 יש הבדל, \u0003אם אמרת\u0004 לענין \u0003לצאת ממנה\u0004 מן השבת כשהוא מעונה — \u0003שהרי אכל ושתה כל היום כולו,\u0004 ואינו סובל אם מתענה דקות אחדות, \u0003תאמר ליכנס בה כשהוא מעונה,\u0004 כ\u0003שלא אכל ושתה כל היום כולו.\u0004","\u0003ואמר עולא: הלכה כר' יוסי,\u0004 ובתשעה באב שחל בערב שבת מתענה ומשלים. ושואלים: \u0003ומי עבדינן\u0004 \u0005[והאם עושים אנו]\u0006 \u0003כר' יוסי? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו: \u0003אין גוזרין\u0004 מלכתחילה \u0003תענית על הציבור בראשי חדשים, בחנוכה ובפורים. ואם התחילו\u0004 מחזור תעניות, ונזדמנה תענית בימים אלה — \u0003אין מפסיקין, דברי רבן גמליאל. אמר ר' מאיר: אף על פי שאמר רבן גמליאל\u0004 ש\u0003אין מפסיקין, מודה היה שאין משלימין\u0004 תענית באותם ימים, \u0003וכן\u0004 אין משלימים \u0003בתשעה באב שחל להיות בערב שבת.\u0004","\u0003ותניא\u0004 \u0005[ושנינו\u0006 על כך בברייתא\u0005]:\u0006 \u0003לאחר פטירתו של רבן (שמעון בן) גמליאל, נכנס ר' יהושע להפר את דבריו\u0004 לענין תעניות. \u0003עמד ר' יוחנן בן נורי על רגליו ואמר: חזי אנא דבתר רישא גופא אזיל\u0004 \u0005[רואה\u0006 \u0005אני שלאחר הראש הולך הגוף]\u0006 ולדעתי יש ללכת אחר דברי הראשונים הגדולים ולא לסטות מהלכות שקבעו. \u0003כל ימיו של רבן גמליאל קבענו הלכה כמותו, עכשיו אתה מבקש לבטל דבריו?! יהושע, אין שומעין לך, שכבר נקבעה הלכה כרבן גמליאל, ולא היה אדם שערער בדבר כלום.\u0004 ואם כן, מברייתא זו למדים אנו שתשעה באב שחל להיות בערב שבת — מתענים ואין משלימים, וכן אמנם נהגו למעשה.","ואמנם את הקושיה דוחים, שאין מכאן ראיה גמורה, כי אמנם \u0003בדורו של רבן גמליאל עבוד\u0004 \u0005[עשו]\u0006 \u0003כרבן גמליאל,\u0004 ואילו \u0003בדורו של ר' יוסי עבוד\u0004 \u0005[עשו]\u0006 \u0003כר' יוסי,\u0004 ומאז נהגו לפסוק כמותו.","ושואלים לגופו של דבר: \u0003ובדורו של רבן גמליאל\u0004 עצמו האם \u0003עבוד\u0004 \u0005[עשו]\u0006 \u0003כרבן גמליאל? והתניא\u0004 \u0005[והרי שנינו],\u0006 \u0003אמר ר' אלעזר בן צדוק\u0004 שהיה בן דורו של רבן גמליאל: \u0003אני הייתי מבני סנאב בן בנימין\u0004 ולהם נקבע יום טוב משפחתי בעשרה באב. \u0003פעם אחת חל תשעה באב להיות בשבת, ודחינוהו לאחר השבת,\u0004 שהרי אין מתענים תשעה באב בשבת, \u0003והתענינו בו, ולא השלמנוהו\u0004 את צום תשעה באב, \u0003מפני שיום טוב שלנו היה,\u0004 ומכאן נדייק: \u0003טעמא\u0004 \u0005[טעם\u0006 הדבר דוקא\u0005]\u0006 שהיה הוא עצמו \u0003יום טוב, הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003ערב יום טוב\u0004 בלבד — \u0003משלימין!\u0004 ואם כן נמצא שבערבי שבתות וימים טובים מתענים ומשלימים, אפילו בדורו של רבן גמליאל!","\u0003אמר רבינא\u0004: שאין להקשות מסיפור זה כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003יום טוב של דבריהם\u0004 שתקנוהו חכמים, שאינו חמור כיום טוב האמור בתורה. והרי חגם של בני סנאב איננו חג מן התורה, כי רק חכמים קבעוהו. ו\u0003מתוך שמתענין בו שעות,\u0004 שהתירו להתענות חלק מן היום ביום טוב של דבריהם, אף \u0003משלימין בו\u0004 גם \u0003ערביות\u0004 (להתענות עד שיעריב היום). ואולם ב\u0003שבת, הואיל ואין מתענין בה\u0004 אפילו \u0003שעות —\u0004 אף \u0003אין משלימין בה ערביות.\u0004","\u0003אמר רב יוסף: לא שמיע לי הא שמעתא\u0004 \u0005[לא שמעתי הלכה זו]\u0006 שפוסקים כר' יוסי (רב יוסף חלה ושכח את תלמודו, ולא זכר שנאמרה הלכה זו). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את אמרת ניהלן, ואהא אמרת ניהלן\u0004 \u0005[אתה אמרת לנו\u0006 הלכה זו, \u0005ועל\u0006 דבר \u0005זה אמרת\u0006 אותה \u0005לנו]:\u0006 שנינו ש\u0003אין גוזרין תענית על הציבור בראשי חדשים,\u0004 בחנוכה ובפורים, \u0003ואמרינן עלה\u0004 \u0005[ואמרנו עליה\u0006 על ברייתא זו\u0005],\u0006 \u0003אמר רב יהודה אמר רב: זו דברי ר' מאיר שאמר משום\u0004 (בשם) \u0003רבן גמליאל\u0004 שאין משלימים, וכן בענין תשעה באב שחל בערב שבת, \u0003אבל חכמים אומרים: מתענה ומשלים.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מה שאמרו חכמים \"מתענה ומשלים\" נאמר \u0003אכולהו\u0004 \u0005[על כולם],\u0006 כלומר על כל הפרטים שנזכרו בברייתא, כולל בענין תשעה באב שחל להיות בערב שבת? \u0003לא,\u0004 הדבר נאמר רק ביחס ל\u0003חנוכה ופורים\u0004 שאם קבעו בהם תענית — מתענין ומשלימים, אבל לא לענין קביעת תענית בערב שבת.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר"],["\u0003דאי סלקא דעתך אכולהו\u0004 \u0005[שאם עולה על דעתך\u0006 לומר ש\u0005על כולם]\u0006 אמר רב יהודה שהלכה כחכמים — \u0003הא בעי מיניה\u0004 \u0005[הרי\u0006 כבר אמרנו ש\u0005שאל ממנו]\u0006 \u0003רבה מרב יהודה\u0004 בנושא זה \u0003ולא פשט ליה\u0004 \u0005[פתר לו]!\u0006 משמע שבנושא זה לא היתה הלכה פסוקה בידו.","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 שסבור אתה שאין פתרון לדבר, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא: הלכה, מתענה ומשלים\u0004 בערב שבת. \u0003הא בעא מיניה\u0004 \u0005[הרי שאל ממנו]\u0006 \u0003רבה\u0004 גם \u0003מרב הונא ולא פשט ליה\u0004 \u0005[פתר לו],\u0006 וכיצד יכול מר זוטרא לומר הלכה משמו של רב הונא?!","\u0003אלא\u0004 על כרחך תאמר: \u0003הא\u0004 \u0005[זו] —\u0006 \u0003מקמי\u0004 \u0005[לפני]\u0006 ש\u0003שמעה, והא\u0004 \u0005[וזו] —\u0006 \u0003לבתר\u0004 \u0005[לאחר]\u0006 ש\u0003שמעה,\u0004 שלאחר ששמע רב הונא הלכה זו בשם רב נפתרה לו הבעיה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי רב יהודה אפשר לומר: \u0003הא\u0004 \u0005[זו] —\u0006 \u0003מקמי\u0004 \u0005[לפני]\u0006 ש\u0003שמעה,\u0004 הלכה בשם רב ולכן לא ידע להשיב לרבה, \u0003והא\u0004 \u0005[וזו] —\u0006 \u0003לבתר\u0004 \u0005[לאחר]\u0006 ש\u0003שמעה,\u0004 והיה בידו פתרון.","וחוזרים על מה שהזכרנו ובדרך אגב: \u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא: הלכה, מתענין ומשלימים\u0004 בתענית שחל להיות בערב שבת וחג. \u0003מי שהוציאוהו גוים\u0004 בעל כורחו מחוץ לתחום, \u0003או\u0004 שיצא מחמת \u0003רוח רעה,\u0004 שנטרפה דעתו לפי שעה, ולא ידע מה הוא עושה, וכשנתפכח מצא שהוא מחוץ לתחום — \u0003אין לו\u0004 רשות להלך \u0003אלא ארבע אמות\u0004 מן המקום בו הוא עומד.","","","אם \u0003החזירוהו\u0004 הגוים, או חזר מחמת הרוח רעה — \u0003כאילו לא יצא.\u0004 ומהלך בתחומו כדרכו.","אם \u0003הוליכוהו\u0004 הגוים \u0003לעיר אחרת\u0004 המוקפת מחיצות, או \u0003נתנוהו בדיר או בסהר\u0004 (מקום מוקף הקבוע עבור בהמות), נחלקו חכמים בדבר: \u0003רבן גמליאל ור' אלעזר בן עזריה אומרים: מהלך את\u0004 העיר \u0003כולה,\u0004 שהעיר כולה נחשבת כארבע אמות. ואילו \u0003ר' יהושע ור' עקיבא אומרים: אין לו אלא ארבע אמות\u0004 ממש ממקומו.","מסופר: \u0003מעשה שבאו\u0004 חכמים \u0003מפלנדרסין\u0004 שבמדינת הים, \u0003והפליגה ספינתם בים\u0004 בשבת, \u0003רבן גמליאל ור' אלעזר בן עזריה הלכו את\u0004 הספינה \u0003כולה,\u0004 שאמרו שכולה כארבע אמות. ואילו \u0003ר' יהושע ור' עקיבא לא זזו מארבע אמות, שרצו להחמיר על עצמן.\u0004","ועוד מסופר: \u0003פעם אחת לא נכנסו לנמל עד שחשיכה\u0004 בליל שבת, \u0003אמרו לו לרבן גמליאל: מה אנו לירד,\u0004 כלומר: האם כבר היינו בתחום העיר מבעוד יום? \u0003אמר להם: מותרין אתם\u0004 לרדת, \u0003שכבר הייתי מסתכל והיינו בתוך התחום עד שלא חשיכה,\u0004 ולכן קנינו שביתה לעצמנו בעיר בין השמשות, ויכולים אנו ללכת אליה אף משחשיכה. כיון שהוזכר במשנה אדם שעבר את התחום מפני רוח רעה, מביאים עוד בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003שלושה דברים מעבירין את האדם על דעתו ועל דעת קונו, ואלו הן: גוים, ורוח רעה, ודקדוקי עניות,\u0004 כלומר: עניות יתירה הגורמת לאדם לעתים לשנות מדעת עצמו, ואף לעבור על דעת קונו.","","","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה]\u0006 כשיודעים על הדברים האלה? ומשיבים: \u0003למיבעי רחמי עלייהו\u0004 \u0005[\u0006כדי \u0005לבקש רחמים עליהם]\u0006 שלא יבואו לידי כך. ומעין זה אמרו: \u0003שלושה\u0004 סוגי אנשים \u0003אין רואין פני גיהנם\u0004 משום שחייהם מלאים סבל בעולם הזה ועוונותיהם מתכפרים, ואלו \u0003הן: דקדוקי עניות,\u0004 אדם המדוכדך בעניות, \u0003וחולי מעיין, והרשות,\u0004 אדם שלוחצים עליו נושים. \u0003ויש אומרים: אף מי שיש לו אשה רעה.\u0004","","ושאלו: \u0003ואידך\u0004 \u0005[והאחר],\u0006 שאינו מונה אשה רעה, מדוע אינו מחשיב זו המציקה לו בכל עת? ומשיבים: \u0003אשה רעה מצוה לגרשה,\u0004 ויש תקנה לצרה זו. \u0003ואידך\u0004 \u0005[והאחר]\u0006 המונה אשה רעה, מדוע מונה זאת? משיבים: \u0003זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003כתובתה מרובה\u0004 ואינו יכול לגרשה משום שאין בידו ממון מספיק כדי לשלם דמי כתובתה. \u0003אי נמי, אית ליה בנים מינה, ולא מצי מגרש לה\u0004 \u0005[או גם כן, יש לו בנים ממנה, ואינו יכול לגרש אותה],\u0006","","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכך]\u0006 שיודעים כל זאת? ומשיבים: \u0003לקבולי\u0004 \u0005[לקבל]\u0006 יסורים אלה \u0003מאהבה\u0004 שכן הוא יודע שבגללם הוא נפטר מעונש גהינם. ועוד אמרו: \u0003שלושה מתין כשהן מספרין,\u0004 כלומר עשויים למות פתאום אפילו נראה שמצבם טוב ויכולים הם לשוחח, \u0003ואלו הן: חולי מעיין, וחיה\u0004 \u0005[יולדת],\u0006 \u0003ו\u0004החולה במחלת ה\u0003הדרוקן.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה\u0006 מידיעה זו\u0005]\u0006 ומשיבים: \u0003למשמושי בהו זוודתא\u0004 \u0005[להכין להם תכריכים]\u0006 שמא יצטרכו להם פתאום.","","","ומעתה חוזרים לענין ההלכה שבמשנה. \u0003אמר רב נחמן אמר שמואל: יצא לדעת\u0004 מתוך התחום — \u0003אין לו אלא ארבע אמות.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003השתא\u0004 \u0005[\u0006הרי\u0005, עכשיו]\u0006 \u0003מי שהוציאוהו גוים\u0004 על כרחו, \u0003אין לו אלא ארבע אמות, יצא לדעת מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין לו יותר מארבע אמות?!","\u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003חזר לדעת\u0004 בזדון אל תוך התחום, לאחר שהוציאוהו גויים — \u0003אין לו אלא ארבע אמות\u0004 ולא יותר.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[הרי\u0006 דבר \u0005זה גם כן שנינו]\u0006 מדקדוק בדברי המשנה: \u0003החזירוהו גוים — כאילו לא יצא,\u0004 ונדייק: \u0003החזירוהו — הוא\u0004 ש\u0003כאילו לא יצא, אבל הוציאוהו גוים וחזר לדעת\u0004 — הרי זה כאילו יצא לדעת — ו\u0003אין לו אלא ארבע אמות!\u0004","\u0003אלא אימא\u0004 \u0005[אמור,\u0006 \u0003תקן\u0004\u0005]\u0006 שכך אמר רב נחמן: \u0003יצא לדעת והחזירוהו גוים\u0004 על כורחו — \u0003אין לו אלא ארבע אמות,\u0004 אף שהחזירוהו על כורחו.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו]\u0006 אם נדייק בדברי המשנה, שהרי נאמר: \u0003הוציאוהו והחזירוהו — כאילו לא יצא,\u0004 ונדייק: \u0003הוציאוהו והחזירוהו הוא\u0004 המקרה ש\u0003כאילו לא יצא, אבל יצא לדעת — לא!\u0004","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ותדחה ראיה זו: שמא \u0003לצדדין קתני\u0004 \u0005[נשנתה]\u0006 שמא לא נאמרו דברי המשנה כיחידה אחת אלא הכוונה לשני מקרים נפרדים: \u0003מי שהוציאוהו גוים וחזר לדעת — אין לו אלא ארבע אמות, אבל יצא לדעת והחזירוהו גוים — כאילו לא יצא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף אם יצא לדעת והחזירוהו גוים נחשב כחוזר לדעת, ואין לו אלא ארבע אמות.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרבה:\u0004 אם אותו אדם העומד בתחום ארבע אמות \u0003הוצרך לנקביו\u0004 ואין לו מקום צנוע לעשותם \u0003מהו? אמר להם:\u0004 כבר נקבע הכלל \u0003גדול כבוד הבריות שדוחה\u0004 אף \u0003את לא תעשה שבתורה,\u0004 ומותר לו לצאת מן התחום שקבעו חכמים, אף על פי שנאסר לעבור על דבריהם בלאו של \"לא תסור\", כדי לעשות צרכיו בצינעה.","\u0003אמרי נהרדעי:\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]\u0006 \u0003אי פיקח הוא\u0004 אדם זה, הרי כיון שניתנה לו רשות \u0003עייל לתחומא\u0004 [יכול הוא \u0005להיכנס\u0006 לשם כך \u0005אל תוך תחום\u0006 העיר ואחר כך \u0003כיון דעל — על\u0004 \u0005[שנכנס\u0006 ברשות \u0005—\u0006 \u0005נכנס]\u0006 ויכול להישאר שם. \u0003אמר רב פפא: פירות שיצאו\u0004 ביום טוב \u0003חוץ לתחום וחזרו, אפילו\u0004 הוציאום \u0003במזיד — לא הפסידו את מקומן\u0004 ומותר לטלטלם בכל התחום. ומה טעם? \u0003אנוסין נינהו\u0004 \u0005[הם]\u0006 שהרי לא יצאו הפירות מדעת עצמם.","","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יוסף בר שמעיה לרב פפא\u0004 מברייתא, \u0003ר' נחמיה ור' אליעזר בן יעקב אומרים: לעולם אסורין\u0004 הפירות, \u0003עד שיחזרו למקומן שוגגין.\u0004 ומכאן נדייק: \u0003בשוגג — אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואולם \u0003במזיד — לא!\u0004","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בכך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003פירות שיצאו חוץ לתחום, בשוגג — יאכלו, במזיד — לא יאכלו.\u0004"],["\u0003ר' נחמיה אומר:\u0004 אם חזרו ל\u0003מקומן — יאכלו, שלא במקומן שעדיין הם מחוץ לתחום — לא יאכלו,\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003במקומן? אילימא\u0004 \u0005[אם תאמר]\u0006 שחזרו ל\u0003מקומן במזיד — והא קתני בהדיא\u0004 \u0005[והרי שנינו במפורש],\u0006 \u0003ר' נחמיה ור' אליעזר בן יעקב אומרים: לעולם אסורין עד שיחזרו למקומן שוגגין,\u0004 משמע: \u0003בשוגג — אין\u0004 \u0005[כן]\u0006 \u0003במזיד — לא.\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003במקומן\u0004 משמעו שחזרו \u0003בשוגג\u0004 למקומם, \u0003וחסורי מחסרא, והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא, \u0005וכך יש לשנותה]:\u0006 \u0003פירות שיצאו חוץ לתחום, בשוגג — יאכלו, במזיד — לא יאכלו.\u0004","\u0003במה דברים אמורים — שלא במקומן\u0004 כלומר, שעדיין לא חזרו למקומם, \u0003אבל\u0004 אם הם \u0003במקומן — אפילו במזיד יאכלו. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' נחמיה למימר\u0004 \u0005[לומר]:\u0006 \u0003אפילו במקומן נמי\u0004 \u0005[גם כן]\u0006 \u0003בשוגג — אין\u0004 \u0005[כן,\u0006 מותר\u0005]\u0006 \u0003במזיד — לא.\u0004","את ההסבר הזה דוחים: \u0003לא,\u0004 אין זה מחייב, ואפשר גם לבאר כך: \u0003במזיד במקומן — דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003אסור, והכא\u0004 \u0005[וכאן]\u0006 — \u0003בשוגג שלא במקומן פליגי\u0004 \u0005[נחלקו]:\u0006 \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003סבר\u0004 שאם יצאו \u0003בשוגג שרי\u0004 \u0005[מותר\u0006 לאוכלם\u0005]\u0006 אפילו \u0003שלא במקומן, ור' נחמיה סבר: אפילו שוגג,\u0004 אם חזרו והם \u0003במקומן — אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואם הם עדיין \u0003שלא במקומן — לא.\u0004","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[הרי ממה ששנינו\u0006 ב\u0005סופה\u0006 של ברייתא זו\u0005]:\u0006 \u0003ר' נחמיה ור' אליעזר בן יעקב אומרים: לעולם אסורין עד שיחזרו למקומן שוגגין.\u0004 הרי אפשר לדייק מכאן בבירור כי: \u0003שוגג — אין\u0004 \u0005[כן,\u0006 מותר\u0005]\u0006 אולם \u0003במזיד — לא,\u0004 ואם ר' נחמיה סבור כי המזיד אסור אפילו במקומם, \u0003מכלל דתנא קמא\u0004 \u0005[מכאן שהתנא הראשון]\u0006 \u0003סבר: במזיד נמי שרי\u0004 \u0005[גם כן מותר]\u0006 ואם כן, הסבר זה אינו יכול להתקבל, ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[נלמד ממנה\u0006 שכך\u0005].\u0006","\u0003אמר רב נחמן אמר שמואל: היה מהלך\u0004 במקום \u0003ואינו יודע תחום שבת\u0004 שלו היכן הוא, \u0003מהלך אלפים פסיעות בינוניות\u0004 ממקום שביתתו לכל צד שירצה, \u0003וזו היא תחום שבת,\u0004 ששיעורה של פסיעה בינונית הוא אמה בערך.","\u0003ועוד אמר רב נחמן אמר שמואל: שבת בבקעה\u0004 (במישור), \u0003והקיפוה גוים מחיצה בשבת\u0004 לצורך דירה —\u0003 מהלך אלפים אמה\u0004 בלבד, שאינו יכול לסמוך אלא על מחיצות שהיו כבר בשעת קניית השביתה, \u0003ו\u0004אולם \u0003מטלטל בכולה\u0004 אף באותו חלק שמחוץ לאלפים אמה. אולם רק \u0003על ידי זריקה,\u0004 שהרי הוא עצמו אינו יכול להוליך את החפץ הלאה.","\u0003ו\u0004אילו \u0003רב הונא אמר: מהלך אלפים אמה, ו\u0004אולם \u0003מטלטל\u0004 אפילו בשטח זה רק ב\u0003ארבע אמות\u0004 הסמוכות לו כבכרמלית. ושאלו: \u0003ו\u0004מדוע לא \u0003ניטלטל\u0004 \u0005[יטלטל]\u0006 \u0003בכולה על ידי זריקה?\u0004 שכן אף על פי שהוא עצמו אינו יכול להלך בכולה, הרי מכל מקום מחיצה היא זו, ויהיה מותר לטלטל בתוכה!","ומשיבים: \u0003שמא ימשך אחר חפצו,\u0004 והרי הוא אסור לצאת מתחום אלפיים אמה, ואם יטלטל בזריקה — שמא יצא אחרי חפצו מתחום המותר לו.","ושואלים: \u0003ב\u0004תוך \u0003אלפיים\u0004 אמה \u0003מיהת לטלטל כי אורחיה\u0004 \u0005[בכל אופן שיטלטל כדרכו]?\u0006 שהרי מותר לו מלכתחילה להלך בהם, ואין חשש שמא ימשך!","ומשיבים שדבר זה נאסר מצד אחר בדיני עירובין, \u0003משום דהוי\u0004 \u0005[שהוא]\u0006 \u0003כמחיצה שנפרצה במלואה למקום האסור לה.\u0004 שהרי יותר מאלפים אמה אינו יכול לטלטל, והבקעה כולה מוקפת ביותר מאלפיים אמה, ונמצא שהחלק המותר לו פרוץ כולו לחלק האחר האסור לו, ולכן נאסר הטלטול בכולה אפילו על ידי זריקה.","ואילו \u0003חייא בר רב אמר: מהלך אלפים אמה, ומטלטל\u0004 כדרכו אפילו שלא על ידי זריקה \u0003באלפים אמה.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 ש\u0003לא כ\u0004שיטת \u0003רב נחמן ולא כ\u0004שיטת \u0003רב הונא,\u0004 והרי לכאורה אין מקום כאן במחלוקת זו לשיטה שלישית!","ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003מטלטל בארבע\u0004 אמות. ושואלים: \u0003אי הכי, היינו\u0004 \u0005[אם כך\u0006 תתקן, \u0005הרי זו]\u0006 ממש שיטתו של \u0003רב הונא.\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003וכן אמר ר' חייא בר רב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא: לא תיפלוג עליה דשמואל\u0004 \u0005[אל תחלוק עליו,\u0006 על שיטת \u0005שמואל]\u0006 שהביאה רב נחמן משמו בענין זה של בקעה שהוקפה מחיצה בשבת, \u0003דתניא כוותיה\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 הברייתא \u0005כמותו].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003היה מודד\u0004 תחום שבת שלו \u0003ובא\u0004 ממקום שהניח בו עירובו, \u0003וכלתה מדתו בחצי העיר — מותר לטלטל בכל העיר כולה, ובלבד שלא יעבור את התחום ברגליו\u0004. שלא יצא מחצי העיר, שהוא סוף תחומו. ואם אינו יוצא ברגליו \u0003במאי\u0004 \u0005[במה]\u0006 \u0003מטלטל\u0004 בעיר, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003על ידי זריקה?\u0004 וקשה לרב הונא האוסר לטלטל על ידי זריקה במקום שאסור לו להלך בו.","\u0003אמר רב הונא: לא,\u0004 הכוונה היא שמטלטל בעיר רק \u0003על ידי משיכה,\u0004 שמותר לו למשוך חפצים מחצי העיר האחר אל המקום שבו הוא נמצא, שבכך אין לחשוש שמא יבוא להימשך אחר החפץ, שכן הוא מקרב את החפץ אליו.","\u0003אמר רב הונא\u0004 בדומה לכך: \u0003היה מודד\u0004 תחום שבת שלו \u0003ובא\u0004 ממקום שהניח עירובו, \u0003וכלתה מדתו בחצי חצר — אין לו אלא חצי חצר\u0004.","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאין לו רשות להלך יותר מתחום שבת שלו! ומשיבים \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003יש לו חצי חצר\u0004 כלומר חידש לנו רב הונא צד אחר, שמותר לו לטלטל בחציה זה של החצר.","ומקשים: \u0003האי נמי פשיטא\u0004 \u0005[גם\u0006 דבר \u0005זה פשוט]\u0006 כי מדוע יאסר עליו הטלטול ברשות היחיד שהוא מותר להלך בה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש דלמא אתי לטלטולי\u0004 \u0005[נחשוש שמא יבוא לטלטל]\u0006 \u0003ב\u0004חצר \u0003כולה,\u0004 ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לנו לחשוש לכך.","\u0003אמר רב נחמן: מודה לי\u0004 רב \u0003הונא\u0004 במקרה דומה שאין גוזרים משום שמא ימשך: מי ש\u0003היה מודד\u0004 תחום שבת שלו \u0003ובא\u0004 ממקום שהניח בו עירובו \u0003וכלתה מדתו על שפת תקרה,\u0004 כלומר תחת תקרה, אף שחלק הבית שמתחתיה נפרץ שהבית עצמו מחוץ לתחומו — \u0003מותר לטלטל בכל הבית\u0004 על ידי זריקה,","\u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003הואיל ותקרת הבית חובטת.\u0004 כלומר, תקרת הבית נראית לו כמחיצה, ואין לחשוש שיעבור מחיצה זו וימשך אחר חפצו.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן:\u0004 מחלוקת שמואל ורב הונא אם גוזרים שמא ימשך, יסודה \u0003כתנאי\u0004 \u0005[\u0006במחלוקת \u0005תנאים].\u0006 שאף הם נחלקו באותו נושא, ומחלוקת זו במשנתנו: מי ש\u0003הוליכוהו\u0004 בעל כורחו \u0003לעיר אחרת\u0004 מחוץ לתחום, \u0003ונתנוהו בדיר או בסהר\u0004 שהיו שם, \u0003רבן גמליאל ור' אלעזר בן עזריה אומרים: מהלך את כולה\u0004 את הדיר והסהר כולו, שכיון שהם מוקפים במחיצה, כל שטחם נחשב כארבע אמות בלבד. ואילו \u0003ר' יהושע ור' עקיבא אומרים: אין לנו אלא ארבע אמות.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר \u0003רבן גמליאל ור' אלעזר בן עזריה\u0004 ש\u0003אמרו: מהלך את כולה —\u0004 ש\u0003לא גזרי\u0004 \u0005[גזרו]\u0006 \u0003הילוך\u0004 שמותר ב\u0003דיר וסהר אטו\u0004 \u0005[משום]\u0006 \u0003הילוך בבקעה\u0004 ואמרו שכיון שהדיר מוקף במחיצה אינו דומה לבקעה שבה אסור לצאת מארבע אמות שלו,","\u0003ומדהילוך אטו הילוך לא גזרי, טלטול אטו הילוך לא גזרי\u0004 \u0005[ומ\u0006כיון \u0005שהילוך\u0006 מותר \u0005משום הילוך\u0006 אסור \u0005לא גזרו,\u0006 ודאי שב\u0005טלטול משום הילוך לא גזרו],\u0006 ובוודאי יתירו בבקעה שהוקפה בשבת על ידי גויים טלטול שעל ידי זריקה אפילו יותר מאלפיים אמה ולא יגזרו, כשם שלא גזר שמואל.","\u0003ו\u0004אילו \u0003ר' יהושע ור' עקיבא\u0004 ש\u0003אומרים: אין לו אלא ארבע אמות,\u0004 ודאי הטעם משום \u0003דגזרי\u0004 \u0005[שגזרו]\u0006 \u0003הילוך דיר וסהר אטו\u0004 \u0005[משום]\u0006 \u0003הילוך בקעה, ומדהילוך אטו הילוך גזרי, טלטול אטו הילוך נמי גזרי\u0004 \u0005[ומ\u0006מכיון \u0005שהילוך משום הילוך גזרו, טלטול משום הילוך גם כן גזרו]\u0006 וכשיטת רב הונא.","את ההשוואה הזאת דוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה שכן הוא? \u0003דילמא כי לא גזרי\u0004 \u0005[שמא כאשר לא גזרו]\u0006 \u0003רבן גמליאל ור' אלעזר בן עזריה הילוך סהר ודיר אטו\u0004 \u0005[משום]\u0006 \u0003הילוך בקעה, הני מילי התם\u0004 \u0005[דברים אלה\u0006 אמורים רק \u0005שם]\u0006 ש\u0003שני מקומות\u0004 שונים \u0003הן,\u0004 ואין לגזור במקום אחד מחשש שבמקום אחר לא ינהג כדין.","\u0003אבל\u0004 לגזור \u0003טלטול אטו\u0004 \u0005[משום]\u0006 \u0003הילוך\u0004 ש\u0003מקום אחד הוא, הכי נמי דגזרי\u0004 \u0005[כך גם כן\u0006 נאמר \u0005שגוזרים\u0006 הם\u0005]\u0006 \u0003שמא ימשך אחר חפצו\u0004 ויהלך במקום האסור לו.","וכן גם אפשר לדחות את ההשוואה מצד שני: \u0003ור' יהושע ור' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003ממאי דמשום דגזרי\u0004 \u0005[ממה\u0006 מסיק אתה \u0005ש\u0006אסרו \u0005משום שגזרו]\u0006 \u0003הוא? דילמא משום דקא סברי כי אמרינן\u0004 \u0005[שמא משום שהן סוברים כאשר אומרים אנו]:\u0006 \u0003כל הבית כולו כארבע אמות דמי\u0004 \u0005[נחשב],\u0006 הרי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003שבת באויר מחיצות\u0004 של אותו בית \u0003מבעוד יום\u0004, ואז נחשב הבית כולו כארבע אמות.","\u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא שבת באויר מחיצות מבעוד יום לא\u0004 נחשב הבית וכל שכן דיר וסהר כארבע אמות, אלא נמדד כשיעור אמות שבו, ואין הדבר אומר כלל לענין טלטול על ידי זריקה מחוץ לאלפיים אמה. ואם כן אין הכרח להשוות מחלוקת זו למחלוקת שבין רב נחמן ורב הונא.","\u0003אמר רב: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבן גמליאל בדיר וסהר וספינה. ושמואל אמר:\u0004 הלכה \u0003כרבן גמליאל בספינה, אבל בדיר וסהר — לא.\u0004","ושואלים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מיהת\u0004 \u0005[בכל אופן]\u0006 \u0003הלכה כרבן גמליאל בספינה, מאי טעמא\u0004 \u0005[ומה הטעם]\u0006 שונה הלכה זו משאר המקרים?","\u0003אמר רבה: הואיל ושבת באויר\u0004 (בתוך חלל) \u0003מחיצות\u0004 של ספינה \u0003מבעוד יום\u0004 ואז סברה פשוטה היא לומר שהספינה כולה נחשבת כארבע אמות בלבד.","\u0003ר' זירא אמר: הואיל\u0004 ואי אפשר להגביל את מקום הספינה \u0003וספינה נוטלתו מתחילת ארבע\u0004 אמות \u0003ומנחתו בסוף ארבע\u0004 אמות אחרות. הרי בין כה וכה אינו מצוי בתחום אחד של ארבע אמות גם אם ירצה בכך, ולכן מסתבר להתיר ולומר שאין דין ארבע אמות כלל בכל הספינה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם\u0006 ההבדל למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 כאשר \u0003נפחתו\u0004 (נשברו) \u0003דופני ספינה\u0004 ואם כן שוב אינו מצוי בין המחיצות. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בקופץ מספינה לספינה,\u0004 והרי לא שבת מבעוד יום בספינה השניה, ואולם נימוקו של ר' זירא קיים גם במקרים אלה.","ושואלים: \u0003ור' זירא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003לא אמר כרבה?\u0004 שלכאורה נימוקו פשוט ביותר? ומשיבים \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003מחיצות\u0004 ספינה אין לראותן כמחיצות גמורות, שכן אלה רק כדי"],["\u0003להבריח מים עשויות,\u0004 שאין המחיצות בספינה מיועדות להכשירה לדירה אלא להגן מפני המים. ולכן אינן כמחיצות שנעשו לצורך דירה.","ושואלים: \u0003ורבה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' זירא?\u0004 ומשיבים: \u0003ב\u0004מצב שבו היתה הספינה \u0003מהלכת — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים],\u0006 שאף ר' יהושע ור' עקיבא מתירים בספינה שאיננה קבועה במקומה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004ספינה \u0003שעמדה,\u0004 שלדעת ר' יהושע אין מחיצותיה חשובות, ולדעת רבן גמליאל מחיצותיה מועילות.","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דיקא דבמהלכת לא פליגי\u0004 \u0005[משנתנו גם כן מדוייקת שב\u0006ספינה \u0005מהלכת לא נחלקו]\u0006 ושואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיקים דבר זה? \u0003מדקתני\u0004 \u0005[מ\u0006הלשון \u0005ששנינו]:\u0006 \u0003מעשה שבאו מפלנדרסין והפליגה ספינתם בים, רבן גמליאל ור' אלעזר בן עזריה הלכו את\u0004 כל הספינה \u0003כולה, ור' יהושע ור' עקיבא לא זזו מארבע אמות, שרצו להחמיר על עצמן.\u0004","ומעתה נדייק: \u0003אי אמרת בשלמא\u0004 \u0005[נניח שאומר אתה]\u0006 \u0003במהלכת לא פליגי\u0004 \u0005[נחלקו]\u0006 — \u0003היינו דקתני\u0004 \u0005[זה הוא ששנינו]\u0006 \u0003\"רצו\",\u0004 כלומר רצו להחמיר על עצמן ולא שהיו חייבים בכך, אלא חששו \u0003דילמא עמדה\u0004 \u0005[שמא תעמוד].\u0006","\u0003אלא אי אמרת פליגי\u0004 \u0005[אם אומר אתה\u0006 ש\u0005נחלקו]\u0006 אף בספינה מהלכת, \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"רצו להחמיר\"\u0004 אינה מובנת, שהרי כאן אין לדבר על רצון להחמיר, שכן לשיטתם \u0003איסורא\u0004 \u0005[איסור\u0006 גמור\u0005]\u0006 \u0003הוא!\u0004","\u0003אמר רב אשי\u0004 והוסיף על כך: \u0003מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 מצד אחר, \u0003דקתני\u0004 \u0005[ששנינו\u0006 בה\u0005]:\u0006 \u0003ספינה, דומיא\u0004 \u0005[בדומה]\u0006 \u0003לדיר וסהר. מה דיר וסהר — דקביעי\u0004 \u0005[ש\u0006הם \u0005קבועים],\u0006 \u0003אף ספינה נמי דקביעא\u0004 \u0005[גם כן ש\u0006היא \u0005קבועה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 הלא אמרו רב ושמואל \u0003הלכה כרבן גמליאל בספינה,\u0004 ואם אמרו \u0003הלכתא\u0004 \u0005[\u0006נפסקה \u0005הלכה]\u0006 \u0003— מכלל דפליגי\u0004 \u0005[מכאן שנחלקו\u0006 באותו דבר\u0005]\u0006 והרי מן הלשון \"שרצו להחמיר\" נראה כי בעיקרי הדברים לא נחלקו כלל!","ענה לו: \u0003אין\u0004 \u0005[כן]\u0006 \u0003והתניא\u0004 \u0005[וכן\u0006 אמנם \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003חנניא בן אחי ר' יהושע אומר: כל אותו היום\u0004 שהיו בספינה \u0003ישבו ודנו בדבר הלכה, אמש הכריע אחי אבא\u0004 (הוא ר' יהושע) \u0003הלכה כרבן גמליאל בספינה\u0004 המהלכת שמותר לטלטל בכולה, \u0003והלכה כר' עקיבא בדיר וסהר\u0004 שאין להלך אלא בתוך ארבע אמות, והוא הדין גם בספינה עומדת.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חנניא\u0004: האם \u0003יש\u0004 איסור \u0003תחומין למעלה מעשרה\u0004 טפחים, \u0003או\u0004 שמא \u0003אין תחומין למעלה מעשרה?\u0004 כלומר האם גבול תחום שבת הוא על הקרקע בלבד, ואם יכול בדרך כלשהי להלך גבוה יותר מעשרה טפחים מותר לו?","ומפרטים את הבעיה; \u0003עמוד גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה,\u0004 וחלקו האחד בתוך התחום והשני מחוצה לו, \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שעמוד יציב כזה \u0003דארעא סמיכתא\u0004 \u0005[ש\u0006כ\u0005אדמה צפופה]\u0006 \u0003היא\u0004 ודינו כקרקע ממש, אף שהוא שונה בגובהו משאר מקומות,","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, יהא זה \u0003בעמוד גבוה עשרה ואינו רחב ארבעה\u0004 וכיוצא בו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003דקאזיל\u0004 \u0005[שהולך]\u0006 \u0003בקפיצה\u0004 (בקפיצת הדרך) בדרך נס למעלה מעשרה טפחים.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 אפשר לשאול את השאלה: \u0003בספינה\u0004 שעל פני הים, הגבוהה למעלה מעשרה טפחים מקרקע הים או הנהר, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 האם יש בה איסור תחומין או אין?","\u0003אמר רב הושעיא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו: \u0003מעשה שבאו מפלנדרסין והפליגה ספינתם בים וכו', אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003יש תחומין\u0004 למעלה מעשרה — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003רצו\u0004 ר' עקיבא ור' יהושע להחמיר. \u0003אלא, אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003אין תחומין — אמאי\u0004 \u0005[מדוע]\u0006 \u0003רצו\u0004 להחמיר, הלא אין תחומין למעלה מעשרה?!","ומתרצים כי אפשר לומר כאן כפי ש\u0003אמר רבא\u0004 לענין דומה, שמדובר כשהיתה הספינה \u0003מהלכת ברקק (בבוץ), הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003במהלכת ברקק,\u0004 והיתה סמוכה לקרקע בפחות מעשרה טפחים וודאי חל עליה איסור תחומים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו בהמשך הדברים: \u0003פעם אחת לא נכנסו לנמל עד שחשיכה וכו'. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003יש תחומין\u0004 למעלה מעשרה — \u0003שפיר\u0004 \u0005[יפה]\u0006 שאלוהו אם מותר להם לרדת לחוף, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003אין תחומין — כי\u0004 \u0005[כאשר]\u0006 אפילו \u0003לא היינו בתוך התחום\u0004 מבעוד יום, ויש מקום לחשש בענין זה, כדבריהם, \u0003מאי הוי\u0004 \u0005[מה נהיה\u0006 על ידי כך\u0005]\u0006 הרי היו למעלה מעשרה ואין איסור תחומין חל עליהם!","\u0003אמר רבא\u0004 שכאן היה מקרה מיוחד שהיתה הספינה \u0003מהלכת ברקק\u0004 — בתוך עשרה טפחים.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מן המעשה הידוע ב\u0003הני שב שמעתא דאיתאמרן בצפרא בשבתא קמיה\u0004 \u0005[אותן שבע הלכות שנאמרו בבוקר השבת לפני]\u0006 \u0003רב חסדא בסורא, בהדי פניא בשבתא\u0004 \u0005[קרוב למוצאי השבת]\u0006 נאמרו אותן הלכות עצמן \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא בפומבדיתא\u0004 והמרחק גדול מכדי שיעבור אותו אדם בדרך הטבע באותו יום.","\u0003מאן אמרינהו\u0004 \u0005[מי אמר\u0006 אותן\u0005]\u0006 שמועות והעבירן ממקום למקום? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אליהו\u0004 הנביא \u0003אמרינהו\u0004 \u0005[אמרן],\u0006 והלך בקפיצת הדרך למעלה מעשרה, ועבר מסורא לפומבדיתא? \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אין תחומין למעלה מעשרה!\u0004 שבוודאי לא היה אליהו עובר עבירה זו. ומשיבים: \u0003לא,\u0004 אין זו הוכחה, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003יוסף שידא\u0004 \u0005[השד]\u0006 שאיננו שומר שבת \u0003אמרינהו\u0004 \u0005[אמרן\u0006 את ההלכות הללו\u0005].\u0006","ומנסים להביא ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 מי שאמר \u0003הריני נזיר ביום שבן דוד בא\u0004 (ביום שמשיח בא בו) — \u0003מותר לשתות יין בשבתות ובימים טובים,\u0004 שאז משיח איננו בא,"],["\u0003ואסור לשתות יין כל ימות החול,\u0004 שמא בא משיח ועדיין לא נודע לו.","ומעתה נאמר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם תאמר]\u0006 \u0003יש תחומין\u0004 למעלה מעשרה — \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם ש\u0003בשבתות ובימים טובים מותר\u0004 לו לשתות יין, שוודאי לא יבוא המשיח מחוץ לתחום ביום זה. \u0003אלא אי אמרת\u0004 \u0005[אם תאמר]\u0006 \u0003אין תחומין, בשבתות וימים טובים אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותר\u0004 לו לשתות יין?","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[המקרא,\u0006 הכתוב\u0005]\u0006 \u0003\"הנה אנכי שלח לכם את אליה הנביא\u0004 לפני בא יום ה' הגדול והנורא והשיב לב אבות על בנים ולב בנים על אבותם\u0003\"\u0004 (מלאכי ג, כג), שמפסוק זה למדים שאליהו מקדים ביום את ביאת המשיח, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא אתא\u0004 \u0005[בא]\u0006 \u0003אליהו מאתמול,\u0004 ודאי לא יבוא משיח היום ויכול הוא לשתות.","ודוחים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 גם \u0003בחול כל יומא ויומא נמי לישתרי, דהא לא אתא\u0004 \u0005[יום ויום גם כן יהא מותר\u0006 לו\u0005, שהרי לא בא]\u0006 \u0003אליהו מאתמול, אלא\u0004 ודאי טעם האיסור בימות החול כי \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 אליהו \u0003לבית דין הגדול אתא\u0004 \u0005[הגיע],\u0006 ועדיין אין כל אדם יודע על כך. אם כן, \u0003הכא נמי לימא\u0004 \u0005[כאן גם כן נאמר]:\u0006 \u0003לבית דין הגדול אתא\u0004 \u0005[בא]\u0006 אליהו מאתמול! ושמא בא בערב השבת?","ומשיבים: \u0003כבר מובטח להן לישראל שאין אליהו בא לא בערבי שבתות ולא בערבי ימים טובים, מפני הטורח.\u0004 שמתוך שיבואו להקביל פניו, לא יספיקו להכין את כל צרכי שבת וחג.","\u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתנו\u0006 לומר\u0005]\u0006 \u0003מדאליהו לא אתא — משיח נמי לא אתי\u0004 \u0005[מכיון שאליהו לא יבוא\u0006 בערב שבת מפני הטורח\u0005, משיח גם כן לא יבוא]\u0006 אם כן, \u0003במעלי שבתא לישתרי\u0004 \u0005[בערב שבת יהא מותר\u0006 לו לשתות יין\u0005]!\u0006 ודוחים: \u0003אליהו — לא אתי, משיח — אתי\u0004 \u0005[אליהו אינו בא\u0006 בערבי שבתות\u0005, משיח בא]\u0006 כי \u0003דכיון דאתי משיחא\u0004 \u0005[שכיון שבא המשיח]\u0006 — \u0003הכל עבדים הן לישראל,\u0004 ויעזרו להם להכין את צרכי השבת כראוי.","ומקשים: \u0003בחד בשבא לישתרי\u0004 \u0005[באחד בשבת יהא מותר]?\u0006 שאם אליהו אינו יכול לבא ביום השבת, לא יבוא המשיח באחד בשבת, \u0003לפשוט מינה\u0004 \u0005[שנפתור מכאן]\u0006 ש\u0003אין תחומין\u0004 למעלה מעשרה, \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 \u0003יש תחומין\u0004 למעלה מעשרה — \u0003בחד בשבא לישתרי, דלא אתא\u0004 \u0005[באחד בשבת יהא מותר, ש\u0006הרי \u0005לא\u0006 יכול \u0005לבוא]\u0006 \u0003אליהו בשבת?!\u0004","ומשיבים: \u0003האי תנא ספוקי מספקא ליה\u0004 \u0005[תנא זה מסופק]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003יש תחומין\u0004 למעלה מעשרה \u0003או אין תחומין, ו\u0004פסק בדברים אלה \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 גם לגבי יום ראשון.","ושואלים, \u0003דקאי אימת דקא\u0004 \u0005[מתי עמד\u0006 אותו אדם \u0005ש\u0006הוא\u0005]\u0006 \u0003נדר? אילימא דקאי\u0004 \u0005[אם תאמר שעמד]\u0006 \u0003בחול ונדר — כיון\u0004 ש\u0003חל עליה\u0004 \u0005[עליו]\u0006 כבר ה\u0003נזירות, היכי אתיא שבתא ומפקעא ליה\u0004 \u0005[כיצד\u0006 יכולה \u0005לבוא השבת ולהפקיע אותה]?\u0006 והרי נזירות אינה יכולה לחול יום אחד ולהתבטל ביום האחר, ואם חלה הנזירות — תוקפה לכל תקופת הזמן שנדר בה!","\u0003אלא דקאי בשבתא וקא נדר וביום טוב וקא נדר\u0004 \u0005[שהיה עומד בשבת ונודר\u0006 נדר זה\u0005, או ביום טוב ונודר]\u0006 \u0003וההוא יומא דשרי ליה\u0004 \u0005[ואותו יום\u0006 הוא \u0005שמותר לו]\u0006 שהרי לא בא משיח, \u0003מיכן ואילך\u0004 (מכאן והלאה) — \u0003אסיר ליה\u0004 \u0005[אסור לו],\u0006 שחל נדר הנזירות ואין תוקפו פג מכאן ואילך אפילו בימי שבת וימים טובים.","במשנה מסופר כי \u0003פעם אחת לא נכנסו לנמל,\u0004 ושאלו את רבן גמליאל אם יכולים לרדת לחוף, ואמר שצופה היה ויודע מתי נכנסו לתחום הנמל ומותר להם.","כדי להבהיר את הדבר מביאים ברייתא: \u0003תנא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שפופרת\u0004 (משקפת) מיוחדת \u0003היתה לו לרבן גמליאל שהיה מביט וצופה בה\u0004 מרחק מדוייק של \u0003אלפים אמה ביבשה, וכנגדה\u0004 היה יכול לקבוע גם מרחק של \u0003אלפים אמה בים.\u0004","ובדרך כלל אומרים ש\u0003הרוצה לידע כמה עומקו של גיא, מביא שפופרת\u0004 כזו \u0003ומביט בה, וידע כמה עומקו של גיא.\u0004","ועוד אמרו בענין אפשרויות מדידה: ו\u0003הרוצה לידע כמה גובהו של דקל\u0004 ואינו רוצה למדוד ממש על ידי טיפוס עליו — \u0003מודד קומתו\u0004 של עצמו \u0003וצלו\u0004 של עצמו, \u0003וצל קומתו\u0004 של הדקל ומחשב \u0003וידע כמה גובהו של דקל\u0004.","ובדומה לזה אמרו: \u0003הרוצה שלא תשרה חיה רעה בצל קבר\u0004 משום כבוד המת — \u0003נועץ קנה בארבע שעות ביום\u0004 (בערך בשעה עשר לפני הצהרים) שהיא שעה בה חם לאור השמש וצונן בצל, ובשעה זו מוצאות להן החיות מחסה בצל, \u0003ויראה להיכן צלו\u0004 של הקנה \u0003נוטה,\u0004 ובאותה זוית יהא \u0003משפיע ועולה משפיע ויורד\u0004 את המצבה בשיפוע כזה שבשעה זו לא תטיל צל, ולא תבוא החיה לנוח ליד הקבר בשעות החום.","מסופר: \u0003נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנילאי משכתיה שמעתא\u0004 \u0005[משכה אותו ההלכה],\u0006 שהיה הוגה בה עד שלא שם לב \u0003ונפק\u0004 \u0005[ויצא]\u0006 \u0003חוץ לתחום. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב נחמן: נחמיה תלמידך שרוי בצער,\u0004 שהוא עומד מחוץ לתחום ואינו יכול להיכנס, מה נעשה לו?","\u0003אמר לו: עשה לו מחיצה של בני אדם,\u0004 שיעברו אנשים שמותר להם להיות שם באותו מקום, וייצרו כעין מחיצה על ידי שורה של בני אדם וילך ביניהם, וכך יגיע עד התחום \u0003ויכנס\u0004 בתוכו.","\u0003יתיב\u0004 \u0005[ישב]\u0006 באותה שעה \u0003רב נחמן בר יצחק אחוריה\u0004 \u0005[מאחורי]\u0006 \u0003רבא, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 בשורה הראשונה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: מאי קא מבעיא ליה\u0004 \u0005[מה היתה\u0006 השאלה \u0005שנשאלה לו]\u0006 \u0003רב חסדא\u0004 שהצטרך לפתרונו של רב נחמן?","\u0003אילימא בדמלו גברי\u0004 \u0005[אם תאמר ב\u0006מקום \u0005ש\u0006היה \u0005מלא אנשים]\u0006 שעירבו ויכולים לצאת מחוץ לתחום עד למקומו \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003וקא מבעיא ליה\u0004 \u0005[ו\u0006השאלה \u0005שנשאלה לו\u0006 היתה\u0005]:\u0006 האם \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבן גמליאל\u0004 שמחיצות מועילות לאדם אפילו אם לא שבת בהן מבעוד יום והוא הדין למחיצה אנושית זו."],["\u0003או אין הלכה כרבן גמליאל. או דילמא, בדלא מלו גברי\u0004 \u0005[או שמא בשלא היו מלאים אנשים]\u0006 שעירבו ויכולים להלך עד למקומו \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 אלא רק כדי שיעשו מחיצה עד שתי אמות סמוך לרב נחמיה, ומשם יכנס לתחום, כדברי ר' אליעזר בדין הבלעת תחומין (לקמן עירובין נב,ב), \u0003וקא מבעיא ליה\u0004 \u0005[ונשאלה לו\u0006 השאלה\u0005]:\u0006 אם \u0003הלכה כר' אליעזר או אין הלכה כר' אליעזר?\u0004","ומשיבים: \u0003פשיטא\u0004 \u0005[ברור]\u0006 \u0003בדלא מלו גברי עסקינן\u0004 \u0005[בשלא היו מלאים אנשים עוסקים אנו],\u0006 \u0003דאי סלקא דעתך בדמלו גברי עסקינן, מאי תיבעי ליה\u0004 \u0005[שאם עולה על דעתך שבשהיו מלאים באנשים אנו עוסקים, מה נשאל לו]?\u0006 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב: הלכה כרבן גמליאל בדיר וסהר וספינה! אלא ודאי בדלא מלו גברי עסקינן\u0004 \u0005[ב\u0006מקרה \u0005שלא היו מלאים אנשים עוסקים אנו],\u0006 ולענין הלכה של \u0003ר' אליעזר קמיבעיא ליה\u0004 \u0005[נשאלה לו].\u0006","ומעירים: \u0003דיקא נמי, דקאמר ליה\u0004 \u0005[מדוייק גם כן שאמר לו]\u0006 \u0003\"יכנס\". מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"יכנס\" לאו\u0004 \u0005[האם לא]\u0006 משמעו שיכנס אף \u0003בלא מחיצה\u0004 באותן שתי אמות נוספות. שלפני שנכנס למחיצה זו, עליו עוד להיכנס מעצמו בלי מחיצה שתי אמות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן בר יצחק לרבא\u0004 על עצם העקרון של עשיית מחיצה אנושית, ממה שנאמר בברייתא: \u0003נפל דופנה\u0004 של סוכה בשבת, ומחוסר דפנות נפסלה לשמש כסוכת מצוה — \u0003לא יעמיד בה אדם בהמה וכלים\u0004 כדי ליצור בזה מעין דופן. \u0003ולא יזקוף את המטה לפרוס עליה סדין\u0004 ולעשותה כעין מחיצה, \u0003לפי שאין עושין אהל עראי בתחילה ביום טוב, ואין צריך לומר בשבת.\u0004 ורואים אם כן שאדם אינו יכול לשמש כמחיצה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את\u0004 \u0005[אתה]\u0006 \u0003אמרת לי מהא, ואנא אמינא לך מהא\u0004 \u0005[מ\u0006ברייתא \u0005זו, ואני אומר לך מ\u0006ברייתא \u0005זו,\u0006 אחרת\u0005]\u0006 שאמרו בה: \u0003עושה אדם את חבירו דופן כדי שיאכל וישתה וישן\u0004 בסוכה, \u0003ו\u0004כן מותר ש\u0003יזקוף את המטה ויפרוס עליה סדין\u0004 מלמעלה \u0003כדי שלא תפול חמה על המת\u0004 או \u0003על האוכלין\u0004.","ומעירים, ואם כן נמצא ששתי ברייתות אלה \u0003קשיין אהדדי\u0004 \u0005[קשות זו על זו]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זו] —\u0006 של \u0003ר' אליעזר הא\u0004 \u0005[זו] —\u0006 של \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003: פקק החלון\u0004 (תריס שאינו קבוע בצירים) \u0003ר' אליעזר אומר: בזמן שקשור\u0004 בקיר \u0003ותלוי\u0004 בחלון — \u0003פוקקין בו\u0004 את החלון, \u0003ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אין פוקקין בו\u0004 את החלון, לפי שאין עושין אוהל ואפילו עראי בשבת. \u0003וחכמים אומרים: בין כך ובין כך פוקקין בו.\u0004 נמצא שהתירו חכמים לעשות מעין דופן בשבת, והם שהתירו אף בסוכה.","\u0003ומקשים: והא איתמר עלה\u0004 \u0005[והרי\u0006 כבר \u0005נאמר עליה\u0006 על מחלוקת זו\u0005],\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הכל מודים שאין עושין אהל עראי בתחילה ביום טוב, ואין צריך לומר בשבת. לא נחלקו\u0004 חכמים ור' אליעזר \u0003אלא להוסיף\u0004 על אוהל עראי; \u0003שר' אליעזר אומר: אין מוסיפין\u0004 אף \u0003ביום טוב, ואין צריך לומר בשבת. וחכמים אומרים: מוסיפין\u0004 על אוהל עראי \u0003בשבת, ואין צריך לומר ביום טוב!\u0004 ואם כן אין מי שמתיר לעשות דופן לכתחילה!","\u0003אלא\u0004 מנסים לתרץ באופן אחר; \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 ואין סתירה בין הברייתות כי \u0003הא\u0004 \u0005[זו]\u0006 המתירה בהעמדת בהמה או אדם כדופן — \u0003כר' מאיר. הא\u0004 \u0005[זו]\u0006 האוסרת — \u0003כר' יהודה\u0004. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשאה לבהמה דופן לסוכה — ר' מאיר פוסל,\u0004 כיון שחושש שמא תברח הבהמה, \u0003ור' יהודה מכשיר.\u0004","\u0003ר' מאיר דקא פסיל התם\u0004 \u0005[שפוסל שם\u0006 בסוכה\u0005]\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהוא סבור שמחיצה העשויה מבעל חי \u0003לא מחיצה היא, הכא שרי\u0004 \u0005[כאן\u0006 לענין שבת \u0005מתיר],\u0006 \u0003דלאו מידי קא עביד\u0004 \u0005[\u0006לפי \u0005שאינו עושה דבר]\u0006 שהרי אין זו קרויה בנייה של ממש.","\u0003ור' יהודה דקא מכשיר התם\u0004 \u0005[שהוא מכשיר שם\u0006 בסוכה\u0005]\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מחיצה היא,\u0004 לכן \u0003הכא\u0004 \u0005[כאן\u0006 בשבת\u0005]\u0006 \u0003אסר\u0004 לעשות מחיצה כזו.","על הסבר זה מקשים: \u0003ותיסברא\u0004 \u0005[וכי יכול אתה לסבור אותה\u0006 סברה\u0005]?\u0006 והרי \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו\u0006 את\u0005]\u0006 \u0003ר' מאיר\u0004 שפוסל ב\u0003בהמה\u0004 אבל \u0003אדם וכלים מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שפסל אותם להיות מחיצה ראויה? שהרי החסרון הקיים בבהמה שמא תברח אינו קיים באדם וכלים, שהרי אדם יש לו דעת וימשיך לעמוד, וגם הכלי לא יזוז ממקומו, ומכיון שהברייתא התירה מחיצת אדם וכלים גם כן, הרי שאינה משיטת ר' מאיר.","\u0003ותו\u0004 \u0005[ועוד],\u0006 אפילו לא תחלק ויש לו טעם בכך — שמא תברח, \u0003ר' מאיר אליבא דמאן\u0004 \u0005[לפי\u0006 שיטת \u0005מי\u0006 סבר\u0005]\u0006 לעיקר דין הוספת מחיצה עראית בשבת? \u0003אי אליבא\u0004 \u0005[אם לפי\u0006 שיטת\u0005]\u0006 \u0003ר' אליעזר\u0004 רבו בענין פקק החלון — הרי \u0003להוסיף נמי\u0004 \u0005[גם כן]\u0006 \u0003אסר.\u0004","\u0003אלא\u0004 תאמר שהלך \u0003אליבא דרבנן\u0004 \u0005[לפי\u0006 שיטת \u0005חכמים],\u0006 הרי אף לשיטתם \u0003אימר דאמרי רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 שמותר \u0003להוסיף\u0004 על אוהל ארעי, אבל \u0003לכתחילה מי אמור\u0004 \u0005[האם אמרו]\u0006 שמותר לעשות מחיצה ואוהל?","\u0003אלא\u0004 כך יש לפרש: \u0003הא והא רבנן\u0004 \u0005[זו וזו\u0006 לפי שיטת \u0005חכמים],\u0006 וכך יש ליישב את הקשיים: מ\u0003כלים\u0004 על \u0003כלים לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאסר לעשות דופן נוספת — מדובר \u0003בדופן שלישית\u0004 שהיא העושה את הכשר הסוכה למצותה, \u0003הא\u0004 \u0005[זו]\u0006 שהותר — הכוונה לעשיית \u0003דופן רביעית\u0004 שאינה חשובה, כיון שהסוכה אינה מוכרחה להיות בעלת ארבעה דפנות.","\u0003דיקא נמי\u0004 \u0005[ונדייק גם כן],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בברייתא האוסרת דיוק לשון זה: \u0003נפל דופנה\u0004 — משמע, דופנה המיוחד, דופנה החשוב המתיר בה, ולא דופן סתם, כברייתא המתירה. ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[נלמד ממנה,\u0006 שכך\u0005].\u0006"],["\u0003אלא מאדם על אדם קשיא\u0004 \u0005[קשה],\u0006 כי בברייתא אחת נאמר שאסור לעשות אדם דופן לסוכה, ובאחרת אמרו שעושה את חבירו דופן, אף שנאמר בה במפורש שיכול לעשות כן \"כדי שיאכל וישתה וישן\", שהוא הכשר סוכה גמור. הרי איפוא אף שחסרה הדופן השלישית, הותר הדבר לשיטת ברייתא זו!","ומשיבים: \u0003מאדם על אדם נמי לא קשיא\u0004 \u0005[גם כן לא קשה]\u0006 \u0003כאן\u0004 שאסרו — הרי זה כאשר שימש אותו אדם מחיצה \u0003לדעת, כאן\u0004 שהתירו — הרי זה כשעמד אדם ונעשה מחיצה \u0003שלא מדעת,\u0004 ואין דרך בנין בכך. מה שאין כן לגבי העמדת כלי, שכיון שאין בו דעת, כל אופן שיעמידנו הריהו מחיצה גמורה ואסור.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 אותו מקרה ב\u0003ר' נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חנילאי לדעת הוה\u0004 \u0005[היה]!\u0006 שכן אמרו לאנשים ללכת לשם להיות מחיצה. ומשיבים: \u0003שלא מדעת הוה\u0004 \u0005[היה].\u0006 כלומר, אותם אנשים לא ידעו לשם מה קראו להם, ושלא מדעתם נעשו כמחיצה.","ועדיין מקשים: והלא \u0003רב חסדא\u0004 שקבץ את האנשים והביאם למקום, \u0003מיהא\u0004 \u0005[לפחות]\u0006 הוא \u0003לדעת הוה\u0004 \u0005[היה\u0006 שם\u0005]!\u0006 ומשיבים: אכן היה שם \u0003רב חסדא\u0004 לדעת, אבל \u0003שלא מן המנין הוה\u0004 \u0005[היה]\u0006, כלומר לא הצטרף עם אלה שהיו כמחיצה.","מסופר: \u0003הנהו בני גננא\u0004 \u0005[אותם בני חופה]\u0006 שהשתמשו ברוב האדם שהיה במקום בכך \u0003דאעילו מיא\u0004 \u0005[שהכניסו מים]\u0006 לרשות היחיד בשבת \u0003במחיצה של בני אדם\u0004 שלא ידעו שמשמשים כמחיצה לשם כך. \u0003נגדינהו\u0004 \u0005[הלקה אותם,\u0006 צוה להלקותם\u0005]\u0006 \u0003שמואל. אמר\u0004 על כך: \u0003אם אמרו\u0004 חכמים שמחיצה מועילה \u0003שלא מדעת, יאמרו\u0004 ויתירו מלכתחילה גם \u0003לדעת?!\u0004","וכן מספרים: \u0003הנהו זיקי דהוה שדיין בריסתקא דמחוזא\u0004 \u0005[אותם נודות שהיו מוטלים ברחובה של מחוזא\u0006 בשבת\u0005]\u0006 ולא יכלו לטלטלם, \u0003בהדי דאתא\u0004 \u0005[בזמן שבא]\u0006 \u0003רבא מפירקיה\u0004 \u0005[מדרשתו]\u0006 והיה כל העם מלוה אותו, \u0003אעלינהו ניהליה\u0004 \u0005[הכניסום\u0006 המשרתים \u0005לביתו],\u0006 שבתוך רוב העם המלווים נוצרה מחיצה של בני אדם והשתמשו בה לצורך זה. \u0003לשבתא אחריתי בעי עיילינהו, ואסר להו\u0004 \u0005[לשבת אחרת רצו להכניסם\u0006 שוב\u0005, ואסר להם]\u0006 וטעמו: \u0003דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003כ\u0004דבר שהוא \u0003לדעת, ואסור,\u0004 שהרי כבר יודעים אנשים שמשתמשים בהם אף לצורך זה.","ומסופר שבהמון אנשים שנאסף כך בשבת שלא מדעת \u0003לוי, אעילו ליה תיבנא\u0004 \u0005[הביאו לו תבן],\u0006 ובאופן זה הביאו ל\u0003זעירי אספסתא\u0004 \u0005[אספסת],\u0006 ול\u0003רב שימי בר חייא\u0004 הביאו כך \u0003מיא\u0004 \u0005[מים].\u0006","\u0003מי שיצא\u0004 מתחום שבת \u0003ברשות,\u0004 כגון שיצא להעיד על מולד הלבנה או לצורך סכנת נפשות. \u0003ואמרו לו\u0004 בתוך דרכו: \u0003\"כבר נעשה מעשה\"\u0004 ואין צורך עוד בך לאותו ענין — \u0003יש לו אלפים אמה לכל רוח\u0004 מאותו מקום שנאמרו לו הדברים.","\u0003אם היה בתוך התחום\u0004 הראשון שלו — הריהו נחשב \u0003כאילו לא יצא,\u0004 ויכול לחזור למקומו. כלל אמרו: \u0003כל היוצאין\u0004 להילחם על מנת \u0003להציל — חוזרין למקומם\u0004 בשבת.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אם היה בתוך התחום כאילו לא יצא\"?\u0004 הרי ודאי לא יצא! \u0003אמר רבה: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003אם היה בתוך התחום שלו\u0004 — \u0003כאילו לא יצא מתוך ביתו דמי\u0004 \u0005[נחשב]\u0006 ויש לו עדיין אלפיים אמה לכל צד מביתו","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שכן הוא הדין שאם נשאר בתוך תחומו הריהו כבתוך ביתו, ומה צורך להשמיענו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הואיל ועקר\u0004 ממקומו, והתכוון להיות במקום אחר, \u0003עקר\u0004 ובטל מקום שביתתו הקודם, ושוב אין זה תחומו, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלמרות זאת כאילו לא יצא מתחום ביתו.","\u0003רב שימי בר חייא אמר\u0004 הסבר אחר בדברי המשנה: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 מדובר שיצא יותר מאלפיים אמה מתחום ביתו, ו\u0003אם היו תחומין שנתנו לו חכמים\u0004 — אותם אלפיים אמות לכל רוח, \u0003מובלעין בתוך התחום שלו,\u0004 ואם ילך אלפיים אמה יחזור אל תוך היקף תחום השבת הראשון שלו \u0003כאילו לא יצא מתחומו.\u0004","ומעירים: \u0003במאי קמיפלגי\u0004 \u0005[במה נחלקו]\u0006 רבה ורב שימי בר חייא? \u0003מר\u0004 \u0005[חכם זה\u0006 רב שימי\u0005]\u0006 \u0003סבר\u0004 כי \u0003הבלעת תחומין,\u0004 שכיון ששני תחומים מובלעים זה בזה במקצתם אפשר לעבור מזה לזה, \u0003מילתא היא\u0004 \u0005[דבר הוא],\u0006 שיש להתחשב בו ולסמוך עליו, \u0003ומר\u0004 \u0005[וחכם זה\u0006 רבה\u0005]\u0006 \u0003סבר לאו מילתא היא\u0004 \u0005[אינה דבר]\u0006 ואין לסמוך עליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: ואת לא תסברא\u0004 \u0005[וכי אתה אינך סבור]\u0006 ש\u0003הבלעת תחומין מילתא היא\u0004 \u0005[דבר הוא]\u0006 ואפשר לסמוך על כך? \u0003ומה אילו שבת במערה\u0004 שיש לה שני פתחים בשני צידיה, \u0003שבתוכה\u0004 (אורכה) \u0003ארבעת אלפים\u0004 אמות \u0003ועל גגה\u0004 (המרחק בין פתחיה) \u0003פחות מארבעת אלפים אמה\u0004, האם \u0003לא נמצא מהלך את\u0004 כל המערה \u0003כולה, וחוצה לה אלפים אמה.\u0004 שכן כל המערה נחשבת לו כארבע אמות, ויכול להלך מכל פתח שלה עוד אלפיים אמה לכל צד. וכיון שיכול הוא להלך מפתחה שבצד אחד אלפיים אמה אף אחורנית על גבי גגה וכן מפתחה השני. ומאחר שעל גגה פחות מארבעת אלפים אמה, נמצא ששני תחומים אלה מובלעים זה בזה, ויכול להלך על כל גב המערה משום הבלעת תחומין אף יותר מתחום שבת.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולא שני לך בין היכא\u0004 \u0005[וכי אינו שונה לך\u0006 בעיניך \u0005בין היכן,\u0006 מצבו של מי\u0005]\u0006 ש\u0003שבת באויר מחיצות מבעוד יום, להיכא\u0004 \u0005[להיכן,\u0006 למצבו של מי\u0005]\u0006 ש\u0003לא שבת באויר מחיצות מבעוד יום?\u0004 שלשובת מבעוד יום באויר מחיצות המערה בלבד התירו הבלעת תחומין.","ומקשה אביי: \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003לא שבת, לא\u0004 תהא הבלעת תחומין?"],["\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' אליעזר אומר:\u0004 מי שיצא חוץ לתחום \u0003שתים\u0004 כלומר שתי אמות — \u0003יכנס, שלש\u0004 אמות — \u0003לא יכנס. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ר' אליעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 שארבע אמות שנותנים לו לאדם היכן שהוא הכוונה ש\u0003הוא באמצען,\u0004 כלומר שיש לו לכל צד שתי אמות,","\u0003ו\u0004אם כן \u0003ארבע אמות דיהבו ליה רבנן, כמאן דמיבלען דמו\u0004 \u0005[שנתנו לו חכמים, כמי שהיו מובלעות\u0006 בתוך התחום \u0005נחשבו],\u0006 \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003\"יכנס\", אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הבלעת תחומין מילתא היא\u0004 \u0005[דבר הוא]\u0006 והרי זה עקרון שראוי להתחשב בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר בר חנה לאביי: ומ\u0004דברי \u0003ר' אליעזר קמותבת ליה למר\u0004 \u0005[מקשה אתה לרבינו]?\u0006 והרי אין הלכה כר' אליעזר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין, דשמיע לי מיניה דמר\u0004 \u0005[כן, ששמעתי ממנו,\u0006 מפי \u0005רבינו]:\u0006 \u0003עד כאן לא פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 על \u0003ר' אליעזר אלא\u0004 ביחס ליוצא \u0003לדבר הרשות, אבל\u0004 ליוצא \u0003לדבר מצוה — מודו ליה\u0004 \u0005[מודים לו]\u0006 שהבלעת תחומים מועילה, משמע שבכל זאת יש דין הבלעת תחומים בהלכה.","נאמר במשנה: \u0003וכל היוצאין להציל חוזרין למקומן.\u0004 ושואלים: \u0003ואפילו טובא\u0004 \u0005[הרבה]\u0006 יותר מאלפיים אמה לכל צד? \u0003והא אמרת רישא\u0004 \u0005[והרי אמרת\u0006 ב\u0005תחילה]:\u0006 \u0003\"אלפים אמה\", ותו לא\u0004 \u0005[ולא עוד]!\u0006","\u0003אמר רב יהודה אמר רב\u0004: הכוונה היא \u0003שחוזרין בכלי זיין למקומן.\u0004 ותוהים על עצם השאלה: \u0003ומאי קושיא\u0004 \u0005[ומהי הקושיה]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003להציל שאני\u0004 \u0005[שונה]!\u0006 שהיוצא להציל התירו לו לחזור למקומו עם כלי זיינו בידו, שהרי יש חשש שמא ירדפו אחריו האויבים בחזרתו!","\u0003אלא אי קשיא, הא קשיא\u0004 \u0005[אם\u0006 יש מקום \u0005להקשות, זהו הקושי],\u0006 שהלא שנינו במסכת ראש השנה: עדים שבאו בשבת ממקום רחוק לירושלים להעיד שראו את מולד הלבנה, \u0003בראשונה\u0004 היו מביאים את אלו שבאו להעיד עדות החודש לחצר מיוחדת ו\u0003לא היו זזין משם כל היום כולו,\u0004 כדין היוצא חוץ לתחום. שכן כיון שמלאו שליחותם בהיתר, שוב אינם יוצאים מארבע אמות.","\u0003התקין רבן גמליאל הזקן שיש להן אלפים אמה לכל רוח,\u0004 כדי שלא יימנעו עדים מלבוא להעיד. \u0003ולא אלו בלבד אמרו\u0004 שנותנים להם אלפיים אמה במקום שהגיעו אליו, \u0003אלא אפילו חכמה\u0004 \u0005[מיילדת]\u0006 \u0003הבאה לילד, והבא להציל מן הגייס\u0004 של גוים, \u0003ומן הנהר ומן המפולת ומן הדליקה — הרי הן כאנשי העיר\u0004 שבאו אליה, \u0003ויש להן אלפים אמה לכל רוח.\u0004","ועל כך יש לשאול: \u0003ותו לא\u0004 \u0005[ולא עוד,\u0006 לא יותר מאלפיים אמה\u0005]?\u0006 \u0003והא אמרת\u0004 \u0005[והרי אמרת\u0006 במשנתנו\u0005]:\u0006 \u0003כל היוצאין להציל חוזרין למקומן.\u0004 משמע \u0003אפילו טובא\u0004 \u0005[הרבה]\u0006 יותר מאלפיים אמה!","על כך \u0003אמר רב יהודה אמר רב:\u0004 אין לדייק שמותר לחזור יותר מאלפיים אמה, אלא להדגיש \u0003שחוזרין\u0004 כשם שהלכו \u0003בכלי זיין למקומן, כדתניא\u0004 \u0005[כפי ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003בראשונה היו מניחין\u0004 החוזרים מלהציל את \u0003כלי זיינן בבית\u0004 הראשון שבעיר \u0003הסמוך לחומה,\u0004 שלא רצו לטלטל בשבת יותר מן ההכרח.","\u0003פעם אחת הכירו בהן אויבים\u0004 שאינם ממשיכים להלך בכלי זיינם \u0003ורדפו אחריהם, ונכנסו\u0004 המגינים לאותו בית \u0003ליטול כלי זיינן\u0004 כדי להילחם, \u0003ונכנסו אויבים אחריהן\u0004 ונעשתה מהומה רבה. \u0003דחקו\u0004 המגינים \u0003זה את זה, והרגו זה את זה יותר ממה שהרגו\u0004 בהם ה\u0003אויבים. באותה שעה התקינו שיהו חוזרין למקומן\u0004 ממש \u0003בכלי זיינן.\u0004","ואילו \u0003רב נחמן בר יצחק אמר: לא קשיא\u0004 \u0005[לא קשה]\u0006 בדברי המשניות השונות. \u0003כאן,\u0004 שהתירו רק באלפיים אמה — מדובר ב\u0003שנצחו ישראל את אומות העולם\u0004 במלחמה, ולכן אינם מוכרחים לחזור למקומן דווקא. \u0003כאן —\u0004 מדובר \u0003שנצחו אומות העולם את עצמן\u0004 (כלומר את ישראל, אלא משום שלא רצה לומר שניצחו את ישראל, לכן אמר בלשון נקיה \"את עצמן\"), ואז התירו להם לחזור אפילו למקומם.","כיון שהוזכרה מלחמה בשבת מובא מה ש\u0003אמר רב יהודה אמר רב: גוים שצרו על עיירות ישראל — אין יוצאין עליהן בכלי זיינן, ואין מחללין עליהן את השבת,\u0004 וימתינו עד לאחר השבת.","\u0003תניא נמי הכי\u0004 \u0005[ושנוייה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003גוים שצרו וכו'.\u0004 ואולם באותה תוספתא נוסף גם: \u0003במה דברים אמורים, כשבאו\u0004 הגוים לצור \u0003על עסקי ממון,\u0004 שרצונם לשדוד, \u0003אבל באו על עסקי נפשות\u0004 ויש חשש סכנת נפשות בדבר — \u0003יוצאין עליהן בכלי זיינן, ומחללין עליהן את השבת.\u0004","\u0003ובעיר הסמוכה לספר\u0004 (לגבול), \u0003אפילו לא באו\u0004 הגוים \u0003על עסקי נפשות אלא על עסקי תבן וקש\u0004 שרצו לשלול שלל — \u0003יוצאין עליהן בכלי זיינן, ומחללין עליהן את השבת.\u0004 שיש לשמור על הגבול שמירה יתירה, ולא לתת לאויבים דריסת רגל שם.","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: ובבל, כעיר הסמוכה לספר דמיא\u0004 \u0005[נחשבת],\u0006 ויש לצאת בה עם כלי זיין בשבת אפילו על עסקי ממונות. \u0003ותרגומא\u0004 \u0005[ופירושה]:\u0006 העיר \u0003נהרדעא\u0004 שהיא היתה סמוכה לגבול.","\u0003דרש ר' דוסתאי\u0004 ש\u0003מן\u0004 העיירה \u0003בירי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויגדו לדוד לאמר הנה פלשתים נלחמים בקעילה והמה שסים את הגרנות\"\u0004 (שמואל א' כג, א), ונאמר שם מייד לאחר מכן שדוד שאל מה לעשות בענין זה.","\u0003תנא\u0004 \u0005[שנה]:\u0006 \u0003קעילה עיר הסמוכה לספר היתה, והם\u0004 [אותם פלישתים] \u0003לא באו אלא על עסקי תבן וקש, דכתיב\u0004 שכן נאמר: \u0003\"והמה שסים את הגרנות\"\u0004 (שמואל א' כג, א). \u0003וכתיב \"וישאל דוד בה' לאמר האלך והכיתי בפלשתים האלה ויאמר ה' אל דוד לך והכית בפלשתים והושעת את קעילה\"\u0004 (שמואל א' כג, ב) משמע שיוצאים להציל אף על עסקי תבן וקש.","את ההוכחה מכאן דוחים בשאלה \u0003מאי קמבעיא ליה\u0004 \u0005[מה\u0006 היתה הבעיה ש\u0005נשאלה לו\u0006 לדוד\u0005]\u0006 \u0003אילימא אי שרי אי אסור\u0004 \u0005[אם תאמר\u0006 שנסתפק לו \u0005אם מותר או אסור]\u0006 להילחם בשבת עם הפלישתים — \u0003הרי בית דינו של שמואל הרמתי קיים,\u0004 ולא היה צריך לשאול באורים ובתומים, אלא מפי בית הדין החשוב שבזמנו.","\u0003אלא\u0004 שכך שאל: \u0003אי מצלח אי לא מצלח\u0004 \u0005[אם יצליח או לא יצליח\u0006 במלחמתו\u0005]\u0006 ומעירים: \u0003דיקא נמי\u0004 \u0005[למד גם כן]\u0006 שנסתפק אם יצליח במלחמתו זו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005כתוב]\u0006 שם, כתשובה לשאלתו: \"\u0003לך והכית בפלשתים והושעת את קעילה\", שמע מינה\u0004 \u0005[למד ממנה]\u0006 ממה שנתבשר על נצחונו שזו היתה שאלתו.","\u0003מי שישב בדרך\u0004 ערב שבת עם חשיכה ולא ידע שהוא בתחום העיר, \u0003ועמד וראה\u0004 לאחר כניסת השבת ש\u0003הרי זה הוא סמוך לעיר\u0004 בתוך תחומה. \u0003הואיל ולא היתה כוונתו לכך\u0004 לקנות שביתה בעיר — \u0003לא יכנס\u0004 אל תוכה, אלא ימדוד אלפים אמה ממקומו. אלה \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: יכנס. אמר ר' יהודה: מעשה היה\u0004 כדוגמת זה \u0003ונכנס ר' טרפון\u0004 לעיר \u0003בלא מתכוין,\u0004 שמתחילה לא נתכוון לקבוע שביתה בעיר אלא במקומו.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר ר' יהודה: מעשה בר' טרפון שהיה מהלך בדרך\u0004 בערב שבת \u0003וחשכה לו, ולן חוץ לעיר. לשחרית מצאוהו רועי בקר\u0004 שבאו לרעות את בקרם מחוץ לעיר, \u0003אמרו לו: רבי, הרי העיר לפניך, הכנס! נכנס וישב בבית המדרש, ודרש כל היום כולו\u0004 משמע שמותר להיכנס.","\u0003אמרו לו\u0004 לר' יהודה: וכי \u0003משם ראייה? שמא בלבו היתה\u0004 מבעוד יום לשבות בעיר, \u0003או\u0004 שמא \u0003בית המדרש מובלע בתוך תחומו היה\u0004 שייתכן שבית המדרש היה בתוך אלפיים אמה מהמקום שקנה בו שביתה, ומותר היה לו לכל הדיעות להיכנס לשם.","\u0003מי שישן בדרך ולא ידע שחשיכה — יש לו אלפים אמה לכל רוח, דברי ר' יוחנן בן נורי\u0004 שלדעתו אין צורך בקניית שביתה מתוך ידיעה והכרה, אלא עצם הימצאו במקום מקנה לו שביתה בו.","\u0003ו\u0004אילו \u0003חכמים אומרים: אין לו אלא ארבע אמות\u0004 בלבד, שכיון שלא קנה שביתה מדעת לא נקנה לו תחום שבת. \u0003ר' אליעזר אומר:\u0004 אפילו לא ארבע אמות לכל צד אלא \u0003והוא באמצען,\u0004 כלומר: שתי אמות לכל צד.","\u0003ר' יהודה אומר:\u0004 לא כן, אלא \u0003לאיזה רוח שירצה ילך\u0004 ארבע אמות. \u0003ו\u0004אולם \u0003מודה ר' יהודה, שאם בירר לו\u0004 לאיזה רוח רוצה ללכת אותן ארבע אמות \u0003שאינו יכול לחזור בו\u0004 וללכת ארבע אמות לצד אחר.","\u0003היו שנים\u0004 שנשארו כך, \u0003מקצת\u0004 מארבע \u0003אמותיו של זה בתוך\u0004 ארבע \u0003אמותיו של זה — מביאין\u0004 מזון \u0003ואוכלין\u0004 יחד \u0003באמצע\u0004 בתחום המשותף לשניהם."],["\u0003ובלבד שלא יוציא זה מתוך\u0004 ארבע אמות \u0003שלו לתוך של חבירו.\u0004","\u0003היו שלשה\u0004 שנשארו כך בדרך \u0003והאמצעי מובלע ביניהן\u0004 שתחום ארבע אמותיו בתוך תחומם של שני האחרים — \u0003הוא מותר עמהן, והן מותרין עמו, ושנים החיצונים אסורין\u0004 לאכול \u0003זה עם זה.\u0004 שהרי אין מקום שיהא מותר לשניהם.","\u0003אמר ר' שמעון: למה הדבר דומה — לשלש חצירות הפתוחות זו לזו, ופתוחות לרשות הרבים. עירבו שתים\u0004 החיצוניות \u0003עם\u0004 החצר \u0003האמצעית — היא מותרת עמהן והם מותרות עמה. ו\u0004אולם \u0003שתים החיצונות אסורות זו עם זו,\u0004 שהרי לא עירבו זו עם זו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מאי קסבר\u0004 \u0005[מה סבר,\u0006 מהי סברתו\u0005]\u0006 של \u0003ר' יוחנן בן נורי\u0004 בהלכה שקבע? האם \u0003מסבר קא סבר\u0004 \u0005[סבור הוא]:\u0006 \u0003חפצי הפקר קונין שביתה,\u0004 שאף חפץ שאינו שייך לאיש, כיון שהגיע ליל שבת קונה הוא שביתה לעצמו, ואפשר לטלטלו אלפיים אמה לכל רוח.","\u0003ו\u0004לפי עקרון זה \u0003בדין הוא דליפלוג\u0004 \u0005[שיחלוק]\u0006 אפילו \u0003בכלים\u0004 שנשארו בשדה, שצריך לתת להם אלפיים אמה לכל רוח. \u0003והא דקמיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 \u0003באדם\u0004 הוא \u0003להודיעך כוחן דרבנן\u0004 \u0005[של חכמים]\u0006 להחמיר, \u0003דאף על גב דאיכא למימר\u0004 \u0005[שאף על פי שיש\u0006 מקום \u0005לומר]:\u0006 \u0003הואיל\u0004 ואם היה אותו אדם \u0003ניעור — קנה\u0004 לו אלפיים אמה, אף אם היה \u0003ישן נמי\u0004 \u0005[גם כן]\u0006 \u0003קנה,\u0004 על כן \u0003קא משמע לן דלא\u0004 \u0005[השמיע לנו שלא]\u0006 הודו בכך חכמים, ומשום כך הובאה מחלוקתם לגבי אדם דוקא.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 נפרש באופן אחר, \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוחנן בן נורי בעלמא\u0004 \u0005[בכלל]:\u0006 \u0003חפצי הפקר אין קונין שביתה\u0004 מכוח עצמן, \u0003והכא היינו טעמא\u0004 \u0005[וכאן\u0006 באדם \u0005זהו הטעם]:\u0006 \u0003הואיל\u0004 ואם היה \u0003ניעור\u0004 — \u0003קנה, ישן נמי\u0004 \u0005[גם כן]\u0006 \u0003קנה?\u0004","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון מתוך הברייתא: \u0003גשמים שירדו מערב יום טוב, יש להן אלפים אמה לכל רוח,\u0004 שמותר לטלטלם בתחום זה. ואם ירדו הגשמים \u0003ביום טוב\u0004 עצמו — \u0003הרי הן כרגלי כל אדם,\u0004 שלא קנו לעצמם שביתה כלל, וכל אדם ששאב מהן מטלטלן לכל מקום שהוא עצמו מותר ללכת אליו.","\u0003אי אמרת בשלמא קסבר\u0004 \u0005[נניח אם אומר אתה שסבור]\u0006 \u0003ר' יוחנן בן נורי: \"חפצי הפקר קונין שביתה\", הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 של \u0005מי היא]\u0006 — כשיטת \u0003ר' יוחנן\u0004 בן נורי \u0003היא,\u0004 ולכן מי הגשמים שירדו מערב שבת קנו לעצמם שביתה במקומם.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]:\u0006 \u0003\"חפצי הפקר אין קונין שביתה\" הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 של \u0005מי היא]?\u0006 \u0003לא\u0004 כ\u0003ר' יוחנן\u0004 בן נורי \u0003ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שהרי ברור ממנה שהגשמים אף שאין להם בעלים קונים שביתה. אלא ודאי יש לומר שברייתא זו כשיטת ר' יוחנן בן נורי ודעתו שחפצי הפקר קונים שביתה!","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי וקאמר לה להא שמעתא\u0004 \u0005[ואמר לה להלכה זו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לאביי: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003בגשמים הסמוכין לעיר עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ואנשי אותה העיר דעתם עילייהו\u0004 \u0005[עליהם]\u0006 ולכן נקנו להם אלפיים אמה לכל רוח!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר הסבר כעין זה, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בור של יחיד\u0004 — מימיו \u0003כרגלי היחיד\u0004 בעל הבור, שלכל מקום שמותר לו ללכת, מותר לטלטל את מי הבור. \u0003ו\u0004בור \u0003של אותה העיר\u0004 — מותר להוליך את מימיו אלפיים אמה מכל צידי העיר \u0003כרגלי אותה העיר, ו\u0004בור \u0003של עולי בבל\u0004 בדרכם לארץ ישראל שהוא של כלל ישראל, מימיו \u0003כרגלי הממלא,\u0004 ובכל מקום שמותר לממלא ללכת מותר לו להוליך עמו את המים.","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003בור של שבטים\u0004 ששייך לציבור כולו — \u0003יש להן אלפים אמה לכל רוח.\u0004 אם כן \u0003קשיין אהדדי\u0004 \u0005[קשות הן זו על זו]!\u0006 שבמשנה למדנו שבור השייך לצבור אין למימיו מקום שביתה מסויים ובברייתא למדנו שיש להם אלפיים אמה בלבד ממקומם.","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרו שיש להן אלפיים אמה — היא כשיטת \u0003ר' יוחנן בן נורי,\u0004 שאפילו חפצי הפקר קונין שביתה. \u0003הא\u0004 \u0005[זו]\u0006 שאמרו שמים שאינם שייכים לאדם מסויים הרי הם כרגלי מי ששואב מהם — היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006.","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 אביי \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף, אמר ליה: הכי קאמר\u0004 \u0005[אמר לו: כך אמר]\u0006 \u0003רב ספרא, והכי אהדרי ליה\u0004 \u0005[וכך השבתי לו].\u0006 \u0003אמר ליה: ואמאי לא תימא ליה\u0004 \u0005[אמר לו: ומדוע לא אמרת לו]\u0006 תירוץ \u0003מגופה\u0004 של אותה ברייתא? \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ב\u0003גשמים הסמוכין לעיר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 — אם כן כיצד תבין \u0003האי\u0004 \u0005[זה]\u0006 שאמרו \u0003יש להן\u0004 כלומר למים עצמם \u0003אלפים אמה לכל רוח?!\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 לשיטה זו שאמרת שמותרים בטלטול אלפיים אמה משום שדעת אנשי העיר עליהם \u0003\"כרגלי אנשי אותה העיר\" מיבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 אלא וודאי מה שהתיר ר' יוחנן בן נורי את הטלטול באלפיים אמה למי שחשכה לו שבת מתוך שינה הוא — ש\"חפצי הפקר קונים שביתה במקומם\" אפילו בלא דעת המקנה להם שביתה.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 שגשמים שירדו \u0003ביום טוב — הרי הן כרגלי כל אדם.\u0004 ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003ליקני\u0004 \u0005[שיקנו]\u0006 המים \u0003שביתה באוקיינוס! שהרי הגשם הינו תוצאה של התאיידות מי האוקיינוס מאתמול וכיון שקנו שם שביתה מאתמול —\u0004 אסורים הם לכול משום שיצאו ממקום שביתתם.","\u0003לימא\u0004 \u0005[האם לומר\u0006 שברייתא זו\u0005]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' אליעזר\u0004 היא? \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004דעת \u0003ר' אליעזר\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר: כל העולם כולו ממי אוקיינוס הוא שותה\u0004 ומי הגשמים מי אוקיינוס הם!","\u0003אמר ר' יצחק: הכא\u0004 \u0005[כאן\u0006 מדובר\u0005]\u0006 \u0003בעבים שנתקשרו מערב יום טוב עסקינן\u0004 \u0005[אנו עוסקים],\u0006 ועננים אלו כבר היו מערב יום טוב באותו מקום ולא באוקיינוס ונמצא שבכניסת השבת כבר לא היה מקומם באוקיינוס.","ושואלים: \u0003ודילמא הנך אזלי, והנך אחריני נינהו\u0004 \u0005[ושמא\u0006 עננים \u0005אלה הלכו, ואלה\u0006 שהורידו גשמים \u0005אחרים הם]\u0006 שכן קנו שביתה באוקיינוס? ומשיבים: \u0003דאית להו סימנא בגוייהו\u0004 \u0005[שיש להם סימן בהם]\u0006 שאלה הם אותם עננים ולא אחרים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר שאיננו חוששים שמא אחרים הם \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003ספק דדבריהם\u0004 של חכמים אם הם אותם עננים, וכלל הוא: כל \u0003ספק דדבריהם —\u0004 נוהגים בו \u0003להקל.\u0004","ושואלים מצד אחר: \u0003וליקני\u0004 \u0005[ושיקנו]\u0006 המים \u0003שביתה בעבים,\u0004 ויימדד תחומם משם! והרי אמרת שהם כרגלי כל אדם, ואם כן \u0003תיפשוט מינה\u0004 \u0005[\u0006האם לא \u0005תפתור מכאן\u0006 את הבעיה\u0005]\u0006 שנתעוררה בנושא זה, ונאמר כי \u0003אין תחומין למעלה מעשרה\u0004 טפחים, שמעל גבול זה מותר ללכת אף יותר מאלפיים אמה. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003יש תחומין — ליקני\u0004 \u0005[ושיקנו]\u0006 המים \u0003שביתה בעבים!\u0004","ודוחים: \u0003לעולם אימא לך\u0004 \u0005[\u0006יכול אני \u0005לומר לך]:\u0006 \u0003יש תחומין\u0004 אף למעלה מעשרה טפחים, אלא לא קנו המים שביתה בענן כי \u0003מיא בעיבא מיבלע בליעי\u0004 \u0005[המים בענן מובלעים הם]\u0006 ואין מים ממש כהווייתם בתוך הענן, אלא היו בו בצורה שונה לגמרי, ולכן לא קנו שם שביתה."],["\u0003כל שכן דהוו להו\u0004 \u0005[שהינם]\u0006 בבחינת \u0003נולד דאסירי\u0004 \u0005[שאסורים]\u0006 בטלטול כלל, שכן דבר שנוצר מתחילתו ביום טוב ובשבת — אסור להשתמש בו, שהוא כמוקצה גמור,","\u0003אלא\u0004 כך יש לומר: \u0003מים בעבים מינד ניידי\u0004 \u0005[נודדים\u0006 הם\u0005]\u0006 וכיון שכך אינם קונים שביתה שם. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך\u0006 לתירוץ זה\u0005],\u0006 \u0003אוקיינוס נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליקשו\u0004 \u0005[יקשה]\u0006 \u0003לך, מיא\u0004 \u0005[המים]\u0006 \u0003באוקיינוס נמי מינד ניידי\u0004 \u0005[גם כן נעים ונדים],\u0006 \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003נהרות המושכין\u0004 מים \u0003ומעיינות הנובעין — הרי הן כרגלי כל אדם\u0004 לפי שלא קנו שביתה במקום מסויים אחד וכן דין מי העבים והימים.","\u0003אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כר' יוחנן בן נורי. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' יעקב בר אידי:\u0004 האם \u0003בפירוש שמיע לך\u0004 \u0005[שמעת]\u0006 הלכה זו \u0003או מכללא שמיע לך\u0004 \u0005[מכלל\u0006 הדברים \u0005שמעת,\u0006 הסקת אותה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בפירוש שמיע לי\u0004 \u0005[שמעתי].\u0006","ושואלים: \u0003מאי כללא\u0004 \u0005[מהו כלל\u0006 זה\u0005]\u0006 שחשב ר' זירא שהוא מקור הלכה זו? — ש\u0003אמר ר' יהושע בן לוי: הלכה כדברי המיקל בעירוב.\u0004","ואולם כיון שנאמרה אף מימרה זו בפירוש, שואלים: \u0003ותרתי\u0004 \u0005[ו\u0006באמת \u0005שתיהן]\u0006 \u0003למה לי,\u0004 שאם אמר כבר שהלכה כדברי המיקל בעירוב, לשם מה היה לו לומר שהלכה כר' יוחנן בן נורי?!","\u0003אמר ר' זירא: צריכי\u0004 \u0005[צריכים\u0006 שניהם להיאמר\u0005],\u0006 \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003הלכה כר' יוחנן בן נורי, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהלכה כמותו \u0003בין לקולא\u0004 \u0005[להקל]\u0006 באדם ישן שקנה שביתה ויכול להלך אלפיים אמה \u0003ובין לחומרא\u0004 \u0005[להחמיר]\u0006 בכלי הפקר שקונים שביתה במקומם ואין להם אלא אלפיים אמה ממקומם, ולכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003הלכה כדברי המיקל בעירוב,\u0004 שיש לפסוק כר' יוחנן בן נורי רק כשיש צד הקלה בדבר.","וכן שואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 רק \u0003\"הלכה כדברי המיקל בעירוב\".\u0004 ואם כן, \u0003הלכה כ\u0004דברי \u0003ר' יוחנן בן נורי למה לי?\u0004","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהלכה כמיקל בעירובין נאמרו כאשר המחלוקת היא של \u0003יחיד במקום יחיד, ורבים במקום רבים, אבל יחיד במקום רבים — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יפסקו כמותו. על כן הוצרך לומר שהלכה כר' יוחנן בן נורי, אף כנגד חכמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי: מכדי\u0004 \u0005[הרי]\u0006 \u0003עירובין דרבנן\u0004 \u0005[מדברי חכמים\u0006 הם\u0005],\u0006 \u0003מה לי\u0004 להבדיל בין מחלוקת \u0003יחיד במקום יחיד, ומה לי יחיד במקום רבים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: ובדרבנן לא שני לן\u0004 \u0005[ו\u0006כי \u0005בדברי סופרים אינו שונה לנו]\u0006 \u0003בין יחיד במקום יחיד ליחיד במקום רבים!\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אלעזר אומר: כל אשה שעברו עליה שלש עונות,\u0004 כלומר: שהגיעו ימי וסתה שלש פעמים ולא מצאה דם, הרי זו בחזקת שאינה רואה דם וסת. ואם ראתה דם אחר כך — \u0003דייה שעתה,\u0004 דייה להיות טמאה כנדה משעה זו שבדקה ומצאה שהיא נדה \u0003ואין חוששים שמא יצא הדם קודם לכן ויש לטמאה יום שלם מקודם לכך. וחכמים אומרים בענין זה שכך הלכה רק באשה זקנה או יולדת שבדרך הטבע מפסיקה לראות דם, אבל באשה צעירה רגילה אין אומרים אף אחר שלש עונות \"דייה שעתה\".\u0004","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ועשה רבי\u0004 ופסק הלכה \u0003כר' אלעזר. לאחר שנזכר\u0004 שבדבר זה חלוקין חבריו על ר' אלעזר ושלכאורה לא עשה כראוי, \u0003אמר:\u0004 בכל זאת \u0003כדי\u0004 (ראוי) \u0003הוא ר' אלעזר לסמוך עליו בשעת הדחק.\u0004","ומעירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לאחר שנזכר\"? אילימא\u0004 \u0005[אם לומר]\u0006 \u0003לאחר שנזכר\u0004 ש\u0003אין הלכה כר' אלעזר אלא כרבנן\u0004 \u0005[כחכמים],\u0006 אם כן \u0003בשעת הדחק היכי עביד כוותיה\u0004 \u0005[איך עשה כמותו],\u0006 והלא נפסקה הלכה שלא כדבריו!","\u0003אלא דלא איתמר הלכתא\u0004 \u0005[שלא נאמרה הלכה]\u0006 פסוקה בדבר \u0003לא כר' אלעזר ולא כרבנן.\u0004 ו\u0003\"לאחר שנזכר\" דלאו\u0004 \u0005[שלא]\u0006 \u0003יחיד פליג עליה\u0004 \u0005[חלק עליו\u0006 על ר' אלעזר\u0005]\u0006 \u0003אלא רבים פליגי עליה\u0004 \u0005[חולקים עליו]\u0006 \u0003אמר:\u0004 בכל זאת \u0003כדי הוא ר' אלעזר לסמוך עליו בשעת הדחק.\u0004 משמע שאף שנחלקו בגזירת חכמים (אם לטמא אשה למפרע), מכל מקום מלכתחילה בכל מחלוקת בין יחיד ורבים הלכה כרבים.","\u0003אמר רב משרשיא לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן בר יצחק לרבא: ובדרבנן לא שני\u0004 \u0005[ובדברי חכמים אינו שונה]\u0006 \u0003בין יחיד במקום יחיד, בין יחיד במקום רבים?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שמועה קרובה\u0004 ששמע אדם שמת אחד מקרוביו — \u0003נוהגת,\u0004 וצריך הוא להתאבל בכל דיני האבל \u0003שבעה\u0004 ימי אבל חמור, \u0003ושלשים\u0004 ימי אבל קל יותר. שמועה \u0003רחוקה — אינה נוהגת\u0004 באבילות \u0003אלא יום אחד\u0004 בלבד.","ואמרו: \u0003ואי זו היא קרובה ואי זו היא רחוקה? בתוך שלשים\u0004 יום מיום הפטירה — \u0003קרובה, לאחר שלשים — רחוקה,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: אחת שמועה קרובה ואחת שמועה רחוקה נוהגת שבעה ושלשים.\u0004","\u0003ואמר רבה בר בר חנה אמר ר' יוחנן: כל מקום שאתה מוצא יחיד מיקל\u0004 בהלכה, \u0003ורבים מחמירין,\u0004 ודאי \u0003הלכה כדברי המחמירין המרובים, חוץ מזו, שאף על פי שר' עקיבא מיקל וחכמים מחמירין — הלכה כדברי ר' עקיבא. ו\u0004ר' יוחנן","\u0003סבר לה\u0004 \u0005[לאותה\u0006 הנהגה\u0005]\u0006 \u0003כשמואל,\u0004 ש\u0003אמר שמואל: הלכה כדברי המיקל באבל,\u0004 שכל מחלוקת בדיני אבילות ראוי לנטות בה להקלה.","ומכאן נדייק: \u0003באבילות הוא דאקילו\u0004 \u0005[שהקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 \u0003אבל בעלמא\u0004 \u0005[בכלל\u0006 בשאר הלכות\u0005] —\u0006 \u0003אפילו בדרבנן שני\u0004 \u0005[בדברי סופרים שונה]\u0006 \u0003בין יחיד במקום יחיד בין יחיד במקום רבים.\u0004 ואם כן יפה עשה ר' יהושע בן לוי שפסק הלכה במפורש כר' יוחנן בן נורי שהוא יחיד במקום רבים אף בעירוב שאינו אלא מדברי סופרים."],["\u0003ורב פפא אמר\u0004 שאפשר להסביר את הצורך בכפילות דבריו של ר' יהושע בן לוי באופן אחר, \u0003איצטריך\u0004 \u0005[נצרך]\u0006 שאילו היה אומר רק הלכה כדברי המיקל בעירוב \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[אלו הדברים]\u0006 נאמרו רק \u0003ב\u0004דיני \u0003עירובי חצירות,\u0004 שכולם מדברי סופרים. \u0003אבל בעירובי תחומין\u0004 שמחמירים בהם — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נפסוק להקל, על כן צריך שיאמר שניהם.","ושואלים: \u0003ומנא תימרא דשני לן\u0004 \u0005[ומנין תאמר ששונה לנו]\u0006 להלכה \u0003בין עירובי חצירות לעירובי תחומין\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדומה לכך, \u0003אמר ר' יהודה: במה דברים אמורים\u0004 שמערבים לאדם רק מדעתו — \u0003בעירובי תחומין, אבל בעירובי חצירות — מערבין בין לדעת ובין שלא לדעת, שזכין לאדם שלא בפניו\u0004 ואין צורך לקבל הסכמתו לדבר שיש לו בו רק צד זכות והנאה, \u0003ו\u0004אולם \u0003אין חבין לאדם אלא בפניו.\u0004 והרי בעירובי תחומין מה שהוא מרוויח בהיתר הליכה לצד אחד מפסיד הוא מצד שני, ואין לעשות זאת שלא מדעתו.","\u0003רב אשי אמר:\u0004 אפשר להסביר באופן אחר את כפילות דברי ר' יהושע. \u0003איצטריך\u0004 \u0005[נצרך],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי מה שאמר שמקילים בעירוב, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בשיורי עירוב,\u0004 כלומר: לאחר שנעשה כבר העירוב כדינו, אלא שיש לחשוש שנתקלקל אחר כך, \u0003אבל בתחילת עירוב — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נפסוק להקל.","ושואלים: \u0003ומנא תימרא דשני לן\u0004 \u0005[ומנין תאמר ששונה לנו]\u0006 \u0003בין שיורי עירוב לתחילת עירוב\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003אמר ר' יוסי: במה דברים אמורים\u0004 שקבעו מידה לכמות האוכל שיש צורך בה לעירוב — \u0003בתחילת עירוב\u0004 כדי לקבעו מעיקרו, \u0003אבל בשיורי עירוב — אפילו כל שהוא.\u0004","\u0003ולא אמרו לערב חצירות\u0004 כאשר כל בני העיר עשו שיתופי מבואות, ונעשים כולם כבני חצר אחת, \u0003אלא כדי שלא לשכח תורת עירוב מן התינוקות.\u0004 ועיקר דין עירוב אינו אלא בעירוב תחומים.","כיון שנאמרו דברים בכללי קביעת הלכה בנושאים שונים הביאו עוד דברים בנושא זה. \u0003ר' יעקב ור' זריקא אמרו: הלכה\u0004 בכל מקום \u0003כר' עקיבא מחבירו\u0004 כשיחיד חולק עליו, \u0003ו\u0004הלכה \u0003כר' יוסי\u0004 אפילו \u0003מחביריו\u0004 הרבים, \u0003ו\u0004הלכה \u0003כרבי\u0004 יהודה הנשיא \u0003מחבירו\u0004.","ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמרו דברים אלה. כלומר, באיזו מידה אפשר לסמוך על כללים אלה? \u0003ר' אסי אמר\u0004 שהדבר הזה \u0003הלכה\u0004 גמורה הוא. \u0003ור' חייא בר אבא אמר\u0004: \u0003מטין,\u0004 להורות כן ליחיד השואל הלכה אבל לא לרבים כהלכה כללית. \u0003ור' יוסי בר' חנינא אמר: נראין,\u0004 שכך נראה שיש לפסוק, אבל אין זו הלכה גמורה ולכן אין מורים כן כלל, אבל אם נהג כך האחד מדעתו, אין מחזירים אותו.","ועוד בענין זה. \u0003כלשון הזה אמר ר' יעקב בר' אידי אמר ר' יוחנן: ר' מאיר ור' יהודה\u0004 שנחלקו ביניהם — \u0003הלכה כר' יהודה, ר' יהודה ור' יוסי — הלכה כר' יוסי. ואין צריך לומר\u0004 שאם נחלקו \u0003ר' מאיר ור' יוסי — הלכה כר' יוסי\u0004. כי \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003במקום ר' יהודה — ליתא\u0004 \u0005[אינו],\u0006 שאין פוסקים הלכה כמותו. \u0003במקום ר' יוסי מיבעיא\u0004 \u0005[נצרכה]?!\u0006 שהרי אף ר' יהודה אין הלכה כמותו נגד ר' יוסי.","אמר \u0003רב אסי: אף אני לומד\u0004 לפי אותו עקרון: \u0003ר' יוסי ור' שמעון — הלכה כר' יוסי,\u0004 ש\u0003אמר ר' אבא אמר ר' יוחנן:\u0004 אם נחלקו \u0003ר' יהודה ור' שמעון — הלכה כר' יהודה.\u0004 ומכאן נסיק: \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאנחנו יודעים ש\u0003במקום ר' יהודה ליתא\u0004 \u0005[אינו]\u0006 לדברי ר' שמעון, \u0003במקום ר' יוסי\u0004 שהלכה כמותו כנגד ר' יהודה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהלכה כמותו?","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' מאיר ור' שמעון\u0004 שחלקו, \u0003מאי\u0004 \u0005[מה\u0006 פסק ההלכה\u0005]?\u0006 ולא נמצאו מקורות בדבר, והושארה הבעיה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003אמר רב משרשיא: ליתנהו להני כללי\u0004 \u0005[אין\u0006 לסמוך \u0005על אותם הכללים]\u0006 שואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרב משרשיא הא\u0004 \u0005[זאת]\u0006 שאין לסמוך על הכללים הללו?","\u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו]\u0006 במשנתנו, \u0003ר' שמעון אומר: למה הדבר דומה — לשלש חצירות הפתוחות זו לזו ופתוחות לרשות הרבים, עירבו שתים החיצונות עם האמצעית — היא מותרת עמהן, והן מותרות עמה, ושתים החיצונות אסורות זו עם זו.\u0004","\u0003ואמר רב חמא בר גוריא אמר רב: הלכה כר' שמעון. ומאן פליג עליה\u0004 \u0005[ומי חלק עליו]\u0006 על ר' שמעון בדבר זה — \u0003ר' יהודה. והא\u0004 \u0005[והרי]\u0006 \u0003אמרת: ר' יהודה ור' שמעון הלכה כר' יהודה. אלא לאו שמע מינה: ליתנהו\u0004 \u0005[אלא\u0006 האם \u0005לא תלמד מכאן\u0006 כי \u0005אין\u0006 לסמוך על כללים אלה\u0005]?\u0006","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבדבר שממנה לומדים כן, \u0003דילמא היכא דאיתמר\u0004 \u0005[במקום שנאמר]\u0006 פסק הלכה מפורש שונה — \u0003איתמר,\u0004 אבל \u0003היכא דלא איתמר\u0004 \u0005[במקום שלא נאמרה]\u0006 הלכה מנוגדת — \u0003לא איתמר\u0004 \u0005[לא נאמר].\u0006 ואפשר לסמוך על הכלל הקבוע.","\u0003אלא\u0004 אפשר להוכיח \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עיר של יחיד ונעשית\u0004 אחר כך קנין ל\u0003רבים — מערבין את כולה\u0004 בעירוב חצרות. ואולם אף עיר \u0003של רבים\u0004 אם \u0003נעשית\u0004 קנין \u0003של יחיד — אין מערבין את כולה, אלא אם כן עושה חוצה לה\u0004 שהשאיר חלק מסויים שלא יכלל בעירוב החצירות, ויהא החלק גדול \u0003כעיר\u0004 ששמה \u0003חדשה שביהודה. שיש בה חמשים דיורין\u0004 — אלו \u0003דברי ר' יהודה\u0004.","\u0003ר' שמעון אומר:\u0004"],["אין צורך בשטח כה גדול אלא בהקצאת \u0003שלש חצירות של שני בתים\u0004 די. \u0003ואמר רב חמא בר גוריא אמר רב: הלכה כר' שמעון. ומאן פליג עליה\u0004 \u0005[ומי חולק עליו]\u0006 — \u0003ר' יהודה. והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 שקיים כלל: \u0003ר' יהודה ור' שמעון — הלכה כר' יהודה!\u0004","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 בכך? \u0003דילמא הכא נמי, היכא דאיתמר\u0004 \u0005[שמא גם כאן, במקום שנאמר]\u0006 במפורש שהלכה כר' שמעון — \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003היכא דלא איתמר\u0004 \u0005[במקום שלא נאמר] —\u0006 \u0003לא איתמר\u0004 \u0005[לא נאמר]\u0006 וכרגיל הלכה כר' יהודה.","\u0003אלא מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המניח את ביתו\u0004 ולא עשה עירוב חצירות \u0003והלך לשבות בעיר אחרת, אחד גוי ואחד ישראל — אוסר לבני חצירות\u0004 שהיו סביב ביתו להוציא מביתם לחצר משום שלא עירב עימם, ובית שאינו מעורב, אוסר על כולם — אלו \u0003דברי ר' מאיר\u0004.","\u0003ר' יהודה אומר: אינו אוסר\u0004 כיון שאינו נמצא במקום. \u0003ר' יוסי אומר: גוי — אוסר, ישראל — אינו אוסר, מפני שאין דרך ישראל לבא בשבת\u0004 אם כבר קבע לעצמו דירה במקום אחר. \u0003ר' שמעון אומר: אפילו הניח את ביתו והלך לשבות אצל בתו באותה העיר — אינו אוסר\u0004 אף שוודאי מצד הדין יכול לחזור, \u0003שכבר הסיח דעתו\u0004 מלשוב לביתו.","\u0003ואמר רב חמא בר גוריא אמר רב: הלכה כר' שמעון, ומאן פליג עליה\u0004 \u0005[ומי חלק עליו] —\u0006 \u0003ר' יהודה. והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כבר כי \u0003ר' יהודה ור' שמעון — הלכה כר' יהודה!\u0004","ושוב דוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 בכך? \u0003דילמא הכא נמי, היכא דאיתמר\u0004 \u0005[שמא גם כאן, במקום שנאמר]\u0006 במפורש שהלכה כר' שמעון — \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003היכא דלא איתמר\u0004 \u0005[במקום שלא נאמר] —\u0006 \u0003לא איתמר\u0004 \u0005[לא נאמר].\u0006","\u0003אלא\u0004 יש להוכיח \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003וזהו שאמרו: העני מערב ברגליו\u0004 שיכול ללכת למקום שבתוך תחומו ולומר: כאן תהא שביתתי וישערו לו את תחום השבת מאותו מקום. \u0003ר' מאיר אומר: אנו אין לנו אלא עני\u0004 שאין ברשותו כעת מזון שתי סעודות, והוא שמותר לו לערב ברגליו.","\u0003ר' יהודה אומר\u0004: היתר זה, \u0003אחד עני ואחד עשיר.\u0004 ולהיפך, \u0003לא אמרו\u0004 ש\u0003מערבין בפת אלא להקל על העשיר, שלא\u0004 יטרח ו\u0003יצא ויערב ברגליו,\u0004 אבל עיקר עירוב — ברגליו הוא.","\u0003ומתני ליה\u0004 \u0005[והיה משנה,\u0006 מלמד\u0005, לו]\u0006 \u0003רב חייא בר אשי לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב: אחד עני ואחד עשיר. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: סיים בה נמי\u0004 \u0005[גם כן]\u0006 כשאתה מלמד: \u0003הלכה כר' יהודה\u0004.","ואפשר להקשות: \u0003תרתי\u0004 \u0005[שתיים]\u0006 \u0003למה לי, והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרת: ר' מאיר ור' יהודה — הלכה כר' יהודה!\u0004 ואם הוצרך רב לפרש שהלכה כר' יהודה, משמע שאינו סבור שיש כלל שר' מאיר ור' יהודה — הלכה כר' יהודה?!","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה קושיה]?\u0006 \u0003דילמא רב לית ליה להני כללי\u0004 \u0005[שמא רב אין לו,\u0006 אינו סובר \u0005אלה הכללים],\u0006 אבל שאר חכמים מקבלים אותם?","\u0003אלא\u0004 מביאים ראיה ממקור אחר, \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היבמה לא תחלוץ ולא תתיבם עד שיהו לה שלשה חדשים\u0004 אחרי מות בעלה, שמא היתה מעוברת מבעלה, ואם יהיה לה ילד ממנו אינה זקוקה ליבום ולחליצה, ותוך שלשה חדשים יהא הדבר ניכר.","\u0003וכן שאר כל הנשים לא ינשאו ולא יתארסו עד שיהו להן שלשה חדשים\u0004 אחר מות בעליהן, או לאחר גירושיהן, \u0003אחד\u0004 אם נישאו כשהן \u0003בתולות ואחד בעולות, אחד אלמנות ואחד גרושות, אחד\u0004 אם נתאלמנו או נתגרשו כשהיו \u0003ארוסות ואחד נשואות,\u0004 שאם היתה הרה לבעלה הראשון ידעו בבירור מי אבי הילד, שלא נחלקו חכמים אם יש מקום לחשש זה אלא קבעו כלל לכל מקרה, שיהא תוקפו קיים תמיד.","\u0003ר' יהודה אומר:\u0004 אם נתאלמנו או נתגרשו כשהיו \u0003נשואות — יתארסו\u0004 מיד שהרי בתקופת האירוסין אין האיש בא על ארוסתו ואין להקפיד אלא להרחיק את זמן נשואין שניים מן הראשונים.","וכן אם נתאלמנו או נתגרשו כשהיו \u0003ארוסות — ינשאו\u0004 מיד, שאין להניח שנבעלו בתקופת אירוסיהן, \u0003חוץ מארוסה שביהודה, מפני שלבו גס בה.\u0004 שזוגות מאורסים שבארץ יהודה היו נוהגים להיפגש ביחידות, ויש לחשוש שמא הרתה לו, אבל בשאר מקומות אין לחשוש.","\u0003ר' יוסי אומר: כל הנשים\u0004 שמנינו \u0003יתארסו\u0004 מיד, שלא גזרו אלא על נישואין, \u0003חוץ מן האלמנה\u0004 שצריכה להמתין, אבל מטעם אחר — \u0003מפני האיבול\u0004 (אבילות). שבגלל אבלה על מות בעלה, אסור לה להתארס.","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בענין זה: \u0003ר' אלעזר לא על\u0004 \u0005[בא\u0006 פעם\u0005]\u0006 \u0003לבי מדרשא\u0004 \u0005[לבית המדרש].\u0006 \u0003אשכחיה\u0004 \u0005[מצא\u0006 את\u0005]\u0006 \u0003ר' אסי דהוה קאים\u0004 \u0005[שהיה עומד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אמור בבי מדרשא\u0004 \u0005[מה אמרו בבית המדרש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: הלכה כר' יוסי\u0004. אמר לו: \u0003מכלל דיחידאה פליג עליה\u0004 \u0005[שיחיד\u0006 הוא זה \u0005שחלק עליו]\u0006 ולכן הלכה כמותו.","ענה לו: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[וכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי\u0004 אשה \u0003שהיתה רדופה לילך לבית אביה,\u0004 שהיתה להוטה להיות בבית אביה ולא שהתה עם בעלה בימיו האחרונים. \u0003או שהיתה לה כעס עם בעלה\u0004 ונפרדו, \u0003או שהיה בעלה זקן או חולה,\u0004 שאינו יכול להוליד, \u0003או שהיתה היא חולה,\u0004 או שהוחזקה \u0003עקרה,\u0004 או \u0003זקנה, קטנה ואיילונית\u0004 (שמטבעה אינה מסוגלת להוליד), \u0003ו\u0004כל \u0003שאינה ראויה לילד\u0004 מסיבה אחרת, \u0003או שהיה בעלה חבוש בבית האסורין,\u0004 וכן \u0003המפלת לאחר מיתת בעלה\u0004 שאין לחוש עוד שמא היא מעוברת — \u0003כולן צריכין להמתין שלשה חדשים, דברי ר' מאיר\u0004 הסבור שגזירה זו חלה על כל הנשים. אף אם אין בכך הכרח מצד הענין. \u0003ר' יוסי מתיר ליארס ולינשא מיד\u0004 בכל אלו.","וממשיכים: \u0003למה לי\u0004 (לשם מה) היה צריך לומר שהלכה כר' יוסי? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת ר' מאיר ור' יוסי הלכה כר' יוסי\u0004 ואם כן הלכה כמותו גם כאן. ואם כן לכאורה משמע מכאן שאין כלל זה נכון!","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 שבדבר\u0005]?\u0006 \u0003דלמא לאפוקי\u0004 \u0005[שמא\u0006 בא פסק זה \u0005להוציא]\u0006 מדברי \u0003רב נחמן אמר שמואל\u0004 ש\u0003אמר\u0004 שאף שבמחלוקות רבות אין הלכה כר' מאיר, מכל מקום \u0003הלכה כר' מאיר בגזירותיו,\u0004 כאשר החמיר בדבר אחד מתוך דמיונו לאחרים. ולכן היה ר' יוחנן צריך לומר שהלכה כאן כר' יוסי למרות שהוא בניגוד לגזירתו של ר' מאיר.","\u0003אלא\u0004 ההוכחה לביטול כללים אלה היא \u0003מהא דתניא\u0004 \u0005[מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הולכין ליריד של גוים\u0004 (שוק שנעשה לכבוד עבודה זרה) \u0003ולוקחים מהן בהמה ועבדים ושפחות,\u0004 מפני שמכניסים אותם לקדושה. \u0003בתים שדות וכרמים,\u0004 משום יישוב ארץ-ישראל. \u0003וכותב ומעלה\u0004 (מאשר את הדברים) \u0003בערכאות\u0004 (בתי דינים) \u0003שלהן,\u0004 תוך קבלת חתימותיהן, ואף על פי שיש בכך הכרת חשיבותם ויש לחשוש שמא יבוא להודות לעבודה זרה, \u0003מפני\u0004 שבכך \u0003הוא כמציל מידן.\u0004 שכן על ידי אישורם וחתימתם לא יוכלו לערער ולחזור בהם ממכירתם.","\u0003ואם היה כהן\u0004 — אף מותר לו לצאת למקום שבו הוא \u0003מטמא, בחוצה לארץ,\u0004 שעפרה ואוירה מטמאים, וללכת \u0003לדון ולערער עמהן. וכשם שמטמא\u0004 הכהן \u0003בחוצה לארץ כך מטמא,\u0004 לשם כך, \u0003בבית הקברות.\u0004","ומתחילה תוהים על הלכה אחרונה זו: וכי \u0003בית הקברות סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?!\u0006 הלא \u0003טומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא,\u0004 וכיצד יתירו חכמים לכהן להיטמא, בניגוד למה שכתוב בתורה!","\u0003אלא\u0004 מדובר בטומאת \u0003בית הפרס,\u0004 שדה שנחרש בו קבר ויש בו חשש טומאת מת, שטומאתו רק מ\u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006","\u0003ומטמא\u0004 וכמו כן יוצא הכהן לחוץ לארץ כדי \u0003לישא אשה\u0004 שם, או כדי \u0003ללמוד תורה. אמר ר' יהודה: אימתי\u0004 נאמר היתר זה — \u0003בזמן שאין מוצא\u0004 אפשרות \u0003ללמוד\u0004 בארץ, \u0003אבל\u0004 אם \u0003מוצא\u0004 הכהן אפשרות \u0003ללמוד\u0004 בארץ — \u0003לא יטמא.\u0004","\u0003ר' יוסי אומר: אף בזמן שמוצא\u0004 אפשרות \u0003ללמוד\u0004 בארץ — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יטמא, לפי\u0004"],["\u0003שאין\u0004 (שלא) \u0003מן הכל זוכה אדם ללמוד,\u0004 וייתכן שרק רב מסויים הנמצא בחוץ לארץ הוא המתאים לו. \u0003ואמר ר' יוסי\u0004 ראיה לדבריו: \u0003מעשה ביוסף הכהן שהלך אצל רבו לצידן\u0004 שהיא בחוץ לארץ \u0003ללמוד תורה,\u0004 על אף שהיה בדורו של רבן יוחנן בן זכאי שהיה בארץ ישראל והיה גדול הדור.","\u0003ואמר ר' יוחנן: הלכה כר' יוסי\u0004. וכאן עולה השאלה: \u0003ולמה לי\u0004 לפסוק גם כאן? \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרת ר' יהודה ור' יוסי — הלכה כר' יוסי!\u0004","\u0003אמר אביי: איצטריך\u0004 \u0005[נצרך,\u0006 בכל זאת\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה] —\u0006 \u0003במתניתין\u0004 \u0005[במשנתינו],\u0006 \u0003אבל בברייתא — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן היה צורך לומר שהלכה כדבריו גם בברייתא. ומכיון שלא נמצאו הוכחות לדברי רב משרשיא שאין כללים לפסק ההלכה, יש איפוא לתקן את דבריו, \u0003אלא\u0004","\u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 התכוון\u0005]\u0006 רב משרשיא: \u0003הני כללי לאו\u0004 \u0005[כללים אלה לא]\u0006 \u0003דברי הכל נינהו\u0004 \u0005[הם],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב לית ליה הני כללי\u0004 \u0005[אין לו אותם כללים],\u0006 כפי שהוכחנו לעיל.","מעתה שבים אנו לבעיה היסודית של קנין שביתה. \u0003אמר רב יהודה אמר שמואל: חפצי גוי אין קונין שביתה\u0004 ואין להם תחום שבת לא מכח עצמם, ולא מכח בעלותו של הגוי, ואם נכנסו מחוץ לתחום לתוך העיר, מותר לישראל לטלטלם אלפיים אמה לכל צד.","ושואלים: \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 נאמר דבר זה, \u0003אילימא לרבנן\u0004 \u0005[אם תאמר שלפי\u0006 שיטת \u0005חכמים]\u0006 אמר — הרי \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאומר אתה ש\u0003חפצי הפקר דלית להו\u0004 \u0005[שאין להם]\u0006 \u0003בעלים, אין קונין שביתה. חפצי הגוי, דאית להו\u0004 \u0005[שיש להם]\u0006 \u0003בעלים\u0004 ובעליהם עצמם אינם יכולים לקנות שביתה \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינם קונים שביתה במקומם מכח עצמם?","\u0003אלא אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יוחנן בן נורי, וקא משמע לן\u0004 \u0005[ומשמיע לנו]:\u0006 \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יוחנן בן נורי\u0004 ש\u0003קונין שביתה — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003חפצי הפקר, דלית להו\u0004 \u0005[שאין להם]\u0006 \u0003בעלים. אבל חפצי הגוי, דאית להו\u0004 \u0005[שיש להם]\u0006 \u0003בעלים — לא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 \u0003ר' שמעון בן אלעזר אומר: השואל כלי מן הגוי\u0004 בן עירו \u0003ביום טוב, וכן המשאיל לו לגוי כלי מערב יום טוב, והחזירו לו\u0004 הגוי \u0003ביום טוב. ו\u0004כן \u0003הכלים\u0004 שנעשו \u0003אוצרות\u0004 (מחסנים) \u0003ששבתו בתוך התחום — יש להן אלפים אמה לכל רוח. וגוי שהביא לו\u0004 לישראל ביום טוב \u0003פירות\u0004 שקנו שביתה \u0003מחוץ לתחום — הרי זה לא יזיזם ממקומן.\u0004","\u0003אי אמרת בשלמא קסבר\u0004 \u0005[אם נניח שאתה אומר שסבור]\u0006 \u0003ר' יוחנן בן נורי: חפצי גוי קונין שביתה,\u0004 ניתן אז לפרש: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יוחנן בן נורי היא\u0004 שאף חפצי גוי קונים שביתה.","\u0003אלא אי אמרת קסבר\u0004 \u0005[אם אומר אתה שסבור]\u0006 \u0003ר' יוחנן בן נורי\u0004 ש\u0003חפצי הגוי אין קונין שביתה, הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 \u0003לא ר' יוחנן בן נורי ולא רבנן\u0004 \u0005[חכמים]!\u0006","\u0003ומשיבים: לעולם\u0004 תפרש \u0003קסבר\u0004 \u0005[שסבור]\u0006 \u0003ר' יוחנן בן נורי חפצי הגוי קונין שביתה, ושמואל\u0004 ש\u0003אמר\u0004 שאינם קונים — \u0003כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 אמר, \u0003ודקאמרת: לרבנן פשיטא\u0004 \u0005[ו\u0006מה \u0005שאמרת:\u0006 הלא \u0005ל\u0006שיטת \u0005חכמים פשוט\u0006 הדבר\u0005]\u0006 ואין צורך לאמרו כלל — אין הדבר כן, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 יש מקום ל\u0003גזירה\u0004 ב\u0003בעלים\u0004 שהוא \u0003גוי אטו\u0004 \u0005[משום]\u0006 \u0003בעלים\u0004 שהוא \u0003ישראל, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ויקנו שביתה במקום הגוי, ולא יטלטלו יותר מאלפיים אמה משם. ועל כן היה צורך לומר לנו שאין גוזרים בכך.","\u0003ו\u0004אילו \u0003רב חייא בר אבין אמר ר' יוחנן: חפצי גוי\u0004 אכן \u0003קונין שביתה,\u0004 מן הטעם האמור של \u0003גזירה\u0004 ב\u0003בעלים\u0004 שהוא \u0003גוי אטו\u0004 \u0005[משום]\u0006 \u0003בעלים\u0004 שהוא \u0003ישראל.\u0004","מסופר: \u0003הנהו דכרי דאתו\u0004 \u0005[אותם אילים שהובאו]\u0006 \u0003ל\u0004עיירה \u0003מברכתא\u0004 בשבת, \u0003שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003רבא לבני מחוזא למיזבן מינייהו\u0004 \u0005[לקנות מהם]\u0006 אף שמברכתא היא מחוץ לתחומה של מחוזא, ואפשר להגיע אליה רק על ידי עירוב תחומים ואילים אלה הובאו איפוא מחוץ לתחום לגמרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: מאי דעתך \u0004\u0005[מה דעתך]\u0006 שאתה מתיר, שאתה מסתמך על מה ש\u0003אמר רב יהודה אמר שמואל: חפצי גוי אין קונין שביתה,\u0004 ולכן לא קנו האילים שביתה במקומם ואפילו נכנסו מחוץ לתחום מותר לטלטלם.","\u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא בידינו כי אם נחלקים \u0003שמואל ור' יוחנן — הלכה כר' יוחנן, ו\u0004הלא כבר \u0003אמר רב חייא בר אבין אמר ר' יוחנן: חפצי גוי קונין שביתה גזירה בעלים\u0004 שהוא \u0003גוי אטו\u0004 \u0005[משום]\u0006 \u0003בעלים\u0004 שהוא \u0003ישראל?!\u0004 והלכה כמותו!","\u0003הדר\u0004 \u0005[חזר]\u0006 \u0003ואמר רבא: ליזדבנו\u0004 \u0005[שימכרו]\u0006 האילים רק \u0003לבני מברכתא,\u0004 שכן \u0003כולה\u0004 \u0005[כל]\u0006 \u0003מברכתא לדידהו\u0004 \u0005[עבורם]\u0006 \u0003כארבע אמות דמיא\u0004 \u0005[נחשבת],\u0006 ואפילו חפץ שיצא באיסור מתחומו מותר לטלטלו ארבע אמות. אבל לבני מחוזא — אסור, וכשיטת ר' יוחנן.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: חרם\u0004 (תעלה מלאה מים) \u0003שבין תחומי שבת — צריך\u0004 לעשות"],["\u0003מחיצה של ברזל להפסיקו,\u0004 להפריד בין תחום לתחום, כדי להתיר לבני שני המקומות לשאוב משם מים. היה \u0003מחייך\u0004 (צוחק) \u0003עליה\u0004 \u0005[על כך]\u0006 \u0003ר' יוסי בר חנינא\u0004 שסבר שאין צורך בתקנה זו.","ושואלים: \u0003מאי טעמא קא\u0004 \u0005[מדוע היה]\u0006 \u0003מחייך? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דתני לה\u0004 \u0005[ששנה אותה]\u0006 ר' חייא \u0003כר' יוחנן בן נורי לחומרא\u0004 \u0005[להחמיר]\u0006 שחפצי הפקר קונים שביתה במקומם \u0003ואיהו\u0004 ר' יוסי בר חנינא \u0003סבירא ליה כרבנן לקולא\u0004 \u0005[והוא עצמו סבור היה כ\u0006שיטת \u0005חכמים להקל]\u0006 שאינם קונים שביתה במקומם \u0003ומשום דסבר לקולא, מאן דתני לחומרא מחייך עלה\u0004 \u0005[שהוא סבר להקל, מי ששנה להחמיר היה צוחק עליו]?\u0006","\u0003אלא\u0004 מטעם אחר, \u0003משום דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נהרות המושכין ומעיינות הנובעין — הרי הן כרגלי כל אדם,\u0004 ואם כן מותרים לשואב אותם לטלטלם כפי שהוא עצמו מותר, אפילו אם היו קודם לכן מחוץ לתחומו.","ודוחים שהרי משם אין להוכיח כי \u0003דילמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003ב\u0004חריץ של מים \u0003מכונסין\u0004 ועומדים, שמים כאלה שייכים רק לבני מקומם.","\u0003אלא\u0004 מטעם אחר היה מחייך, \u0003משום דקתני\u0004 \u0005[ששנה]\u0006 ר' חייא: \u0003\"צריך מחיצה של ברזל להפסיקו\".\u0004 וכך טען ר' יוסי: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 מחיצת \u0003קנים\u0004 ש\u0003לא — דעיילי בהו מיא\u0004 \u0005[ש\u0006כן \u0005נכנסים בהם\u0006 דרכה \u0005המים\u0006 מתחום לתחום\u0005],\u0006 אולם במחיצה \u0003של ברזל נמי\u0004 \u0005[גם כן] —\u0006 \u0003עיילי בהו מיא\u0004 \u0005[נכנסים בהם\u0006 מתחתיה \u0005מים]\u0006 ואי אפשר לעשותה שתהיה אטומה לגמרי, ומה הועיל אם כן בתקנתו.","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003\"צריך ואין לו תקנה\" קאמר\u0004 \u0005[הוא שאמר]\u0006 שצריך היה לעשות מחיצה של ברזל שתפסיק לחלוטין. וכיון שאי אפשר לעשות מחיצה אטומה כזו — אין לו תקנה לחרם זה ואין להשתמש במים.","\u0003אלא\u0004 מטעם אחר לא קיבל את דברי ר' חייא, \u0003משום\u0004 ש\u0003קל\u0004 (הקלה) \u0003הוא שהקילו חכמים במים\u0004 במחיצה כל שהיא ואין צריך במחיצת ברזל ובלבד שתהא בת עשרה טפחים.","וכמו שהיה בענין \u0003ר' טבלא, דבעא מיניה\u0004 \u0005[ששאל ממנו]\u0006 \u0003ר' טבלא מרב: מחיצה תלויה\u0004 המפסיקה מלמעלה אבל אינה מגיעה עד למטה, \u0003מהו שתתיר בחורבה?\u0004 והאם אפשר לומר שחלקי גגות וקירות בבית שנהרס ישמשו מחיצה אף בדרך זו.","ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: אין מחיצה תלויה מתרת אלא במים, קל הוא שהקילו חכמים במים\u0004 ומדבריו למדנו שכשם שהקלו במים לומר שאם תלויה מעל למים — דייה, כך אין צורך במחיצה של ברזל, אלא די במחיצה כל שהיא, ואפילו היא של קנים.","במשנה מובא כי \u0003חכמים אומרים\u0004 שמי שבשעת קניית השביתה ישן ולא נתכוון לשבות במקום \u0003אין לו אלא ארבע אמות\u0004. ור' יהודה אומר שיכול לבחור ארבע אמות לכל צד שירצה, ושואלים: \u0003ר' יהודה היינו\u0004 \u0005[זהו\u0006 הרי אלה\u0005]\u0006 דברי \u0003תנא קמא\u0004 \u0005[התנא הראשון,\u0006 חכמים\u0005]!\u0006","\u0003אמר רבא: שמונה על שמונה\u0004 אמות \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל להלכה\u0005]\u0006 שלדעת ר' יהודה יש לו ארבע אמות רק לצד אחד לפי בחירתו, ואילו לדברי התנא הראשון יש ארבע אמות לכל צד שירצה ובסך הכל יש לו שמונה על שמונה אמות. ואכן \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך\u0006 במפורש\u0005]:\u0006 \u0003יש לו שמונה על שמונה, דברי ר' מאיר\u0004. והוא כדברי התנא הראשון במשנתנו.","\u0003ו\u0004עוד \u0003אמר רבא: מחלוקת\u0004 זו היא לענין ההיתר \u0003להלך, אבל לטלטל — דברי הכל: ארבע אמות — אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 \u0003טפי\u0004 \u0005[יותר] —\u0006 \u0003לא.\u0004","ושואלים לעיקר ההלכה: \u0003והני\u0004 \u0005[ואלה]\u0006 \u0003ארבע אמות היכא כתיבא\u0004 \u0005[היכן כתובות]?\u0006","ומביאים \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003\"שבו איש תחתיו\u0004 אל יצא איש ממקומו ביום השביעי\u0003\"\u0004 (שמות טז, כט), הכוונה: שביום השבת אל יצא אדם ממקומו אלא יהיה מוגבל לשטח שהוא \u0003כתחתיו. וכמה\u0004 הוא \u0003תחתיו\u0004 של אדם — \u0003גופו\u0004 שיעורו כרגיל \u0003שלש אמות, ואמה\u0004 נוספת \u0003כדי לפשוט ידיו ורגליו,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר\u0004 באופן אחר: \u0003גופו שלש אמות, ואמה\u0004 נוספת \u0003כדי שיטול חפץ מתחת מרגלותיו ומניח תחת מראשותיו\u0004 כלומר, שישאר לו רווח מסויים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל הלכה למעשה \u0005ביניהם],\u0006 \u0003ועונים: איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לענין \u0003ארבע אמות מצומצמות\u0004 (בדיוק), שלדעת ר' יהודה יש רק ארבע אמות בדיוק, ולדעת ר' מאיר אין מצמצמים בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003כי עיילת לקמיה\u0004 \u0005[כאשר תבוא לפני]\u0006 \u0003רב פפא, בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ארבע אמות\u0004 שאמרו כאן, \u0003באמה דידיה יהבינן ליה\u0004 \u0005[שלו אנו נותנים לו],\u0006 כלומר לפי גודל אמת יד שלו \u0003או באמה של קדש,\u0004 האמות הרגילות הקבועות לעניני הקודש שהם של ששה טפחים בינוניים, \u0003יהבינן ליה\u0004 \u0005[נותנים אנו לו].\u0006","\u0003אם אמר לך אמות של קדש יהבינן ליה\u0004 \u0005[נותנים אנו לו]\u0006 — \u0003עוג מלך הבשן מה תהא עליו?\u0004 שגדול הוא בהרבה מתחום זה. \u0003ואם אמר לך באמה דידיה יהבינן ליה\u0004 \u0005[שלו אנו נותנים לו]\u0006 \u0003אימא ליה\u0004 \u0005[אמור לו]:\u0006 \u0003מאי טעמא לא קתני לה גבי\u0004 \u0005[מה הטעם לא שנה\u0006 אף \u0005אותה\u0006 הלכה \u0005אצל]\u0006 אותן הלכות שצרפו יחד שיעורים שונים בהלכה \u0003\"יש\u0004 שיעורים \u0003שאמרו\u0004 בהם \u0003הכל לפי מה שהוא אדם\",\u0004 שהמידה אינה קבועה ומשתנה לפי האדם העושה, ולא מנו בין ההלכות הללו גם את ארבע האמות הללו?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 בנו של רב משרשיא \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא, אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003אי דייקינן כולא האי, לא הוי תנינן\u0004 \u0005[אילו היינו מדייקים כל כך, לא היינו\u0006 יכולים \u0005ללמוד\u0006 כלל\u0005]\u0006 ואין לדייק עד כדי כך במשנתינו.","\u0003לעולם באמה דידיה יהבינן ליה\u0004 \u0005[שלו אנו נותנים לו]\u0006 \u0003ודקא קשיא\u0004 \u0005[ואשר\u0006 היה \u0005קשה]\u0006 \u0003לך מאי טעמא לא קתני גבי\u0004 \u0005[מה הטעם לא נשנה\u0006 דבר זה \u0005אצל]\u0006 אותן ההלכות שמתחילות ב\"\u0003יש שאמרו\u0004\"? טעמו של דבר — ש\u0003לא פסיקא ליה\u0004 \u0005[פסוקה\u0006 וגמורה \u0005לו]\u0006 הלכה זו, שפעמים צריך לשנות בה, \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 אדם שהוא \u0003ננס באבריו\u0004 שגופו גדול וידיו קטנות, ולאדם כגון זה אין מודדים לפי גודל אמת ידו שלו אלא באמות של קודש.","במשנה שנינו: \u0003היו שנים מקצת אמותיו של זה כו'.\u0004 שר' שמעון הביא דוגמא לדבריו לגבי שלשה שהיו בתחומים חופפים משלש חצרות. ושואלים: \u0003למה ליה למימר\u0004 \u0005[לומר]\u0006 \u0003\"למה הדבר דומה\"\u0004 ולצרף לכאן ענין אחר?","ומסבירים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 \u0003ר' שמעון לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003למה הדבר דומה — לשלש חצירות הפתוחות זו לזו, ופתוחות לרשות הרבים, מאי שנא התם דפליגיתו, ומאי שנא הכא דלא פליגיתו\u0004 \u0005[מה שונה שם שאתם חולקים\u0006 עלי (להלן עירובין דף מט,א) ואומרים שכל החצירות אסורות, \u0005ומה שונה כאן שאין אתם חולקים\u0006 עלי\u0005]?\u0006","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים: \u0003התם אוושי\u0004 \u0005[שם מרובים]\u0006 ה\u0003דיורין\u0004 שבחצירות ויתכן שיבואו אחדים מהם לטלטל במקום האסור להם. ואילו \u0003הכא לא אוושי\u0004 \u0005[כאן אין מרובים הדיורים]\u0006 ה\u0003דיורין,\u0004 שיש רק שלשה אנשים ויזהירו זה את זה מחילול שבת.","המשך דברי ר' שמעון במשנה הוא: \u0003\"ושתים החיצונות\u0004 שלא עירבו זו עם זו אסורות, ומותרות עם האמצעית\u0003\"\u0004. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003כיון\u0004 ש\u0003ערבו להו\u0004 \u0005[להם]\u0006 ה\u0003חיצונות בהדי\u0004 \u0005[עם]\u0006 ה\u0003אמצעית, הויא להו חדא\u0004 \u0005[נעשו להן\u0006 כ\u0005אחת],\u0006 שנעשו כולם כאילו דרים באמצעית ומן הדין שיהיו כולן מותרות זו עם זו!","\u0003אמר רב יהודה: כגון\u0004 שלא הניחו שתי החיצוניות עירובם באמצעית אלא להיפך \u0003שנתנה אמצעית עירובה בזו\u0004 עם אחת, \u0003ועירובה בזו\u0004 עם אחת, נמצא שהאמצעית לא נעשתה מקום עירוב של כל החצירות.","\u0003ורב ששת אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003שנתנו\u0004 החיצוניות \u0003עירובן באמצעית\u0004 ובכל זאת לא נעשו כולן כאחת, \u0003כגון שנתנוהו\u0004 לעירוב"],["\u0003בשני בתים\u0004 נפרדים, ולכן אין שתי החצרות החיצונות מתערבות יחד.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אומר רב יהודה שעירוב שהונח בשני בתים אפילו באותה חצר אינו מתערב יחד? \u0003כ\u0004שיטת \u0003בית שמאי\u0004, \u0003דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה\u0004 אנשים \u0003שגבו את עירובן ונתנוהו בשני כלים\u0004 אפילו בבית אחד, \u0003בית שמאי אומרים: אין עירובן עירוב\u0004 כיון שאין שתי יחידות העירוב ממש יחד. \u0003ובית הלל אומרים: עירובן עירוב\u0004 כל עוד הוא ברשות אחת.","ודוחים: \u0003אפילו תימא\u0004 \u0005[\u0006יכול אתה \u0005לומר]\u0006 שהדבר הוא אף כשיטת \u0003בית הלל\u0004; כי \u0003עד כאן לא קאמרי\u0004 \u0005[\u0006שמענו \u0005שאמרו]\u0006 \u0003בית הלל התם\u0004 \u0005[שם]\u0006 — \u0003אלא בשני כלים\u0004 שהיו \u0003בבית אחד\u0004 ולכן לדעתם מתערבים הם, \u0003אבל\u0004 אם היו \u0003בשני בתים\u0004 נפרדים, אפילו הם מודים ש\u0003לא,\u0004 שאין העירוב חל בשני בתים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 בעצם דיוקם של הדברים גם \u0003לרב יהודה קשיא\u0004 \u0005[קשה]\u0006 וגם \u0003לרב ששת קשיא\u0004 \u0005[קשה].\u0006 \u0003לרב יהודה קשיא\u0004 \u0005[קשה]\u0006 ש\u0003אמר: כגון שנתנה אמצעית עירובה בזו ועירובה בזו, וכיון\u0004 ש\u0003עירבה אמצעית בהדי\u0004 \u0005[עם]\u0006 ה\u0003חיצונה — הויא ליה חדא\u0004 \u0005[נעשתה אחת\u0006 עימה\u0005],\u0006 \u0003וכי הדרה\u0004 \u0005[וכאשר חזרה]\u0006 \u0003וערבה בהדי אידך\u0004 \u0005[עם האחרת] —\u0006 את \u0003שליחותה\u0004 של החצר החיצונה הראשונה \u0003עבדה\u0004 \u0005[עשתה],\u0006 שהרי נעשו שתיהן כחצר אחת.","\u0003ו\u0004אף \u0003לרב ששת קשיא\u0004 \u0005[קשה]\u0006 הדבר: שמכיון ששתי החיצוניות הניחו עירוביהן באמצעית, נעשה הדבר כאילו דרות כולן באמצעית ומכיון שכל אחת הניחה עירובה בבית אחר \u0003תיהוי\u0004 \u0005[שיהא\u0006 הדבר\u0005]\u0006 \u0003כחמשה ששרויין בחצר אחת, ושכח אחד מהם ולא עירב — דאסרי אהדדי\u0004 \u0005[שאוסרים הם זה על זה],\u0006 ואם כן לפי שיטה זו צריך שתהיה אף האמצעית אסורה ולא רק שתי החיצונות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: לא לרב יהודה קשיא\u0004 \u0005[קשה]\u0006 \u0003ולא לרב ששת קשיא\u0004 \u0005[קשה].\u0006 \u0003לרב יהודה לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כיון\u0004 ש\u0003עירבה לה\u0004 ה\u0003אמצעית בהדי\u0004 \u0005[עם]\u0006 ה\u0003חיצונה, ושתים\u0004 ה\u0003חיצונות בהדי הדדי\u0004 \u0005[זו עם זו]\u0006 \u0003לא עירבו\u0004 — \u0003גליא דעתיה דבהא ניחא ליה, ובהא לא ניחא ליה\u0004 \u0005[גילתה\u0006 החיצונה \u0005דעתה שבזו\u0006 האמצעית \u0005נוח לה, ובזו\u0006 החיצונה האחרת \u0005לא נוח לה].\u0006 וכיון שגילו החיצונות דעתם שאינם רוצים להיות מעורבים אי אפשר להכריחם.","\u0003ו\u0004אף \u0003לרב ששת לא קשיא\u0004 \u0005[קשה]\u0006 הדבר: \u0003אם אמרו\u0004 שהמערבים בחצר נעשו כאילו \u0003דיורין\u0004 בחצר \u0003להקל,\u0004 ולהתיר להם לטלטל, \u0003יאמרו\u0004 שנעשו \u0003דיורין\u0004 אף \u0003להחמיר,\u0004 ולאסור בגללם את החצר כאילו היו גרים בה?!","\u0003אמר רב יהודה אמר רב: זו\u0004 ששנינו כאן במשנתנו היא כ\u0003דברי ר' שמעון. אבל חכמים אומרים: רשות אחת משמשת לשתי רשויות\u0004 שמותר לטלטל חפצים מן החצרות החיצוניות אל החצר הפנימית, שעל החצרות החיצוניות לא חל איסור בגלל העירוב המשותף. \u0003אבל לא שתי רשויות משמשות לרשות אחת,\u0004 ואין לטלטל חפצים מן החצר האמצעית לשתי החצרות האחרות. שכלי החצר האמצעית נמשכים לשתי האחרות, ואם מכניס אותם לאחת מהן נמצא שהוציאם מרשות האחרת.","וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 הלכה \u0005זו לפני]\u0006 \u0003שמואל אמר לי:\u0004"],["\u0003אף זו\u0004 החלוקה בין שימוש החצרות זו בזו \u0003דברי ר' שמעון, אבל חכמים אומרים: שלשתן\u0004 כל החצירות כולן \u0003אסורות.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003שמואל, אמר ר' שמעון: למה הדבר דומה — לשלש חצירות הפתוחות זו לזו ופתוחות לרשות הרבים,\u0004 אם \u0003עירבו שתים\u0004 החיצונות \u0003עם האמצעית — זו מביאה מתוך ביתה ואוכלת, וזו מביאה מתוך ביתה ואוכלת\u0004. וכן להיפך: \u0003זו מחזרת מותרה\u0004 שנותר ממה שהביאה, \u0003לתוך ביתה, וזו מחזרת מותרה לתוך ביתה.\u0004","\u0003אבל חכמים אומרים: שלשתן אסורות\u0004 שכיון שאסור לבני החצרות לטלטל מחצר חיצונה אחת לחברתה, נמצא שיש מקום האסור בטלטול, ומקום אסור — אוסר את כל החצירות כולן.","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לשיטתו]\u0006 בענין זה, ש\u0003אמר שמואל: חצר שבין שני מבואות,\u0004 אם \u0003עירבה\u0004 אותה חצר \u0003עם שניהם — אסורה עם שניהם,\u0004 שהרי בני מבואות אסורים לטלטל מזה לזה, ואותה חצר כיון שמותר (על ידי העירוב) לבני שני המבואות לטלטל בה נאסרת משום כך לטלטל בהם, שלא יבואו בני המבואות האסורים זה עם זה להשתמש באותה חצר ולהעביר חפצים מזה לזה.","אם \u0003לא עירבה עם שניהם — אוסרת על שניהן,\u0004 כיון שיכולים בני אותה חצר להשתמש ולהוציא לכל מבוי ובכל מבוי הרי לא עירבה, אם כן נמצא שבכל אחד מן המבואות יש חצר אחת שלא עירבה, והיא אוסרת על כל בני המבוי.","ואולם אם \u0003היתה באחד\u0004 מהמבואות \u0003רגילה\u0004 להשתמש, \u0003ובאחד אינה רגילה, זה\u0004 (אותו מבוי) \u0003שרגילה בו — אסור,\u0004 משום שלא עירבה עמו, \u0003וזה שאינה רגילה בו — מותר,\u0004 שהרי אין שייכות ברורה של בני החצר לאותו מבוי.","\u0003אמר רבה בר רב הונא\u0004: אם \u0003עירבה\u0004 החצר \u0003עם\u0004 מבוי \u0003שאינה רגילה בו — הותר\u0004 מבוי ש\u0003רגילה\u0004 בו \u0003לעצמו,\u0004 שגילו בני החצר דעתם שכוונתם להשתמש במבוי האחר אף שאינם רגילים בשימושו.","\u0003ואמר רבה בר רב הונא אמר שמואל: אם עירבה\u0004 אותו מבוי ש\u0003רגילה\u0004 בו \u0003לעצמו וזה\u0004 אותו מבוי \u0003שאינה רגילה בו לא עירב, והיא,\u0004 אותה חצר \u0003עצמה לא עירבה\u0004 עם אף אחת מהמבואות. ונמצא שיש מבוי אחד שאסור לטלטל בו כלל בשל חוסר עירוב ומבוי אחד מותר בטלטול לדרים בו, ובני החצר בין כה וכה אסורים בטלטול בשניהם, לכן \u0003דוחין אותה\u0004 את החצר שתשתמש \u0003אצל\u0004 המבוי \u0003שאינה רגילה בו.\u0004 שכן אם תשתמש במבוי שהיא רגילה בו יאסרו בטלטול גם שאר בני המבוי כמבואר אף שעירבו את המבוי שלהם, ואם תשתמש במבוי האחר לא יפסידו בני המבוי כלום — שהרי מכיון שלא עירבו כלל הרי הם אסורים בטלטול.","\u0003וכגון זה כופין על מדת סדום\u0004 שאם אדם עושה (או נמנע מלעשות) מעשה מבלי שיביא בכך תועלת לעצמו וגורם בזה נזק לאחרים, מידה מגונה היא הקרויה מידת סדום. ובית דין יכולים להכריח אדם שלא יעשה כך, אף שאין דין מיוחד המונע אותו.","\u0003אמר רב יהודה אמר שמואל: המקפיד על עירובו\u0004 שנתן שלא יאכלוהו אחרים שנמנו עליו — \u0003אין עירובו עירוב\u0004. כי \u0003מה שמו — עירוב שמו,\u0004 שמשמעות הדבר — שצריך להיות מעורב ושייך לכולם. ואם אינו נותן לשאר הנמנים לאוכלו הרי שאינו שייך לכולם ושוב אינו קרוי עירוב.","\u0003ר' חנינא אמר:\u0004 אף כאן \u0003עירובו עירוב, אלא שנקרא\u0004 אדם כזה \u0003מאנשי\u0004 היישוב הנקרא \u0003ורדינא,\u0004 שהיו מפורסמים בקמצנותם, ואף הוא קמצן כמותם.","\u0003אמר רב יהודה אמר שמואל: החולק את עירובו\u0004 לשני חלקים — \u0003אינו עירוב\u0004 מהטעם האמור שהרי שמו \"עירוב\" ומורה שצריך להיות מעורב ולא נפרד.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 האם כשיטת \u0003בית שמאי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה שגבו את עירובן ונתנוהו בשני כלים, בית שמאי אומרים: אין זה עירוב, ובית הלל אומרים: הרי זה עירוב,\u0004 וקשה להניח שדברי שמואל הם כשיטת בית שמאי הדחויה מן ההלכה!","ומתרצים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהדבר אף כשיטת \u0003בית הלל,\u0004 וכך יש להבין: \u0003עד כאן לא קאמרי\u0004 \u0005[אמרו]\u0006 \u0003בית הלל התם\u0004 \u0005[שם]\u0006 להתיר \u0003אלא דמליין למנא ואייתר\u0004 \u0005[\u0006כ\u0005שמילאו את הכלי והותיר],\u0006 ולכן היו צריכים להכניס מקצת העירוב שנותר בכלי אחר, \u0003אבל היכא דפלגיה מיפלג\u0004 \u0005[מקום שחלקו]\u0006 מתחילה ומרצונו — \u0003לא,\u0004 ואינו עירוב אפילו לשיטת בית הלל.","ושואלים: \u0003ותרתי\u0004 \u0005[ושתיים],\u0006 שתי הלכות מאותו עקרון עצמו, \u0003למה לי?\u0004 ועונים: \u0003צריכי\u0004 \u0005[צריך]\u0006 לומר את שתיהן, \u0003דאי אשמעינן התם\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005שם\u0006 בענין המקפיד בעירוב\u0005],\u0006 היינו אומרים — \u0003משום דקפיד\u0004 \u0005[שמקפיד]\u0006 ומגלה דעתו במפורש שאינו רוצה שיאכלו עירובו. \u0003אבל הכא\u0004 \u0005[כאן\u0006 במחלק עירוב\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחשב כנפרד מן הכלל.","\u0003ואי אשמעינן הכא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק \u0005כאן] —\u0006 \u0003משום דפלגיה מיפלג\u0004 \u0005[שחלקו],\u0006 ועל ידי חלוקה זו הפריד עצמו במעשה מן השאר, \u0003אבל התם\u0004 \u0005[שם] —\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שהרי לא עשה מעשה של פירוד, ועל כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר שניהם\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אבא לרב יהודה בבי מעצרתא דבי\u0004 \u0005[בבית הבד שבבית]\u0006 \u0003רב זכאי: מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל \"החולק את עירובו — אינו עירוב\", והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: בית שמניחין בו עירוב\u0004 ארבעה אנשים שהניחו עירוביהם בבית חמישי — בעל הבית \u0003אינו צריך ליתן את הפת\u0004 לעירוב זה, ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמר\u0004 \u0005[שאמר\u0006 התכוון\u0005]\u0006 שמואל: ש\u0003כיון דמנח בסלא\u0004 \u0005[שמונח בסל] —\u0006 \u0003כמאן דמנח הכא דמי\u0004 \u0005[כמי שמונח כאן נחשב]!\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דמנח בסלא\u0004 \u0005[שמונח בסל] —\u0006 \u0003כמאן דמנח הכא דמי\u0004 \u0005[כמי שמונח כאן\u0006 בבית \u0005נחשב]\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 התיר שמואל — \u0003אף על פי שאין\u0004 בעל הבית מניח \u0003פת\u0004 כלל, \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003דכולהו הכא דיירי\u0004 \u0005[שכולם דרים כאן],\u0006 שהרי משמעות הנחת העירוב בבית היא לעשות כאילו היו גרים כולם באותו בית עצמו, ובני הבית עצמם אינם זקוקים לעירוב נוסף, שהרי הם ודאי דרים בבית זה.","\u0003אמר שמואל: עירוב\u0004 שהניחו בבית עיקרו \u0003משום קנין,\u0004 שכל אחד נותן משהו בעירוב, ועל ידי כך קונה זכות לשימוש מסוים באותה דירה ונעשה כדייר בה.","\u0003ואם תאמר: מפני מה אין קונין\u0004 זכות זו \u0003במעה\u0004 אלא בפת — \u0003מפני\u0004 שהמעה \u0003אינה מצויה בערבי שבתות;\u0004 שרבים הוציאו כל הכסף שבידם לצורכי שבת, וקשה למצוא ממון מזומן בשעה זו.","ושואלים: אם כן, לשיטת שמואל, \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003עירב\u0004 בכסף, \u0003מיהו לקני\u0004 \u0005[בכל אופן שיקנה]!\u0006 שהרי לשיטתו אין סיבה עקרונית לפסול קנין עירוב בכסף, ואין אנו מוצאים דבר כעין זה בהלכה!","ומשיבים שגם שמואל לא התיר למעשה לערב בכסף, \u0003גזירה שמא יאמרו מעה עיקר, וזימנין דלא שכיח\u0004 \u0005[ופעמים שאין מצויה]\u0006 \u0003מעה, ולא אתי לאיערובי\u0004 \u0005[ולא יבוא לערב]\u0006 \u0003בפת, דאתי\u0004 \u0005[ויבוא\u0006 על ידי כך\u0005]\u0006 ה\u0003עירוב לאיקלקולי\u0004 \u0005[להתקלקל]\u0006 שיחשבו שעיקר העירוב במעה ובאין מעה לא יערבו בכלל — ותשתכח תורת עירוב.","\u0003רבה אמר: עירוב משום דירה\u0004 שכל אחד שם מקצת מאכלו באותה דירה, והרי זה לגביו כאילו היה דר בדירה זו באותה שבת.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה? ועונים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לענין עירוב ב\u0003כלי,\u0004 שאם עיקר עירוב הוא משום קנין הרי לדעת שמואל אפשר לקנות בכלי (קנין חליפין) ולאו דוקא בכסף, ולדעת רבה אין זה עירוב.","\u0003ו\u0004כן יש הבדל ביניהם אם עירבו ב\u0003פחות משוה פרוטה\u0004 שלדעת שמואל אינו עירוב שאין קנין בפחות מפרוטה, ולדעת רבה כיון שהעירוב מתיר מפני שעל ידו קובע מקום דירתו שם הרי אף בפחות משווה פרוטה יכול לקבוע שם דירתו."],["\u0003וקטן\u0004 אם אחד מבעלי הבתים שבחצר היה קטן אין הוא יכול להקנות רשות ביתו, וממילא אי אפשר לערב עמו (ר\"ח)","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 \u0003ו\u0004אף \u0003ל\u0004שיטת \u0003שמואל קשיא\u0004 \u0005[קשה].\u0006 \u0003הא תניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה שגבו את עירובן כשהם מוליכין את עירובן למקום אחר\u0004 שרצו לערב עם חצר אחרת וצריכים להניח את העירוב בתוכה \u0003— אחד מוליך לכולן\u0004. משמע: \u0003הוא ניהו דקא קני, ותו לא\u0004 \u0005[הוא זה שקנה, ולא עוד].\u0006 \u0003הוא ניהו דקא דייר, ותו לא\u0004 \u0005[הוא זה שגר, ולא עוד]\u0006 וכיצד יכולים האחרים להשתמש בעירוב זה?!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003לא לדידי קשיא\u0004 \u0005[לי קשה],\u0006 \u0003ולא לשמואל קשיא\u0004 \u0005[קשה],\u0006 כי בענין זה \u0003שליחות דכולהו קא עביד\u0004 \u0005[של כולם הוא עושה]\u0006 קובע דירה או קונה מקום בשביל כולם.","ולענין שלש חצירות שעסקנו בו \u0003אמר רבה אמר רב חמא בר גוריא אמר רב: הלכה כר' שמעון\u0004 שמותרות כל שלושת החצירות זו בזו.","\u0003מי שבא בדרך וחשכה לו, והיה מכיר אילן או גדר\u0004 הנמצאים בסוף אלפיים אמה ממקום שהוא עומד, ומאותו אילן עד ביתו כאלפיים אמה, \u0003ואמר: \"שביתתי תחתיו\"\u0004 תחת אילן זה, שרצוני לקנות שביתה לא במקום זה שאני מצוי בו כעת אלא שם, תחת האילן — \u0003לא אמר כלום,\u0004 כיון שלא קבע את שביתתו במקום מוגדר.","אולם אם אמר: \u0003\"שביתתי בעיקרו\"\u0004 ליד גזעו של אותו אילן — קנה שביתה שם. ו\u0003מהלך ממקום רגליו ועד עיקרו\u0004 של האילן \u0003אלפים אמה, ו\u0004אף מותר לו להלך \u0003מעיקרו\u0004 של האילן \u0003ועד ביתו אלפים אמה. נמצא מהלך משחשיכה ארבעת אלפים אמה.\u0004","\u0003אם אינו מכיר\u0004 אילן או מקום מסוים אחר, \u0003או שאינו בקי בהלכה\u0004 ואינו יודע שאפשר לקנות שביתה במקום רחוק, \u0003ואמר \"שביתתי במקומי\" — זכה לו מקומו אלפים אמה לכל רוח\u0004.","בעיקר שיעורן של אלפיים אמות אלה נחלקו חכמים, יש אומרים שאלפיים אמה אלה הן \u0003עגולות\u0004 כלומר אלפיים אמה לכל צד, אלו \u0003דברי ר' חנינא בן אנטיגנוס, וחכמים אומרים:\u0004 אלפיים אמה אלה הן \u0003מרובעות,\u0004 שנותנים לו ממקומו \u0003כ\u0004עין \u0003טבלא מרובעת\u0004 שבארבעה כיוונים יש לו אלפיים אמה לכל ארכם, \u0003כדי שיהיה נשכר לזויות,\u0004 וניתנת לו רשות להלך בזויות כאלפיים ושמונה מאות אמה.","\u0003וזו היא שאמרו: העני מערב ברגליו\u0004. שיכול אדם כגון זה שאין פת לעירוב ברשותו לקנות שביתה כשנמצא בתוך תחום ואומר: קובע אני שביתתי במקום זה, \u0003אמר ר' מאיר: אנו אין לנו אלא עני\u0004 שיכול לעשות כן שהקלו עליו חכמים, אבל מי שיש פת בידו אינו יכול לקנות שביתה בדרך זו, אלא בפת. ואילו \u0003ר' יהודה אומר: אחד עני ואחד עשיר\u0004 יכולים להשתמש בדרך זו של עירוב, \u0003לא אמרו מערבין בפת אלא להקל על העשיר, שלא\u0004 יטרח ו\u0003יצא ויערב ברגליו,\u0004 שאין הוא צריך לכך, אלא יוכל גם לשלוח שליח שיניח לו פת באותו מקום. אבל לא נתבטלה האפשרות שהוא עצמו ילך למקום ויקנה בו שביתה בלי פת.","במשנה נאמר שהקובע שביתה תחת האילן ולא הגדיר בדיוק היכן, לא אמר כלום ודנו בשאלה: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 בדיוק \u0003\"לא אמר כלום\"?\u0004","\u0003אמר רב: לא אמר כלום כל עיקר,\u0004 ולא קנה כל שביתה ש\u0003אפילו לתחתיו של\u0004 אותו \u0003אילן לא מצי אזיל\u0004 \u0005[אינו יכול ללכת],\u0006 שלא קנה שביתה תחת האילן משום שלא ציין מקום מסויים. ולא קנה במקומו — משום שאמר שרצונו בשביתה במקום אחר ועקר בדבריו את עצמו ממנו, ולכן אין לו אלא ארבע אמות.","\u0003ושמואל אמר: לא אמר כלום\u0004 כלומר שאינו יכול ללכת מכאן \u0003לביתו\u0004 אם הוא רחוק אלפיים אמה מן האילן, \u0003אבל לתחתיו של אילן\u0004 אם כל נופו נוטה לתוך אלפיים אמה למקומו \u0003מצי אזיל\u0004 \u0005[יכול ללכת].\u0006","ומה שאמרו שלא קנה שביתה משמעו רק ש\u0003נעשה תחתיו של אילן חמר גמל\u0004 שמושכים אותו כל אחד לצד אחר, וכמו כן מכיון שלא קבע לו שם מקום מסויים, אומרים שיש לחשוש בכל חלק שמתחת לאילן שמא הוא המקום שקנה בו שביתה ומושכו אליו.","ולכן אם \u0003בא למדוד מן הצפון\u0004 שבאילן זה כדי להגיע משם לביתו, אומרים לו: שמא לא כאן קבעת — ו\u0003מודדין לו\u0004 רק \u0003מן הדרום\u0004 להחמיר, וכן אם \u0003בא למדוד מן הדרום — מודדין לו מן הצפון.\u0004"]]};
